def require_authenticated_actor_binding(
    project_id: str,
    actor: str,
    permission: str,
    connection=None,
) -> None:
    if identity_guard.identity_enforced():
        # The guard decided this request against the catalogue (enforce) and REPLACED the claimed
        # actor with the verified principal's (identity_guard._bind_actor, F2/H7). An actor that
        # still differs reached the handler some other way: refuse it, never act as it.
        expected = identity_guard.request_actor()
        if expected and actor and actor != expected and not identity_guard.is_worker_principal(
                identity_guard.REQUEST_IDENTITY.get()):
            raise HTTPException(status_code=403, detail={
                "error": "forbidden", "reason": "actor_mismatch",
                "message": "the actor is the signed-in principal; it cannot be named"})
        return
    principal = current_api_principal.get()
    if not principal:
        if current_transport_authenticated.get():
            raise HTTPException(
                status_code=403,
                detail="Authenticated API request has no project member principal.",
            )
        return
    if principal == actor:
        return
    approved_human = current_mcp_human_attribution.get()
    if (approved_human == (project_id, actor, principal)
            and current_transport_authenticated.get()
            and current_auth_method.get() == "api_key"):
        return
    # Bounded delegation: allow the authenticated principal to act as a member whose
    # role_keys explicitly include the principal — e.g. the console's system actor
    # 'executive_console' carries role_keys ['ceo', 'ceo_delegate'], so a 'ceo' key
    # may act as it. This is NOT arbitrary impersonation: the target actor must carry
    # the principal as one of its roles. Without a connection to check roles, fall
    # back to the strict principal == actor rule.
    if connection is not None:
        try:
            member = members.get_member(connection, project_id, actor)
            role_keys = (member or {}).get("role_keys") or []
        except Exception:  # noqa: BLE001 — any lookup failure ⇒ no delegation
            role_keys = []
        if principal in role_keys:
            return
    reason = (
        f"Authenticated principal '{principal}' is not allowed to act as "
        f"'{actor}'."
    )
    record_policy_denial(project_id, principal, permission, reason)
    raise HTTPException(status_code=403, detail=reason)


def require_project_actor(connection, project_id: str, actor: str, permission: str) -> None:
    # Authenticate the claimed actor before inspecting its permissions. Checking
    # permissions first can turn an impersonation attempt into a target-member
    # error and bypass the principal-specific denial evidence.
    require_authenticated_actor_binding(project_id, actor, permission, connection)
    if identity_guard.identity_enforced():
        return   # the route's catalogue permission was checked at this project by the guard
    try:
        members.require_member(
            connection,
            project_id,
            actor,
            permission=permission,
        )
    except (ProjectMemberNotFoundError, ProjectMemberPermissionError) as error:
        # Membership and permission changes are operator decisions. Never seed
        # defaults during authorization: it can reactivate revoked baseline rows
        # (including the CEO) and grant back permissions removed by an operator.
        record_policy_denial(project_id, actor, permission, str(error))
        raise HTTPException(status_code=403, detail=str(error)) from error


def _may_act_as(connection, project_id: str, actor: str) -> bool:
    """May this request's principal act as `actor`? The same answer
    require_authenticated_actor_binding gives, without recording a denial: no principal (auth
    off), the principal itself, or a member whose role_keys name the principal (the console's
    `executive_console` carries `ceo`, so the console's key may act as it)."""
    principal = current_api_principal.get()
    if identity_guard.identity_enforced():
        # an identity principal is only itself (F2/H7: its actor, never a claimed one)
        return actor == (identity_guard.request_actor() or principal)
    if not principal or principal == actor:
        return True
    try:
        member = members.get_member(connection, project_id, actor)
    except Exception:  # noqa: BLE001 — no member, no delegation
        return False
    return principal in ((member or {}).get("role_keys") or [])


def signed_in_actor(connection, project_id: str, claimed: str | None) -> str:
    """THE ONE ACTOR RULE (govern_guard.govern_actor's, bound): the signed-in operator the
    console names is who acted — when this key may act as them — else the key's principal.

    Plans, approvals and redeploys of one deploy were recorded as three different people: the
    plan as the operator the console named, the approval as the key's principal (`ceo`), the
    redeploy as whichever route it went through. An exact MCP confirmation still records its
    independently authenticated reviewer."""
    claimed = str(claimed or "").strip()
    if identity_guard.request_actor():
        return identity_guard.request_actor()   # F2/H7: under enforce the actor is the principal
    if current_mcp_human_attribution.get():
        return _decision_action_actor(claimed)
    if claimed and _may_act_as(connection, project_id, claimed):
        return claimed
    return str(current_api_principal.get() or claimed or "").strip()


def _decision_route_actor(connection, decision_id: str, claimed: str | None) -> str:
    row = connection.execute(text("SELECT project_id FROM decisions WHERE id = :d"),
                             {"d": decision_id}).mappings().first()
    if not row:
        return _decision_action_actor(claimed)
    return signed_in_actor(connection, row["project_id"], claimed)


def require_project_write_actor(
    connection, project_id: str, claimed_actor: str | None, permission: str,
) -> str:
    """Bind a project mutation to the authenticated member and its permission."""
    actor = signed_in_actor(connection, project_id, claimed_actor)
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    require_project_actor(connection, project_id, actor, permission)
    return actor


def require_autonomy_operator(connection, project_id: str, claimed_actor: str | None) -> str:
    """Only a human CEO may change or apply the policy that resolves gates."""
    claimed = str(claimed_actor or "").strip()
    if identity_guard.identity_enforced():
        # policy:manage (or the route's key) was checked by the guard; the actor recorded is
        # the authenticated principal, never the claimed one.
        return signed_in_actor(connection, project_id, claimed_actor)
    if current_mcp_human_attribution.get():
        actor = _decision_action_actor(claimed)
        require_project_actor(connection, project_id, actor, "decision_resolve")
    else:
        actor = require_project_write_actor(
            connection, project_id, claimed_actor, "decision_resolve"
        )
    try:
        member = members.require_member(
            connection, project_id, actor, role_keys_any=["ceo"]
        )
    except (ProjectMemberNotFoundError, ProjectMemberPermissionError) as error:
        record_policy_denial(project_id, actor, "autonomy_manage", str(error))
        raise HTTPException(status_code=403, detail=str(error)) from error
    if member.get("member_type") != "human":
        reason = "A human CEO member is required to change autonomy policy."
        record_policy_denial(project_id, actor, "autonomy_manage", reason)
        raise HTTPException(status_code=403, detail=reason)
    return actor


def require_project_reader(connection, project_id: str) -> None:
    """Limit project-scoped reads to an active member of that project or its org."""
    if identity_guard.identity_enforced():
        return   # the guard checked the route's read permission at this project
    if not current_transport_authenticated.get():
        # Explicitly unauthenticated local development keeps its existing behavior.
        return
    exists = connection.execute(
        text("SELECT 1 FROM projects WHERE id = :project_id"),
        {"project_id": project_id},
    ).scalar()
    if not exists:
        raise HTTPException(status_code=404, detail="Project not found.")
    principal = current_api_principal.get()
    if not principal:
        raise HTTPException(status_code=403, detail="Project member principal required.")
    try:
        members.require_member(connection, project_id, principal)
    except (ProjectMemberNotFoundError, ProjectMemberPermissionError) as error:
        record_policy_denial(project_id, principal, "project_read", str(error))
        raise HTTPException(status_code=403, detail=str(error)) from error


