def require_decision_actor_binding(
    connection,
    decision_id: str,
    actor: str,
) -> None:
    row = connection.execute(
        text("SELECT project_id FROM decisions WHERE id = :decision_id"),
        {"decision_id": decision_id},
    ).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="Decision not found")
    # With the connection, so the bounded delegation every other write honours applies here
    # too: the console's key may answer as the operator signed in to it (`executive_console`
    # carries `ceo`), and as nobody else.
    require_authenticated_actor_binding(row["project_id"], actor, "decision_resolve",
                                        connection)


def raise_project_actor_error(error: Exception) -> None:
    raise HTTPException(status_code=403, detail=str(error)) from error


def raise_decision_actor_error(
    decision_id: str, actor: str, error: Exception
) -> None:
    try:
        with begin(engine) as audit_connection:
            row = audit_connection.execute(
                text("SELECT project_id FROM decisions WHERE id = :decision_id"),
                {"decision_id": decision_id},
            ).mappings().first()
            if row:
                emit_event(
                    audit_connection,
                    row["project_id"],
                    "policy.denied",
                    actor,
                    "decision",
                    decision_id,
                    {
                        "permission": "decision_resolve",
                        "reason": str(error),
                    },
                )
    except Exception as audit_error:
        LOGGER.exception(
            "policy_denial_audit_write_failed decision_id=%s actor=%s reason=%s",
            decision_id,
            actor,
            error,
            exc_info=audit_error,
        )
    raise HTTPException(status_code=403, detail=str(error)) from error


def resolve_list_project_id(project_id: Optional[str] = None) -> str:
    """Default omitted list ``project_id`` to the configured Community project.

    Single-tenant Community operators (and gates) often hit ``GET /v1/tasks``
    without a query string. Fail closed only when no default is configured —
    never invent a project, never 500.
    """
    resolved = str(project_id or "").strip() or str(
        getattr(settings, "default_project_id", "") or ""
    ).strip()
    if not resolved:
        raise HTTPException(status_code=422, detail="project_id is required.")
    return resolved


def record_policy_denial(
    project_id: str, actor: str, permission: str, reason: str
) -> None:
    try:
        with begin(engine) as audit_connection:
            project_exists = audit_connection.execute(
                text("SELECT 1 FROM projects WHERE id = :project_id"),
                {"project_id": project_id},
            ).first()
            if not project_exists:
                return
            emit_event(
                audit_connection,
                project_id,
                "policy.denied",
                actor,
                "project",
                project_id,
                {
                    "permission": permission,
                    "reason": reason,
                },
            )
    except Exception as audit_error:
        LOGGER.exception(
            "policy_denial_audit_write_failed project_id=%s actor=%s permission=%s reason=%s",
            project_id,
            actor,
            permission,
            reason,
            exc_info=audit_error,
        )
        return


