def reload_inbox_message(connection, message_id: str) -> dict:
    row = connection.execute(
        text(
            """
            SELECT id, project_id, channel, raw_ref, subject, body, status, parsed,
                   data_boundary, created_at, updated_at
            FROM inbox_messages
            WHERE id = :message_id
            """
        ),
        {"message_id": message_id},
    ).mappings().one()
    return dict(row)


