def catalog_read_scope() -> tuple[bool, str]:
    """Return the authenticated member for catalog filtering.

    Local deployments that explicitly disable transport auth keep the existing
    all-project operator catalog. Authenticated requests must have a member
    principal, even if the endpoint is called outside the auth middleware.
    """
    if identity_guard.identity_enforced():
        # Enforced: legacy memberships no longer name who may read; both callers filter the rows
        # by the caller's own project:read (identity_access.readable_projects, §6.7).
        return False, ""
    if not current_transport_authenticated.get():
        return False, ""
    principal = current_api_principal.get()
    if not principal:
        raise HTTPException(status_code=403, detail="Project member principal required.")
    return True, principal


@app.get("/v1/orgs")
@authenticated(note="SQL filters orgs to those with a project where the principal is an active project/org memb")
def list_orgs(request: Request):
    """Organizations with a project this caller may read, for the org picker."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    authenticated, principal = catalog_read_scope()
    with begin(engine) as connection:
        rows = connection.execute(
            text(
                """
                WITH accessible_projects AS (
                    SELECT o.id AS org_id, o.name AS org_name,
                           o.created_at AS org_created_at,
                           p.id AS project_id, p.name AS project_name,
                           p.slug AS project_slug, w.name AS workspace_name,
                           ROW_NUMBER() OVER (
                               PARTITION BY o.id ORDER BY p.created_at, p.id
                           ) AS project_rank
                    FROM orgs o
                    JOIN workspaces w ON w.org_id = o.id
                    JOIN projects p ON p.workspace_id = w.id
                    WHERE NOT :authenticated
                       OR EXISTS (
                           SELECT 1 FROM project_members pm
                           WHERE pm.project_id = p.id
                             AND pm.member_id = :principal AND pm.status = 'active'
                       )
                       OR EXISTS (
                           SELECT 1 FROM org_members om
                           WHERE om.org_id = o.id
                             AND om.member_id = :principal AND om.status = 'active'
                             AND NOT EXISTS (
                                 SELECT 1 FROM project_members pm_override
                                 WHERE pm_override.project_id = p.id
                                   AND pm_override.member_id = :principal
                             )
                       )
                )
                SELECT ap.org_id, ap.org_name, ap.org_created_at AS created_at,
                       ap.project_id, ap.project_name, ap.project_slug,
                       ap.workspace_name,
                       (SELECT count(*) FROM tasks t WHERE t.project_id = ap.project_id)
                           AS task_count,
                       (SELECT count(*) FROM meetings m WHERE m.project_id = ap.project_id)
                           AS meeting_count
                FROM accessible_projects ap
                WHERE (:all_ranks OR ap.project_rank = 1)
                ORDER BY ap.org_created_at, ap.org_id, ap.project_rank
                """
            ),
            {"authenticated": authenticated, "principal": principal,
             "all_ranks": identity_guard.identity_enforced()},
        ).mappings().all()
        # IDENTITY (S2): only the caller's org, only projects it holds project:read in.
        visible = _readable_projects(request, [r["project_id"] for r in rows])
        if visible is not None:
            # Each org once, at the first project the caller may read (not the org's first).
            first: dict[str, Any] = {}
            for r in rows:
                if r["project_id"] in visible:
                    first.setdefault(r["org_id"], r)
            rows = list(first.values())
        return {
            "items": [
                {
                    "org_id": r["org_id"],
                    "org_name": r["org_name"],
                    "created_at": r["created_at"].isoformat() if hasattr(r["created_at"], "isoformat") else r["created_at"],
                    "project_id": r["project_id"],
                    "project_name": r["project_name"],
                    "project_slug": r["project_slug"],
                    "workspace_name": r["workspace_name"],
                    "task_count": int(r["task_count"] or 0),
                    "meeting_count": int(r["meeting_count"] or 0),
                }
                for r in rows
                if visible is None or r["project_id"] in visible
            ]
        }


@app.post("/v1/orgs", status_code=201)
@permit(P.ORG_UPDATE, scope=Scope.org())
def onboard_org_endpoint(payload: OrgOnboardBody):
    """Onboard a new organization: create org → workspace → project and seed it
    with the common defaults (budget policy, members, packs, agent modules,
    entitlement sources, MCP servers). No auth yet — this is the admin action."""
    if identity_guard.identity_enforced():
        # F2/M5: identity is one org per install. A second org would have no Owner, no bindings
        # and no claim, and nothing in BOSS yet keeps two orgs apart end to end.
        raise HTTPException(status_code=409, detail={
            "error": "single_org", "message": "This BOSS runs one organization."})
    payload = payload.payload()
    name = str(payload.get("name") or "").strip()
    if not name:
        raise HTTPException(status_code=422, detail="Organization name is required.")
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .bootstrap import onboard_org
    with begin(engine) as connection:
        principal = current_api_principal.get()
        if principal and current_transport_authenticated.get():
            member = connection.execute(
                text(
                    """
                    SELECT 1 FROM project_members
                    WHERE member_id = :member_id AND status = 'active'
                    LIMIT 1
                    """
                ),
                {"member_id": principal},
            ).first()
            if not member:
                raise HTTPException(
                    status_code=403,
                    detail="Authenticated principal must already belong to a project.",
                )
        result = onboard_org(
            connection, settings, name,
            entitlements=entitlements, members=members, specpack=specpack,
        )
        # A clearly-labeled welcome task so a brand-new org isn't empty in Work/Overview.
        intake.create_task(
            connection,
            project_id=result["project_id"],
            title=f"👋 Welcome to BOSS, {name} — issue your first command",
            description=(
                "Your organization is set up with the shared capabilities (tools, skills, MCP servers, "
                "meeting roles) and a budget policy. Get started:\n"
                "• Overview → issue a CEO command and BOSS will plan it, gating any real effect behind your approval.\n"
                "• Meetings → convene a cross-functional agent panel to debate and draft a PRD.\n"
                "• Capabilities → review the tools and skills your agents can use, and plug in your own MCP servers.\n"
                "You can close this task once you're oriented."
            ),
            # ONE welcome task per project, ever. A random key here meant re-running org
            # setup handed the operator another copy of the same onboarding card.
            dedupe_key=stable_dedupe_key("welcome", result["project_id"]),
            priority="p3",
            risk_tier=0,
            data_boundary="internal",
        )
        _record_governed(
            connection,
            project_id=result["project_id"],
            actor=principal or "onboarding",
            effect_kind="org.onboard",
            dedupe_parts=[result["org_id"]],
            payload={"name": name, "org_id": result["org_id"]},
        )
    return result


@app.get("/v1/projects", response_model=ProjectListResponse)
@authenticated(note="SQL filters projects to the principal's active project/org memberships (catalog_read_scope")
def list_projects(request: Request) -> ProjectListResponse:
    authenticated, principal = catalog_read_scope()
    with begin(engine) as connection:
        rows = connection.execute(
            text(
                """
                SELECT p.id, p.name, p.slug, p.workspace_id, p.created_at,
                       w.name AS workspace_name, o.id AS org_id, o.name AS org_name
                FROM projects p
                JOIN workspaces w ON w.id = p.workspace_id
                JOIN orgs o ON o.id = w.org_id
                WHERE NOT :authenticated
                   OR EXISTS (
                       SELECT 1 FROM project_members pm
                       WHERE pm.project_id = p.id
                         AND pm.member_id = :principal AND pm.status = 'active'
                   )
                   OR EXISTS (
                       SELECT 1 FROM org_members om
                       WHERE om.org_id = o.id
                         AND om.member_id = :principal AND om.status = 'active'
                         AND NOT EXISTS (
                             SELECT 1 FROM project_members pm_override
                             WHERE pm_override.project_id = p.id
                               AND pm_override.member_id = :principal
                         )
                   )
                ORDER BY o.name ASC, w.name ASC, p.name ASC
                """
            ),
            {"authenticated": authenticated, "principal": principal},
        ).mappings().all()
        # IDENTITY (S2): only projects the caller holds project:read in (§6.7).
        visible = _readable_projects(request, [str(row["id"]) for row in rows])
        return ProjectListResponse(
            items=[project_summary_from_row(row) for row in rows
                   if visible is None or str(row["id"]) in visible]
        )


