@app.post(
    "/v1/webhooks/inbound/{source}",
    response_model=InboundWebhookResponse,
    status_code=202,
)
@public(reason=PublicReason.HMAC_SIGNED_WEBHOOK, verifier=_identity_verifiers.inbound_webhook_hmac)
async def receive_inbound_webhook(
    source: str,
    request: Request,
) -> InboundWebhookResponse:
    raw_body = await request.body()
    headers = {key.lower(): value for key, value in request.headers.items()}
    with begin(engine) as connection:
        result = inbound_webhooks.ingest(
            connection,
            source,
            raw_body,
            headers,
        )
        if (
            source.strip().lower() == "github"
            and result["status"] == "accepted"
            and result.get("inbound_webhook_id")
        ):
            github_reconciler.ingest_inbound_webhook(
                connection,
                inbound_webhook_id=result["inbound_webhook_id"],
            )
    if result["status"] == "rejected":
        raise HTTPException(status_code=401, detail="Invalid webhook signature.")
    if result["status"] == "not_configured":
        raise HTTPException(status_code=503, detail="Webhook source is not configured.")
    if result["status"] == "invalid":
        raise HTTPException(status_code=400, detail="Invalid webhook payload.")
    return InboundWebhookResponse(**result)


@app.post("/v1/webhooks/github", status_code=202)
@public(reason=PublicReason.HMAC_SIGNED_WEBHOOK, verifier=_identity_verifiers.inbound_webhook_hmac)
async def receive_github_webhook(request: Request):
    """Compatibility GitHub ingress with the community event allowlist."""
    raw_body = await request.body()
    headers = {key.lower(): value for key, value in request.headers.items()}
    with begin(engine) as connection:
        result = inbound_webhooks.ingest(
            connection,
            "github",
            raw_body,
            headers,
            github_community_only=True,
        )
        if result["status"] == "accepted" and result.get("inbound_webhook_id"):
            github_reconciler.ingest_inbound_webhook(
                connection,
                inbound_webhook_id=result["inbound_webhook_id"],
            )
    if result["status"] == "rejected":
        raise HTTPException(status_code=401, detail="Invalid webhook signature.")
    if result["status"] == "not_configured":
        raise HTTPException(status_code=503, detail="Webhook source is not configured.")
    if result["status"] == "invalid":
        raise HTTPException(status_code=400, detail="Invalid webhook payload.")
    if result["status"] in {"unrouted", "ignored"}:
        return Response(status_code=204)
    return JSONResponse(
        status_code=202,
        content=InboundWebhookResponse(**result).model_dump(mode="json"),
    )


