@app.post("/v1/code-tasks")
@permit(P.CODE_TASK_CREATE, scope=Scope.project(body="project_id"),
        confine=(Confine.body("task_id", "task"),
                 Confine.body("workflow_version_id", "workflow_version")))
def start_code_task_endpoint(payload: CodeTaskStartBody):
    """Convene a durable coding task: clone -> agent edits + tests -> gated PR.
    Returns the run_id; a `code.task` worker picks it up and runs the pipeline.

    ``simulated=true`` is a no-spend fixture: persist a labeled run with fixture
    evidence and do not enqueue a job, reserve budget, or call a model. It is
    not a sealed factory path. ``open_pr=true`` with ``simulated=true`` is 422.
    """
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    project_id = payload.get("project_id")
    if not project_id:
        raise HTTPException(status_code=422, detail="project_id is required.")
    simulated = bool(payload.get("simulated"))
    actor = str(payload.get("actor") or current_api_principal.get() or "ceo")
    from .services.code_task_service import start_code_task
    try:
        with begin(engine) as c:
            require_project_actor(c, project_id, actor, "workflow_execute")
            run_id = start_code_task(
                c, project_id=project_id, task_id=payload.get("task_id"),
                title=payload.get("title") or "Code task",
                instructions=payload.get("instructions") or "",
                acceptance_criteria=payload.get("acceptance_criteria") or [],
                test_commands=payload.get("test_commands") or [],
                owner=payload.get("owner") or (
                    "_fixture" if simulated else settings.target_github_owner
                ),
                repo=payload.get("repo") or (
                    "_fixture" if simulated else settings.target_github_repo
                ),
                base_branch=payload.get("base_branch") or "main",
                # THE WORKFLOW THE OPERATOR PICKED, if they picked one. Carried on
                # finalize_ctx rather than a new parameter: start_code_task already threads
                # that dict through to the run row, and the engine pops the id, resolves it
                # against THIS project, and records the workflow it names.
                finalize_ctx={
                    **(payload.get("finalize_ctx") or {}),
                    **({"workflow_version_id": payload["workflow_version_id"]}
                       if payload.get("workflow_version_id") else {}),
                },
                jobs=jobs,
                profile=payload.get("profile"),
                risk_tier=payload.get("risk_tier"),
                model_config=None if simulated else payload.get("model_config"),
                open_pr=payload.get("open_pr"),
                repair_retries=payload.get("repair_retries"),
                review_panel_size=payload.get("review_panel_size"),
                simulated=simulated,
                # RUN AS AN AGENT: its held MCP servers reach the harness (skills-mcp E6).
                role_key=payload.get("role_key"),
            )
    except ValueError as error:
        # Preflight rejections (e.g. non-allowlisted test executables) are the CALLER's
        # problem to fix, not a server fault — return the actionable message, not a 500.
        raise HTTPException(status_code=422, detail=str(error)) from error

    if simulated:
        return {
            "status": "simulated",
            "run_id": run_id,
            "simulated": True,
            "job_enqueued": False,
            "note": (
                "Simulated fixture — no model, no budget reservation, no code.task job. "
                "This is not a sealed factory path."
            ),
        }
    swarm = None
    fctx = payload.get("finalize_ctx") or {}
    official = bool(payload.get("official") or fctx.get("official") or fctx.get("qa_benchmark"))
    if official:
        try:
            from boss_engine.services.agent_process import bind_captain_swarm

            with begin(engine) as c:
                swarm = bind_captain_swarm(
                    c,
                    settings=settings,
                    project_id=project_id,
                    actor=actor,
                    prd=str(payload.get("instructions") or payload.get("title") or "Official factory run"),
                    title=f"Captain swarm — {payload.get('title') or 'official'}",
                    attach_run_id=run_id,
                    official=True,
                    engine=(
                        ((payload.get("model_config") or {}).get("default") or {}).get("engine")
                    ),
                    review_panel_size=payload.get("review_panel_size")
                    if isinstance(payload.get("review_panel_size"), int) else 5,
                    qa_benchmark=fctx.get("qa_benchmark")
                    if isinstance(fctx.get("qa_benchmark"), dict) else None,
                )
        except Exception:  # noqa: BLE001
            swarm = None
    # THE OUTER RUN, so the console can take the operator straight to it. Written into
    # finalize_ctx by start_code_task — read back rather than plumbed through a return value,
    # because every creation path goes through that one function and only some of them are
    # this endpoint.
    workflow_run_id = None
    try:
        with begin(engine) as c:
            workflow_run_id = c.execute(
                text("SELECT finalize_ctx->>'workflow_run_id' FROM code_task_runs WHERE id = :r"),
                {"r": run_id},
            ).scalar()
    except Exception as error:  # noqa: BLE001 — the project started; this is only navigation
        LOGGER.warning("could not read the workflow run for %s: %s", run_id, error)
    return {
        "status": "queued",
        "run_id": run_id,
        "workflow_run_id": workflow_run_id,
        "process_run_id": (swarm or {}).get("id") if isinstance(swarm, dict) else None,
    }


@app.post("/v1/prd/decompose", status_code=201)
@permit(P.CODE_TASK_CREATE, scope=Scope.project(body="project_id"))
def decompose_prd_endpoint(payload: PrdDecomposeBody):
    """Autonomous PRD -> scoped coding tasks -> build. BOSS reads a PRD (or a feature directive),
    decomposes it into a SMALL ordered set of composable coding tasks, and runs them as ONE branch
    lineage (scaffold -> features -> wire-up) — each task auto-starts when the prior lands. Body:
    {project_id, prd | directive, owner?, repo?, base_branch?, task_id?, profile?, risk_tier?,
    max_tasks?, plan_only?}. plan_only=true returns the decomposition WITHOUT starting the build."""
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    project_id = payload.get("project_id")
    if not project_id:
        raise HTTPException(status_code=422, detail="project_id is required.")
    prd = (payload.get("prd") or payload.get("directive") or "").strip()
    if not prd:
        raise HTTPException(status_code=422, detail="prd (or directive) is required.")
    actor = str(payload.get("actor") or current_api_principal.get() or "ceo")
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "workflow_execute")
    from .services.prd_decomposition import decompose_prd_into_tasks, start_decomposed_build
    max_tasks = int(payload.get("max_tasks") or 6)
    if payload.get("plan_only"):
        from boss_engine.services import model_routing

        with begin(engine) as connection:
            model = model_routing.project_chat_adapter(connection, settings, project_id)
        tasks = decompose_prd_into_tasks(settings, prd, max_tasks=max_tasks, adapter=model)
        if not tasks:
            raise HTTPException(status_code=422, detail="could not decompose the PRD into tasks.")
        return {"plan_only": True, "total": len(tasks), "tasks": tasks}
    result = start_decomposed_build(
        engine, settings, jobs, project_id=project_id, task_id=payload.get("task_id"),
        prd_or_directive=prd,
        owner=payload.get("owner") or settings.target_github_owner,
        repo=payload.get("repo") or settings.target_github_repo,
        base_branch=payload.get("base_branch") or "main",
        profile=payload.get("profile"), risk_tier=payload.get("risk_tier"), max_tasks=max_tasks)
    if not result.get("started"):
        raise HTTPException(status_code=422, detail=result.get("reason") or "decomposition failed.")
    return result


@app.post("/v1/web-app", status_code=201)
@permit(P.CODE_TASK_CREATE, scope=Scope.project(body="project_id"))
def build_web_app_endpoint(payload: WebAppBuildBody):
    """SINGLE-TASK web-app build — the robust path for a website. Seeds a deterministic
    Vite+React+TS+Tailwind scaffold (0 agent turns), then ONE governed task builds the whole app on
    top (fits the guest turn cap; no fragile decomposition chain). Body: {project_id, directive,
    owner?, repo?, task_id?, review?}. review defaults to false so the FIRST pass just works."""
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    project_id = payload.get("project_id")
    directive = (payload.get("directive") or payload.get("prd") or "").strip()
    if not project_id or not directive:
        raise HTTPException(status_code=422, detail="project_id and directive are required.")
    actor = str(payload.get("actor") or current_api_principal.get() or "ceo")
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "workflow_execute")
    from .services.prd_decomposition import start_web_app_build
    return start_web_app_build(
        engine, settings, jobs, project_id=project_id, task_id=payload.get("task_id"),
        directive=directive,
        owner=payload.get("owner") or settings.target_github_owner,
        repo=payload.get("repo") or settings.target_github_repo,
        review=bool(payload.get("review", False)))


@app.get("/v1/qa/benchmark-apps")
@permit(P.ASSURANCE_READ, scope=Scope.project_or_org(query="project_id"))
def list_qa_benchmark_apps_endpoint(project_id: str = ""):
    """List pinned end-to-end application contracts used to evaluate BOSS itself.

    Catalog reads are side-effect free. A benchmark is not a claimed result; it becomes
    a governed code-task run only through the explicit launch endpoint below.

    Each entry carries whether it has ALREADY been built in this project. Without that the
    card can only say "Launch", so a benchmark that finished hours ago still invites the press
    that would build a second copy of it -- and the operator only discovers that by pressing.
    Telling them beforehand is the difference between a guard and an interface.
    """
    from boss_engine.services.benchmark_apps import benchmark_task_input, list_benchmark_apps
    from boss_engine.services.meeting_service import (
        completed_benchmark_build, is_reportable, meeting_fingerprint,
    )

    apps = list_benchmark_apps()
    if not project_id or not database_is_reachable(engine):
        return {"benchmark_apps": apps}
    with begin(engine) as c:
        for app_entry in apps:
            try:
                directive = benchmark_task_input(app_entry["id"])["instructions"]
                done = completed_benchmark_build(
                    c, project_id, app_entry["id"],
                    meeting_fingerprint(project_id, directive, ""),
                    name=app_entry.get("name"))
            except Exception:  # noqa: BLE001 - a catalog read must never fail on one entry
                done = None
            if done:
                # Only advertise `built` when the run is a real QA-benchmark
                # artifact (reportable). Name/subject matches are related work,
                # not certified canaries — listing them as built made Launch
                # reuse a run whose /report 404s.
                reportable = is_reportable(done)
                payload = {
                    "run_id": done["run_id"],
                    "run_status": done["run_status"],
                    "pull_request_url": done["pull_request_url"],
                    "preview_id": done["preview_id"],
                    "preview_url": done["preview_url"],
                    "matched_on": done["matched_on"],
                    "reportable": reportable,
                }
                if reportable:
                    app_entry["built"] = payload
                else:
                    app_entry["related"] = payload
    return {"benchmark_apps": apps}


@app.post("/v1/qa/benchmark-apps/{benchmark_id}/runs", status_code=201)
@permit(P.ASSURANCE_RUN, scope=Scope.project(body="project_id"))
def start_qa_benchmark_app_endpoint(benchmark_id: str, payload: open_bodies.BenchmarkAppLaunchBody):
    """Launch one pinned QA benchmark through the normal budgeted code-task workflow."""
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    project_id = str((payload or {}).get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=422, detail="project_id is required.")
    from boss_engine.services.benchmark_apps import benchmark_task_input
    from .services.code_task_service import start_code_task

    try:
        task = benchmark_task_input(benchmark_id)
    except ValueError as error:
        raise HTTPException(status_code=404, detail=str(error)) from error
    actor = str((payload or {}).get("actor") or "executive_console").strip()
    simulated = bool((payload or {}).get("simulated"))
    official = bool((payload or {}).get("official"))
    # official=true is a labeled budgeted code.task (route=direct by default,
    # qa_benchmark stamped). It does not invent a certified score.
    engine_override = str((payload or {}).get("engine") or "").strip().lower()
    model_config = None
    if engine_override:
        from boss_engine.services.spend_cap_failover import OFFICIAL_ENGINES, pin_engine_model_config

        if engine_override not in OFFICIAL_ENGINES:
            raise HTTPException(
                status_code=422,
                detail=f"unknown engine: {engine_override!r} (expected openai|native|claude_code)",
            )
        # simulated never spends — do not persist a live model route on a fixture.
        if not simulated:
            model_config = pin_engine_model_config(engine_override)
    # simulated=true is a no-spend fixture and must never convene the panel.
    # official=true is a reportable code-task launch (engine failover lives here).
    # Default the route to direct for those; do not change the meeting path
    # for ordinary launches.
    if simulated:
        route = "direct"
    elif official and (payload or {}).get("route") in (None, ""):
        route = "direct"
    else:
        route = str((payload or {}).get("route") or "meeting").lower()
    if simulated and (payload or {}).get("open_pr") is True:
        raise HTTPException(
            status_code=422,
            detail="simulated=true cannot open a PR (fail-closed; fixture has no sandbox or model)",
        )

    # Launch convenes the panel first, and the panel's PRD becomes the build.
    #
    # Pressing Launch used to hand the raw benchmark prompt straight to the coding pipeline.
    # The same prompt run through a PRD meeting produced a markedly better app, because the
    # panel turns "build an expense approval workflow" into explicit roles, states and flows,
    # and the coding agent's output is bounded by the specification it is given.
    #
    # The PRD gate auto-approves (BOSS_MEETING_PRD_AUTO_APPROVE), so this is one press, not a
    # press and a later approval. `route=direct` still goes straight to a code task for
    # comparing the two paths.
    if route == "meeting":
        from boss_engine.services.meeting_service import (
            completed_benchmark_build, convene_prd_meeting_core, is_reportable,
            meeting_fingerprint,
        )

        # Refuse to silently rebuild something that already exists.
        #
        # Launch on a finished benchmark used to convene a fresh panel, publish another PRD and
        # start another build -- twenty minutes and several dollars for a second copy of what
        # the operator already had, with nothing about the click saying so. The in-flight guard
        # did not help: it only catches a double-press while a meeting is still running.
        #
        # Answering with the existing work is the useful response. Building again stays
        # available and now has to be asked for: `force`.
        if not (payload or {}).get("force"):
            with begin(engine) as c:
                done = completed_benchmark_build(
                    c, project_id, benchmark_id,
                    meeting_fingerprint(project_id, task["instructions"], ""),
                    name=task["benchmark"].get("name"))
            # Only a REPORTABLE build blocks a rebuild. Related work that merely shares a name
            # is not this benchmark's artifact -- its /report 404s -- so refusing to build over
            # it left the operator with a card that said Launch and a press that would not.
            if is_reportable(done):
                return {
                    "status": "already_built",
                    **done,
                    "benchmark": {"id": task["benchmark"]["id"],
                                  "name": task["benchmark"]["name"]},
                    "hint": ("This benchmark has already been built. Open the existing run, or "
                             "pass force=true to build it again."),
                }

        try:
            with begin(engine) as c:
                require_project_actor(c, project_id, actor, "task_create")
                meeting_constraints = {
                    "source": "qa_benchmark",
                    "benchmark_id": benchmark_id,
                }
                if official:
                    meeting_constraints["official"] = True
                if engine_override:
                    meeting_constraints["engine"] = engine_override
                meeting = convene_prd_meeting_core(
                    c, settings=settings, budget=budget, intake=intake, jobs=jobs,
                    project_id=project_id,
                    directive=task["instructions"],
                    constraints=meeting_constraints,
                )
        except PermissionError as error:
            raise HTTPException(status_code=403, detail=str(error)) from error
        except ValueError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        return {
            "status": "meeting_convened",
            "run_id": meeting.get("run_id"),
            "task_id": meeting.get("task_id"),
            "duplicate_of": meeting.get("duplicate_of"),
            "benchmark": {"id": task["benchmark"]["id"], "name": task["benchmark"]["name"]},
        }
    finalize_ctx = dict(task.get("finalize_ctx") or {})
    if official:
        finalize_ctx["official"] = True
        bench = dict(finalize_ctx.get("qa_benchmark") or {})
        bench["official"] = True
        if engine_override:
            bench["engine"] = engine_override
        finalize_ctx["qa_benchmark"] = bench
    try:
        with begin(engine) as c:
            require_project_actor(c, project_id, actor, "task_create")
            run_id = start_code_task(
                c,
                project_id=project_id,
                task_id=(payload or {}).get("task_id"),
                title=task["title"],
                instructions=task["instructions"],
                acceptance_criteria=task["acceptance_criteria"],
                test_commands=task["test_commands"],
                owner=(payload or {}).get("owner") or (
                    "_fixture" if simulated else settings.target_github_owner
                ),
                repo=(payload or {}).get("repo") or (
                    "_fixture" if simulated else settings.target_github_repo
                ),
                base_branch=(payload or {}).get("base_branch") or "main",
                finalize_ctx=finalize_ctx,
                jobs=jobs,
                # A benchmark is machine evaluation work: nobody is sitting in front of it.
                # It used to be BOOSTED above everything (metatron reprioritize set
                # priority=5/priority_score=9000), which is how a batch of QA runs came to sit
                # in front of an operator's PRD meeting.
                job_priority=JOB_PRIORITY_BULK,
                # Benchmarks asked for `strict` — the most expensive setting BOSS has, and
                # currently withdrawn while it is being fixed. They ask for `balanced` now:
                # full review, findings captured, still always ships a PR. A caller may still
                # pass an explicit profile, and `usable_profile` has the final say either way.
                profile=(payload or {}).get("profile") or "balanced",
                risk_tier=int((payload or {}).get("risk_tier") or 1),
                model_config=None if simulated else model_config,
                repair_retries=(
                    int((payload or {}).get("repair_retries"))
                    if isinstance((payload or {}).get("repair_retries"), int)
                    else int(task.get("repair_retries") or 2)
                ),
                simulated=simulated,
            )
    except PermissionError as error:
        raise HTTPException(status_code=403, detail=str(error)) from error
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    if simulated:
        return {
            "status": "simulated",
            "run_id": run_id,
            "simulated": True,
            "job_enqueued": False,
            "passed": False,
            "benchmark": {"id": task["benchmark"]["id"], "name": task["benchmark"]["name"]},
            "note": (
                "Simulated fixture — no model, no budget reservation, no PR. "
                "This is not a certified benchmark pass."
            ),
        }
    queued = {
        "status": "queued",
        "run_id": run_id,
        "benchmark": {"id": task["benchmark"]["id"], "name": task["benchmark"]["name"]},
    }
    if official:
        queued["official"] = True
    if engine_override:
        queued["engine"] = engine_override
    return queued


@app.post("/v1/code-tasks/{run_id}/follow-up", status_code=201)
@permit(P.CODE_TASK_STEER, scope=Scope.of("code_task", path="run_id"))
def follow_up_code_task_endpoint(run_id: str, payload: CodeTaskFollowUpBody):
    """Ask for a change to an app that already exists, naming the run that built it.

    Most software work is changing software that already exists, and BOSS had no route for it:
    it could spawn follow-ups for its OWN deferred review findings, but an operator asking for
    "save this to a database instead of React state" had to locate the app's git branch by hand
    and post a base_branch. This is that capability, using the same lineage rules.
    """
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    instructions = str((payload or {}).get("instructions") or "").strip()
    if not instructions:
        raise HTTPException(status_code=422, detail="instructions are required.")
    actor = str((payload or {}).get("actor") or "executive_console").strip()
    from .services.code_task_service import load_code_task_run, start_followup_task

    try:
        with begin(engine) as c:
            parent = load_code_task_run(c, run_id)
            if parent is None:
                raise HTTPException(status_code=404, detail=f"run not found: {run_id}")
            require_project_actor(c, parent["project_id"], actor, "task_create")
            result = start_followup_task(
                c, parent_run_id=run_id, instructions=instructions, jobs=jobs,
                title=(payload or {}).get("title"),
                profile=(payload or {}).get("profile"),
                actor=actor,
                engine=(payload or {}).get("engine"),
                review_panel_size=(
                    int((payload or {}).get("review_panel_size"))
                    if isinstance((payload or {}).get("review_panel_size"), int)
                    else None
                ),
            )
    except PermissionError as error:
        raise HTTPException(status_code=403, detail=str(error)) from error
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    return {"status": "queued", **result}


@app.get("/v1/qa/benchmark-apps/runs/{run_id}/report")
@permit(P.CODE_TASK_READ, scope=Scope.of("code_task", path="run_id"))
def qa_benchmark_app_report_endpoint(run_id: str):
    """Read the evidence-backed completion report for a benchmark run."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from boss_engine.services.benchmark_apps import completion_report
    from .services.code_task_service import load_code_task_run

    with begin(engine) as c:
        require_code_task_reader(c, run_id)
        run = load_code_task_run(c, run_id)
        calls = c.execute(
            text(
                "SELECT total_tokens, cost_usd_micros, latency_ms, turns, ok "
                "FROM llm_calls WHERE code_task_run_id=:run_id ORDER BY created_at"
            ),
            {"run_id": run_id},
        ).mappings().all()
    if run is None:
        raise HTTPException(status_code=404, detail="code task not found")
    if not (run.get("finalize_ctx") or {}).get("qa_benchmark"):
        raise HTTPException(status_code=404, detail="code task is not a QA benchmark run")
    return completion_report(run, llm_calls=[dict(call) for call in calls])


@app.get("/v1/qa/benchmark-apps/evaluations")
@permit(P.ASSURANCE_READ, scope=Scope.project(query="project_id"))
def list_qa_benchmark_evaluations(project_id: str, limit: int = 50):
    """List durable scorecard snapshots produced by the benchmark tuning sweep."""
    if limit < 1 or limit > 500:
        raise HTTPException(status_code=422, detail="limit must be between 1 and 500.")
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from boss_engine.services.benchmark_tuning import list_evaluations

    with begin(engine) as connection:
        return {
            "project_id": project_id,
            "items": list_evaluations(connection, project_id=project_id, limit=limit),
        }


@app.post("/v1/qa/benchmark-apps/tuning-sweep")
@permit(P.ASSURANCE_RUN, scope=Scope.org())
def sweep_qa_benchmark_evaluations(payload: dict | None = None):
    """Materialize changed terminal QA reports; safe for the worker's idle loop.

    This performs no model, provider, SCM, or configuration write. It only stores
    evidence snapshots and recommendation state, so a regular worker can safely
    invoke it without gaining authority to approve or apply a tuning candidate.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    payload = payload or {}
    project_id = str(payload.get("project_id") or "").strip() or None
    limit = int(payload.get("limit") or 100)
    actor = str(payload.get("actor") or "qa_benchmark_scheduler").strip()
    from boss_engine.services.benchmark_tuning import sweep_terminal_benchmarks
    from boss_engine.services.improvement_programs import reconcile_program_baselines

    try:
        with begin(engine) as connection:
            result = sweep_terminal_benchmarks(
                connection,
                project_id=project_id,
                actor=actor,
                limit=limit,
            )
            result["baseline_reconciliation"] = reconcile_program_baselines(
                connection,
                project_id=project_id,
                actor="improvement_program_scheduler",
                limit=limit,
            )
            return result
    except ValueError as error:
        raise HTTPException(status_code=422, detail=str(error)) from error


@app.post(
    "/v1/qa/benchmark-apps/runs/{run_id}/tuning-proposal",
    response_model=SelfImprovementProposalDetail,
    status_code=201,
)
@permit(P.IMPROVEMENT_MANAGE, scope=Scope.project(body="project_id"))
def create_qa_benchmark_tuning_proposal(
    run_id: str,
    payload: QABenchmarkTuningProposalRequest,
) -> SelfImprovementProposalDetail:
    """Create a decision-gated tuning proposal from durable benchmark evidence.

    The endpoint cannot generate or apply a candidate change. ``change_ref`` must
    identify a developer-authored PR or configuration diff, and the resulting
    proposal follows the established test, canary, approval, rollout, and rollback
    state machine.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from boss_engine.services.benchmark_apps import (
        completion_report,
        tuning_proposal_inputs,
    )
    from .services.code_task_service import load_code_task_run

    with begin(engine) as connection:
        try:
            require_project_actor(
                connection,
                payload.project_id,
                payload.actor,
                "self_improvement_manage",
            )
            run = load_code_task_run(connection, run_id)
            if run is None or run.get("project_id") != payload.project_id:
                raise HTTPException(status_code=404, detail="QA benchmark run not found.")
            if not (run.get("finalize_ctx") or {}).get("qa_benchmark"):
                raise HTTPException(status_code=404, detail="Code task is not a QA benchmark run.")
            calls = connection.execute(
                text(
                    "SELECT total_tokens, cost_usd_micros, latency_ms, turns, ok "
                    "FROM llm_calls WHERE code_task_run_id=:run_id ORDER BY created_at"
                ),
                {"run_id": run_id},
            ).mappings().all()
            report = completion_report(run, llm_calls=[dict(call) for call in calls])
            proposal_input = tuning_proposal_inputs(
                report,
                change_ref=payload.change_ref,
                diff_summary=payload.diff_summary,
            )
            row = self_improvement.create_proposal(
                connection,
                project_id=payload.project_id,
                title=proposal_input["title"],
                summary=proposal_input["summary"],
                change_ref=proposal_input["change_ref"],
                diff_summary=proposal_input["diff_summary"],
                expected_impact=proposal_input["expected_impact"],
                test_plan=proposal_input["test_plan"],
                canary_scope=proposal_input["canary_scope"],
                rollback_plan=proposal_input["rollback_plan"],
                success_metrics=proposal_input["success_metrics"],
                actor=payload.actor,
                risk_tier=payload.risk_tier,
            )
        except ValueError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
    return self_improvement_detail_from_row(row)


