@app.post("/v1/investigations/{investigation_id}/run")
@permit(P.WORKER_LEASE)
def run_investigation_endpoint(investigation_id: str):
    """Worker-invoked: perform one investigation.

    It runs HERE, not in the worker, for the same reason code tasks do: the Claude Code CLI is
    installed in this image and not in the worker's. The worker owns the queue; the container
    with the binary owns the work.
    """
    require_worker_principal()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from boss_engine.services.debug_session import (
        block_community_investigation, run_investigation,
    )

    with begin(engine) as connection:
        project_id = connection.execute(
            text("SELECT project_id FROM investigations WHERE id = :investigation_id"),
            {"investigation_id": investigation_id},
        ).scalar_one_or_none()
        if project_id is None:
            return {"ok": False, "error": f"no such investigation: {investigation_id}"}
        actor = current_api_principal.get() or "system"
        require_project_actor(connection, project_id, actor, "workflow_execute")
        blocked = block_community_investigation(connection, settings, investigation_id)
        if blocked is not None:
            return blocked

    return run_investigation(engine, settings, investigation_id=investigation_id)


def _investigation_caller(investigation_id: str, request: Request) -> dict:
    """Resolve the token an investigation's sandbox is calling with.

    The sandbox holds this and nothing else — no database url, no KMS key, no SSH key. Those
    stay in this process, which is the whole reason these endpoints exist: the first version
    baked the connection string into the working directory, and because the commands ran in the
    sandbox's own stripped environment, the first SSH call auto-provisioned a replacement KMS
    master key. The investigation found that itself and called it "a silent wrong-key fallback".
    """
    from boss_engine.services.debug_session import authorise

    token = request.headers.get("x-investigation-token") or ""
    with begin(engine) as connection:
        try:
            return authorise(connection, investigation_id, token)
        except PermissionError as error:
            raise HTTPException(status_code=403, detail=str(error)) from error


