@permit(P.WORKER_LEASE)
def apply_host_deployment_endpoint(deployment_run_id: str,
                                   payload: open_bodies.StackDeployExecuteBody):
    """The worker hands its leased `deployment.host_apply` job here. Fenced by the lease; the
    apply runs inside the approved ChangeSet (services/governed_host_deploy.py)."""
    require_worker_principal()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from boss_engine.services.governed_host_deploy import execute_host_job

    result = execute_host_job(engine, settings, deployment_run_id=deployment_run_id,
                              job_id=payload.job_id, worker_id=payload.worker_id,
                              lease_token=payload.lease_token)
    if result.get("http_status"):
        # A lease that is not this job's, or a run that does not exist: 4xx, never a 200.
        raise HTTPException(status_code=int(result["http_status"]),
                            detail=str(result.get("error") or "Refused."))
    return result


def _planned_next_action(planned: dict) -> dict:
    """What the console does next with a plan. A governed host deployment waits on ONE
    decision in Approvals; a provider ChangeSet goes through ChangeSet review."""
    review = (planned.get("release_packet") or {}).get("plan_review") \
        or planned.get("plan_review")
    if review and planned.get("decision_id"):
        return {"next_action": "approve_decision", "decision_id": planned["decision_id"],
                "plan_review": review}
    return {"next_action": "approve_and_apply_changeset"}


@app.post("/v1/deployment-targets/{target_id}/auto-deploy")
@permit(P.DEPLOYMENT_TARGET_MANAGE, scope=Scope.of("deployment_target", path="target_id"))
def set_auto_deploy_endpoint(target_id: str, payload: AutoDeployBody):
    """Turn deploy-on-merge on/off, or pause it.

    `paused` is separate from `auto_deploy` on purpose: during an incident an operator wants
    automation to stop without losing the configuration that says this target is normally
    automatic — and without having to remember to turn it back on correctly.
    """
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    actor = _deployment_target_write_actor(payload)
    sets, params = [], {"i": target_id}
    if payload.get("auto_deploy") is not None:
        sets.append("auto_deploy = :a")
        params["a"] = bool(payload["auto_deploy"])
    if payload.get("paused") is not None:
        sets.append("paused = :pz")
        params["pz"] = bool(payload["paused"])
    if not sets:
        raise HTTPException(status_code=422, detail="auto_deploy or paused is required")

    with begin(engine) as connection:
        target = connection.execute(
            text("SELECT project_id FROM deployment_targets WHERE id=:i FOR UPDATE"),
            {"i": target_id},
        ).mappings().first()
        if not target:
            raise HTTPException(status_code=404, detail="no such deployment target")
        require_project_actor(
            connection, target["project_id"], actor, "providerops_manage"
        )
        result = connection.execute(
            text(f"UPDATE deployment_targets SET {', '.join(sets)}, updated_at=now() "
                 f"WHERE id=:i AND project_id=:p"),
            {**params, "p": target["project_id"]})
        if result.rowcount == 0:
            raise HTTPException(status_code=404, detail="no such deployment target")
        row = connection.execute(
            text("SELECT id, app_name, auto_deploy, paused, project_id FROM deployment_targets WHERE id=:i"),
            {"i": target_id}).mappings().first()
        _record_governed(
            connection,
            project_id=row["project_id"],
            actor=actor,
            effect_kind="deployment_target.auto_deploy",
            dedupe_parts=[target_id, row["auto_deploy"], row["paused"]],
            payload={"auto_deploy": row["auto_deploy"], "paused": row["paused"]},
        )
    return {"id": row["id"], "app_name": row["app_name"],
            "auto_deploy": row["auto_deploy"], "paused": row["paused"]}


@app.get("/v1/delivery/deployments")
@permit(P.DEPLOYMENT_READ, scope=Scope.project(query="project_id"))
def list_deployment_runs_endpoint(project_id: str, limit: int = 10):
    """Recent DEPLOYMENTS, newest first.

    Replaces the pipeline table that listed every code task run which had ever opened a PR —
    eighteen rows, nearly all with no deployment at all. A code task that never deployed is not
    a deployment; it is already visible under Code Tasks, and repeating it here was noise
    wearing the costume of a report.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    with begin(engine) as connection:
        rows = connection.execute(
            text("SELECT d.id, d.status, d.environment, d.commit_ref, d.trigger, "
                 "       d.started_at, d.finished_at, d.duration_ms, d.failure_reason, "
                 "       d.app_name, t.app_name AS target_app, t.domains, "
                 "       d.decision_id, d.changeset_id, "
                 "       (d.release_packet->>'governed') IS NOT NULL AS governed, "
                 "       jsonb_array_length(COALESCE(d.steps,'[]'::jsonb)) AS step_count "
                 "FROM deployment_runs d LEFT JOIN deployment_targets t "
                 "  ON t.id = d.deployment_target_id "
                 "WHERE d.project_id = :p ORDER BY d.created_at DESC LIMIT :l"),
            {"p": project_id, "l": max(1, min(limit, 50))}).mappings().all()
    return {"deployments": [{
        "id": r["id"], "status": r["status"], "environment": r["environment"],
        "app_name": r["target_app"] or r["app_name"], "commit_ref": r["commit_ref"],
        "trigger": r["trigger"], "duration_ms": r["duration_ms"],
        "started_at": r["started_at"].isoformat() if r["started_at"] else None,
        "finished_at": r["finished_at"].isoformat() if r["finished_at"] else None,
        "failure_reason": r["failure_reason"], "step_count": r["step_count"],
        "url": (r["domains"] or [None])[0],
        # A governed host deployment links to its one decision in Approvals.
        "decision_id": r["decision_id"] if r["governed"] else None,
        "changeset_id": r["changeset_id"],
    } for r in rows]}


@app.get("/v1/delivery/deployments/{deployment_run_id}")
@permit(P.DEPLOYMENT_READ, scope=Scope.of("deployment_run", path="deployment_run_id"))
def get_deployment_run_endpoint(deployment_run_id: str):
    """Live progress of one deployment: steps, timings, logs, outcome.

    This is what makes an honest progress display possible. The steps are written as they
    happen, so a run that is still going reports exactly how far it has got, and one that died
    mid-step shows where.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .services.deployment_steps import planned_steps

    with begin(engine) as connection:
        require_project_reader(
            connection, project_id_for_deployment_run(connection, deployment_run_id)
        )
        row = connection.execute(
            text("SELECT d.*, t.app_name AS target_app, t.domains "
                 "FROM deployment_runs d LEFT JOIN deployment_targets t "
                 "  ON t.id = d.deployment_target_id WHERE d.id = :i"),
            {"i": deployment_run_id}).mappings().first()
    if not row:
        raise HTTPException(status_code=404, detail="no such deployment run")

    done = list(row["steps"] or [])
    seen = {s.get("step") for s in done}
    # Connector steps belong only to an actively executing connector run. A
    # `created` run is awaiting ChangeSet approval/apply, and a `deployed` run
    # has already completed its Resource Plane provider effect. Neither has a
    # background connector worker to poll.
    running = row["status"] in {"running", "building", "deploying"}
    upcoming = (
        [s for s in planned_steps() if s["step"] not in seen] if running else []
    )
    packet = row["release_packet"] or {}
    governed = bool(packet.get("governed"))

    return {
        "deployment_run_id": row["id"], "status": row["status"],
        "app_name": row["target_app"] or row["app_name"],
        "environment": row["environment"], "commit_ref": row["commit_ref"],
        "trigger": row["trigger"], "failure_reason": row["failure_reason"],
        "started_at": row["started_at"].isoformat() if row["started_at"] else None,
        "finished_at": row["finished_at"].isoformat() if row["finished_at"] else None,
        "duration_ms": row["duration_ms"],
        "url": (row["domains"] or [None])[0],
        "health": row["health_check_results"],
        "steps": done + upcoming,
        "running": running,
        # A governed host deployment: its decision, ChangeSet and the plan that was approved.
        # `approved` is queued for the worker, so the console keeps watching it.
        "governed": governed,
        "decision_id": row["decision_id"] if governed else None,
        "changeset_id": row["changeset_id"],
        "plan_review": packet.get("plan_review") if governed else None,
        "rollback_plan": row["rollback_plan"] or [],
        "waiting": row["status"] in {"awaiting_approval", "approved"},
    }


@app.post("/v1/delivery/deployments/{deployment_run_id}/redeploy")
@permit(P.DEPLOYMENT_CREATE, scope=Scope.of("deployment_run", path="deployment_run_id"),
        confine=(Confine.body("reservation_id", "budget_reservation"),),
        production=Production(deployment_run="path:deployment_run_id"))
def delivery_redeploy_endpoint(deployment_run_id: str, payload: Optional[dict] = None):
    """Plan the same target again as a NEW deployment run.

    A new run keeps the previous attempt's history intact. The returned ChangeSet must pass
    Resource Plane approval and apply before any provider effect.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    p = payload or {}
    actor = str(p.get("actor") or "").strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    try:
        expected_cost = int(p.get("expected_cost_usd_micros") or 0)
    except (TypeError, ValueError) as error:
        raise HTTPException(
            status_code=422, detail="expected_cost_usd_micros must be an integer"
        ) from error
    if expected_cost < 0:
        raise HTTPException(
            status_code=422, detail="expected_cost_usd_micros must be non-negative"
        )
    reservation_id = str(p.get("reservation_id") or "").strip() or None
    with begin(engine) as connection:
        run_row = connection.execute(
            text("SELECT project_id FROM deployment_runs WHERE id = :i"),
            {"i": deployment_run_id},
        ).mappings().first()
        if not run_row:
            raise HTTPException(status_code=404, detail=p.get("reason")
                                or f"no deployment run {deployment_run_id}")
        actor = signed_in_actor(connection, run_row["project_id"], actor)
        require_project_actor(
            connection, run_row["project_id"], actor, "providerops_manage"
        )
    from .services.delivery_pipeline import redeploy
    # Planning creates a new run and ChangeSet; direct connector execution is disabled.
    result = redeploy(engine, settings, deployment_run_id,
                      commit_ref=(p.get("commit_ref") or None),
                      actor=actor, execute=False,
                      expected_cost_usd_micros=expected_cost,
                      reservation_id=reservation_id)
    # A missing deployment is a 404, not a 200 carrying the word "not_found". A caller that
    # checks the status code — which is most of them — would otherwise read a typo'd id as a
    # successful redeploy.
    if result.get("status") == "not_found":
        raise HTTPException(status_code=404, detail=result.get("reason")
                            or f"no deployment run {deployment_run_id}")
    if result.get("status") == "blocked":
        raise HTTPException(status_code=409, detail=result.get("reason")
                            or "Deployment policy blocked this run.")
    if not result.get("changeset_id"):
        raise HTTPException(status_code=409, detail="Deployment has no governed ChangeSet.")
    # `ref` opens the new plan in Infra's deploy drawer.
    return {**result, **_planned_next_action(result),
            "ref": f"delivery:{result.get('deployment_run_id')}"}


@app.post("/v1/deployments/{deployment_run_id}/promote")
@permit(P.DEPLOYMENT_PRODUCTION, scope=Scope.of("deployment_run", path="deployment_run_id"))
def promote_deployment_endpoint(deployment_run_id: str, payload: DeploymentPromoteBody):
    """Promote a SUCCEEDED staging deployment to production — the second human gate.

    Reuses PromotionOrchestrator rather than running a rollout here: promotion already has
    gating, pipeline verdicts and rollback in one place, and a shortcut path would be a second
    opinion about what "promoted" means.

    Refuses to promote a run that did not succeed. Promoting a failed build is the single most
    expensive mistake this endpoint could make easy.
    """
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    actor = str(payload.get("actor") or "").strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")

    with begin(engine) as connection:
        run = connection.execute(
            text("SELECT * FROM deployment_runs WHERE id = :i"),
            {"i": deployment_run_id}).mappings().first()
        if not run:
            raise HTTPException(status_code=404, detail="no such deployment run")
        run = dict(run)
        require_project_actor(connection, run["project_id"], actor, "task_create")

        if run.get("status") not in ("succeeded", "deployed", "completed"):
            raise HTTPException(
                status_code=409,
                detail=(f"deployment is {run.get('status')!r}; only a succeeded staging "
                        "deployment may be promoted"))
        if run.get("environment") != "staging":
            raise HTTPException(
                status_code=409,
                detail=f"run targets {run.get('environment')!r}, not staging")

        production = connection.execute(
            text("SELECT id FROM deployment_targets "
                 "WHERE project_id = :p AND app_name = :a AND repo = :r "
                 "  AND environment = 'production' AND status = 'active' "
                 "ORDER BY created_at DESC LIMIT 1"),
            {"p": run["project_id"], "a": run["app_name"], "r": run["repo"]}
        ).mappings().first()
        if not production:
            # Common and legitimate when everything runs on one box. Say what is missing
            # rather than inventing a production target.
            raise HTTPException(
                status_code=422,
                detail=(f"no active production deployment_target for app "
                        f"{run['app_name']!r} in {run['repo']!r}. Register one, or keep "
                        "deploying to this environment only."))

        plan = _governed_plan(payload)
        if plan:
            effect = _record_governed(
                connection,
                project_id=run["project_id"],
                actor=actor,
                effect_kind="deployment.promote",
                dedupe_parts=[deployment_run_id, production["id"], plan],
                payload={"deployment_run_id": deployment_run_id,
                         "production_target_id": production["id"]},
                rollback_plan=plan,
                destructive=True,
                spends=True,
                reservation_id=_governed_reservation(payload),
                expected_cost_usd_micros=_governed_cost(payload),
                worker=True,
            )
            return {
                "promoted_from": deployment_run_id,
                "approved_by": actor,
                "status": "recorded",
                "provider_called": False,
                **effect,
            }

        from boss_engine.services.promotion_orchestrator import PromotionOrchestrator

        try:
            result = PromotionOrchestrator(settings).promote(
                connection,
                project_id=run["project_id"],
                staging_target_id=run["deployment_target_id"],
                production_target_id=production["id"],
                commit_ref=str(run.get("commit_ref") or ""),
                actor=actor,
                release_packet={"source": "promotion_gate",
                                "promoted_from_run": deployment_run_id,
                                "approved_by": actor,
                                "note": str(payload.get("note") or "")[:500]},
            )
        except ValueError as exc:
            raise HTTPException(status_code=422, detail=str(exc))
        return {"promoted_from": deployment_run_id, "approved_by": actor, **result}


@app.get("/v1/delivery/targets/{target_id}/preflight")
@permit(P.DEPLOYMENT_READ, scope=Scope.project(query="project_id"))
def delivery_preflight_endpoint(target_id: str, project_id: str):
    """Is this target deployable right now, and if not exactly what is missing?

    Cheap and read-only, so an operator never has to run a deployment to discover a
    credential is absent — which is how provider_account_id was found the first time.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .services.deployment_connectors import preflight
    with begin(engine) as c:
        row = c.execute(text("SELECT * FROM deployment_targets WHERE id=:i AND project_id=:p"),
                        {"i": target_id, "p": project_id}).mappings().first()
        if not row:
            raise HTTPException(status_code=404, detail="no such deployment target")
        # Same connection: preflight resolves the target's bound credential through it, so the
        # operator sees a credential problem here rather than in the middle of a deployment.
        return preflight(dict(row), settings, c)


@app.get("/v1/delivery/pipeline")
@permit(P.DEPLOYMENT_READ, scope=Scope.project(query="project_id"))
def delivery_pipeline_endpoint(project_id: str, limit: int = 25):
    """Code task -> PR -> deployment -> health, assembled in ONE query pass.

    One endpoint on purpose: a CI/CD view whose stages arrive separately can show a merged PR
    next to a stale deployment status and quietly mislead. The delivery story has to be
    internally consistent or it is worse than no view.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .services.delivery_pipeline import pipeline_view
    with begin(engine) as c:
        view = pipeline_view(c, project_id, limit=limit)
    # Safety flags ride with the pipeline payload so the empty-state UI does not need a
    # second round-trip (and cannot disagree about whether auto sandbox deploy is armed).
    view["sandbox_deploy_enabled"] = bool(getattr(settings, "enable_sandbox_deploy", False))
    view["sandbox_merge_enabled"] = bool(getattr(settings, "enable_sandbox_merge", False))
    return view


@app.get("/v1/shepherd/overview")
@permit(P.AUTOPILOT_READ, scope=Scope.project(query="project_id"))
def shepherd_overview_endpoint(project_id: str, limit: int = 40):
    """Everything the Task Shepherd console renders: reasoning, ledger, escalations, spend.

    One endpoint on purpose — the console's whole point is showing HOW it is thinking, and
    that story is incoherent if the timeline, the ledger and the money arrive separately and
    can disagree with each other.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from .services.shepherd_service import calibration
    from .services.task_shepherd import CLASS_NAMES
    with begin(engine) as c:
        reasoning = [dict(r) for r in c.execute(text(
            "SELECT id, task_ref, step_no, observe, signals, hypothesis, confidence, "
            "check_result, check_confirmed, failure_class, remedy_chosen, rationale, "
            "predicted_cost_usd_micros, predicted_outcome, actual_cost_usd_micros, "
            "actual_outcome, stopped_because, created_at "
            "FROM shepherd_reasoning WHERE project_id=:p "
            "ORDER BY created_at DESC LIMIT :l"), {"p": project_id, "l": limit}).mappings()]
        ledger = [dict(r) for r in c.execute(text(
            "SELECT task_ref, failure_class, remedy_id, status, used_at, "
            "cost_usd_micros, outcome FROM shepherd_ledger WHERE project_id=:p "
            "ORDER BY created_at DESC LIMIT 200"), {"p": project_id}).mappings()]
        escalations = [dict(r) for r in c.execute(text(
            "SELECT id, task_ref, question, options, evidence, status, created_at "
            "FROM shepherd_escalations WHERE project_id=:p AND status='open' "
            "ORDER BY created_at DESC LIMIT 50"), {"p": project_id}).mappings()]
        spend = dict(c.execute(text(
            "SELECT COALESCE(SUM(CASE WHEN r.pull_request_url IS NOT NULL "
            "         THEN c.usd ELSE 0 END),0) AS productive, "
            "       COALESCE(SUM(CASE WHEN r.pull_request_url IS NULL "
            "         THEN c.usd ELSE 0 END),0) AS unproductive "
            "FROM code_task_runs r JOIN LATERAL ("
            "  SELECT COALESCE(SUM(cost_usd_micros),0)/1e6 AS usd FROM llm_calls "
            "  WHERE code_task_run_id=r.id) c ON true "
            "WHERE r.project_id=:p AND r.created_at > now() - interval '7 days'"),
            {"p": project_id}).mappings().first() or {})
        cal = calibration(c, project_id)
    return {
        "project_id": project_id,
        "class_names": {str(k): v for k, v in CLASS_NAMES.items()},
        "reasoning": reasoning, "ledger": ledger, "escalations": escalations,
        "spend": {k: round(float(v or 0), 2) for k, v in spend.items()},
        "calibration": cal["remedies"],
    }


