@permit(P.DEPLOYMENT_CREATE, scope=Scope.of("code_task", path="run_id"))
def deploy_code_task_endpoint(run_id: str, request: Request, payload: Optional[dict] = None):
    """Deploy a sandbox-built app to a customer's own host (governed SSH-host path).

    Phase 1: mode='dry_run' (default) returns the exact deploy PLAN — steps, SSH/docker commands,
    health check, rollback — WITHOUT touching any host. Phase 2 (mode='ssh') will actuate via
    ssh_host_adapter once a host + SSH key are provided and the outward-action gate is enabled."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    p = payload or {}
    actor = str(p.get("actor") or "").strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    with begin(engine) as connection:
        run_row = connection.execute(
            text("SELECT project_id FROM code_task_runs WHERE id = :run_id"),
            {"run_id": run_id},
        ).mappings().first()
        if not run_row:
            raise HTTPException(status_code=404, detail="Code task run not found.")
        require_project_actor(
            connection, run_row["project_id"], actor, "infra_provision"
        )
        project_id = run_row["project_id"]
    mode = str(p.get("mode", "dry_run")).lower()
    if mode not in {"dry_run", "ssh"}:
        raise HTTPException(status_code=422, detail="mode must be 'dry_run' or 'ssh'")
    if mode == "ssh":
        # A caller-named host has no environment of its own to say it is not production, so
        # shipping to one is treated as production (IDENTITY: deployment:production).
        _require_production(request, project_id, always=True)
    plan = _governed_plan(p)
    if mode == "ssh" and plan:
        with begin(engine) as connection:
            effect = _record_governed(
                connection,
                project_id=project_id,
                actor=actor,
                effect_kind="code_task.deploy",
                dedupe_parts=[run_id, plan],
                payload={"run_id": run_id, "mode": "ssh"},
                rollback_plan=plan,
                destructive=True,
                spends=True,
                reservation_id=_governed_reservation(p),
                expected_cost_usd_micros=_governed_cost(p),
                worker=True,
            )
        return {"status": "recorded", "provider_called": False, "run_id": run_id, **effect}
    from .services.deploy_service import deploy_ssh, plan_ssh_deploy, render_plan_markdown
    try:
        plan = plan_ssh_deploy(
            engine, settings, run_id,
            host=str(p.get("host") or "<HOST>"), name=p.get("name"),
            port=int(p.get("port", 8080)), user=str(p.get("user") or "root"))
    except ValueError as exc:
        raise HTTPException(status_code=404, detail=str(exc))
    if mode == "dry_run":
        return {"plan": plan, "markdown": render_plan_markdown(plan)}
    if mode != "ssh":
        raise HTTPException(status_code=422, detail="mode must be 'dry_run' or 'ssh'")
    if str(settings.boss_edition).strip().lower() in {"community", "oss", "local"}:
        from boss_engine.services.governed_host_deploy import ungoverned_refusal

        raise HTTPException(status_code=409,
                            detail=ungoverned_refusal("Community SSH deployment"))

    # mode == 'ssh' — actuate on a real host (Phase 2/3). Requires an explicit host, the SSH key,
    # and the outward gate; otherwise return the plan + the reason it's held (never touch a host).
    host = str(p.get("host") or "").strip()
    if not host or host == "<HOST>":
        raise HTTPException(status_code=422, detail="a real 'host' is required for mode='ssh'")
    try:
        result = deploy_ssh(
            engine, settings, run_id, host=host, user=str(p.get("user") or "root"),
            ssh_port=int(p.get("ssh_port", 22)), app_port=int(p.get("port", 8080)), name=p.get("name"))
    except PermissionError as exc:
        raise HTTPException(status_code=403, detail={
            "error": str(exc), "reason": "outward deploy gate off / no key",
            "plan": plan, "markdown": render_plan_markdown(plan)})
    except ValueError as exc:
        # Invalid host/user (shell-metacharacter rejection) — never actuate.
        raise HTTPException(status_code=422, detail=str(exc))
    except (RuntimeError, OSError, subprocess.SubprocessError) as exc:
        raise HTTPException(status_code=502, detail={"error": f"deploy failed: {exc}", "plan": plan})
    return {"result": result, "plan": plan}


# What makes a code task run shippable. Deliberately a small, explicit set rather than a
# "not obviously broken" check: deploying is the one action here that reaches a real machine,
# and the failure mode of guessing wrong is a broken build placed on a customer's host.
DEPLOYABLE_STATUSES = frozenset({"completed"})
UNDEPLOYABLE_STATUSES = frozenset({"blocked", "failed", "cancelled", "queued", "running"})


def assert_run_is_deployable(run: dict) -> None:
    """Refuse to ship a run that never produced reviewed code.

    The UI hides the control for these, but hiding a button is not a guard — the endpoint is
    reachable directly, and a guard that lives only in the console is a guard that is not
    there. Raises with the REASON, because "cannot deploy" without one sends an operator to
    the logs to discover a state the console already knew.

    Without this, deploying a blocked run was accepted and failed LATE: after a clone, a build
    and a transfer, at the health gate, with an error about the app rather than about the fact
    that this task never finished.
    """
    status = str(run.get("status") or "").lower()
    if status in UNDEPLOYABLE_STATUSES:
        raise HTTPException(
            status_code=409,
            detail=(f"this task is {status!r} — there is no reviewed build to deploy. "
                    "Fix or re-run the task first."))
    if status not in DEPLOYABLE_STATUSES and not run.get("pull_request_url"):
        raise HTTPException(
            status_code=409,
            detail=(f"this task is {status!r} and opened no pull request, so nothing has been "
                    "built and reviewed for it yet."))


def assign_app_slot(target_id: str, host: dict, *, wanted_port: Any = None) -> dict:
    """Give a host target its port and the domain that names it, so its first deploy can plan.

    setup-deployment used to call bootstrap_deployment_target(target_id, {"apply_port": True}).
    That never assigned anything: the call carried no actor (so it answered "actor is
    required"), and with one it would answer 409, because a direct host bootstrap is disabled
    without a governed ChangeSet. The app was then left with no port and no domain, and its
    first deploy was refused with `app_port_missing`. Choosing a port is a database fact (the
    promised ports, plus a probe of the machine), so it is done here, and the answer is words.
    """
    from boss_engine.services.deployment_connectors import _app_port, domain_with_port
    from boss_engine.services.deployment_fleet import _first_free_port, _ports_assigned_on

    address = str(host.get("address") or "").strip()
    name = str(host.get("name") or address or "the host")
    if not address:
        return {"ok": False, "message": f"{name} has no address, so no port could be chosen.",
                "next": "Set the host's address in Infra, then press Set target again."}
    with begin(engine) as connection:
        target = connection.execute(
            text("SELECT app_name, required_resources, domains FROM deployment_targets "
                 "WHERE id = :i FOR UPDATE"), {"i": target_id}).mappings().first()
        if not target:
            return {"ok": False, "message": "The target was not found after it was created.",
                    "next": "Press Set target again."}
        target = dict(target)
        taken = {p: a for p, a in _ports_assigned_on(connection, address).items()
                 if a != str(target.get("app_name") or "")}
        port = _app_port(target, default=0)
        if not port and wanted_port not in (None, ""):
            try:
                port = int(str(wanted_port).strip())
            except ValueError:
                return {"ok": False, "message": f"{wanted_port!r} is not a port number.",
                        "next": "Give a number such as 3000, or leave the port empty."}
        if port and port in taken:
            return {"ok": False,
                    "message": f"Port {port} on {name} is already promised to {taken[port]!r}.",
                    "next": "Leave the port empty and BOSS will choose a free one."}
        if not port:
            port = _first_free_port(connection, address)
        if not port:
            return {"ok": False, "message": f"No free port was found on {name}.",
                    "next": "Free a port on the machine or set one on the target in Infra."}
        domains = [d for d in (target.get("domains") or []) if d]
        fixed = domain_with_port(domains[0] if domains else None, address, port)
        if fixed:
            domains = [fixed] + domains[1:]
        connection.execute(
            text("UPDATE deployment_targets SET required_resources = CAST(:rr AS JSONB), "
                 "domains = CAST(:d AS JSONB), updated_at = now() WHERE id = :i"),
            {"rr": json.dumps(merge_target_resources(target.get("required_resources"),
                                                     {"app_port": port})),
             "d": json.dumps(domains), "i": target_id})
    return {"ok": True, "port": port, "domain": domains[0] if domains else f"{address}:{port}",
            "message": f"The app will listen on port {port} of {name}."}


def _app_slot_report(target_id: str, host: dict, wanted_port: Any = None) -> dict:
    """assign_app_slot, never raising: a target that exists without a port is recoverable from
    Infra; losing the target because a port probe failed is not. Every answer is words."""
    try:
        return assign_app_slot(target_id, host, wanted_port=wanted_port)
    except HTTPException as exc:
        detail = exc.detail if isinstance(exc.detail, str) else "the port could not be chosen"
        return {"ok": False, "message": f"No port was set: {detail}",
                "next": "Set the app's port on its target in Infra, then deploy."}
    except Exception:  # noqa: BLE001
        LOGGER.warning("assigning the app slot for %s failed", target_id, exc_info=True)
        return {"ok": False, "message": "No port was set: choosing one failed on the server.",
                "next": "Set the app's port on its target in Infra, then deploy."}


@app.post("/v1/code-tasks/{run_id}/setup-deployment")
@permit(P.DEPLOYMENT_TARGET_MANAGE, scope=Scope.of("code_task", path="run_id"))
def setup_deployment_for_code_task_endpoint(run_id: str, payload: open_bodies.CodeTaskSetupDeploymentBody):
    """Point an app at a verified host — the missing link between the Factory and the fleet.

    Onboarding a host and approving a preview were both reachable, and nothing joined them: an
    app that had already merged had no way to acquire a destination except a per-app wizard on
    another screen, which is the trip the delivery work exists to remove. This creates the
    `deployment_target` from what the code task already knows, attaches the host so `target_ref`
    is derived rather than retyped, and turns on deploy-on-merge.

    It does NOT deploy. Creating a destination and shipping to it are different decisions, and
    the second one has its own button.
    """
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    actor = str(payload.get("actor") or "").strip()
    host_id = str(payload.get("host_id") or "").strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    if not host_id:
        raise HTTPException(status_code=422, detail="host_id is required")

    from boss_engine.services.deployment_fleet import attach_target, get_host

    with begin(engine) as connection:
        run = connection.execute(
            text("SELECT id, project_id, spec, title, status, pull_request_url "
                 "FROM code_task_runs WHERE id = :i"),
            {"i": run_id}).mappings().first()
        if not run:
            raise HTTPException(status_code=404, detail="Code task run not found.")
        run = dict(run)
        require_project_actor(connection, run["project_id"], actor, "task_create")
        assert_run_is_deployable(run)

        host = get_host(connection, host_id)
        if not host:
            raise HTTPException(status_code=404, detail="no such deployment host")
        if host.get("project_id") != run["project_id"]:
            # Binding a foreign host would also grant this project use of its SSH key.
            raise HTTPException(
                status_code=422,
                detail="host belongs to a different project; setup-deployment refused")
        if host.get("status") != "verified":
            # A target pointed at an unproven host fails at deploy time, long after the
            # decision was made and somewhere less obvious than here.
            raise HTTPException(
                status_code=422,
                detail=f"host {host['name']!r} is {host['status']!r}, not verified. "
                       "Finish onboarding it first.")

        spec = run.get("spec") or {}
        if isinstance(spec, str):
            try:
                spec = json.loads(spec)
            except ValueError:
                spec = {}
        # The BARE repo name: `settings.target_github_repo` is what the merge path keys on, and
        # a target stored as "owner/name" is a target the delivery seam will never resolve.
        repo = str(payload.get("repo") or spec.get("repo") or settings.target_github_repo or "")
        repo = repo.rsplit("/", 1)[-1]
        app_name = str(payload.get("app_name") or "").strip()
        if not app_name:
            raise HTTPException(status_code=422, detail="app_name is required")
        # A DIRECTIVE IS NOT A NAME, and this endpoint is where that has to be caught.
        #
        # The console's Set-target form defaulted this field to the run's whole title, so one
        # click created a target called "Build a lead triage inbox.Who it is for: a small team
        # drowning in in…". Target resolution matches on app IDENTITY, so the app then had no
        # target it could recognise and the deploy refused with "no 'staging' target of its
        # own" — while listing that very target among the ones belonging to other apps.
        #
        # The form is fixed too, but the form is one caller. `project_name` is the same namer
        # the console titles cards with and the same one deploy resolution matches against, so
        # normalising here means a target cannot be created under a name the deploy will never
        # find, whoever asked for it.
        from boss_engine.services.naming import project_name as _project_name

        _display, _blurb, _label = _project_name(app_name)
        if _display and _display != "Untitled app" and _display != app_name:
            LOGGER.info("deployment target name normalised: %r -> %r", app_name, _display)
            app_name = _display
        environment = str(payload.get("environment") or "staging")

        # MATCH THE APP, NOT THE STRING IT WAS STORED UNDER.
        #
        # An exact match could never find a target created before the normalisation above,
        # because the name stored there is the whole directive. So an app whose target already
        # existed under the damaged name would get a SECOND target on a second port, the old one
        # would be orphaned, and the app would end up deployed twice — a worse state than the
        # one being repaired.
        #
        # Both sides go through the namer and then through identity, so "Build a lead triage
        # inbox.\nWho it is for: …" and "Lead-Triage Inbox" resolve to the same app. When the
        # stored name is the damaged one, it is repaired in place: that is what makes pressing
        # Set target once fix the app rather than duplicate it.
        from boss_engine.services.naming import identity_key as _identity_key

        _wanted = _identity_key(app_name)
        existing = None
        for _row in connection.execute(
            text("SELECT id, host_id, status, app_name FROM deployment_targets "
                 "WHERE project_id = :p AND environment = :e"),
            {"p": run["project_id"], "e": environment},
        ).mappings().all():
            _stored = str(_row["app_name"] or "")
            _named, _b, _l = _project_name(_stored)
            if _identity_key(_stored) == _wanted or (
                _named and _named != "Untitled app" and _identity_key(_named) == _wanted
            ):
                existing = _row
                if _stored != app_name:
                    LOGGER.info("deployment target %s renamed: %r -> %r",
                                _row["id"], _stored, app_name)
                    connection.execute(
                        text("UPDATE deployment_targets SET app_name = :a, updated_at = now() "
                             "WHERE id = :i"), {"a": app_name, "i": _row["id"]})
                break
        if existing:
            # SETTING A TARGET MEANS THE OPERATOR WANTS IT USABLE.
            #
            # A RETIRED target was left retired. The console lists only active ones, so the app
            # vanished from every picker while this endpoint answered "already deploying to
            # hetzner-ci-01" — the operator pressed Set target repeatedly, was told each time
            # that it had worked, and nothing appeared anywhere. The deploy step then showed a
            # SUCCEEDED deploy whose detail read status=blocked, for an app answering "not
            # found", with no way to ship it.
            #
            # Retiring is how you take an app out of service; pointing it at a host again is
            # how you put it back. Doing the second and silently keeping the first is a state
            # nobody asked for and nothing surfaces.
            revived = existing["status"] == "retired"
            if revived:
                connection.execute(
                    text("UPDATE deployment_targets SET status = 'active', updated_at = now() "
                         "WHERE id = :i"), {"i": existing["id"]})
            # AN UNBOUND TARGET IS THE THING THIS ENDPOINT EXISTS TO BIND.
            #
            # Refusing outright stranded the exact case it was meant to serve: a target created
            # by an earlier attempt that never got a host (host_id NULL) could not be bound by
            # "Set target" — the only control that binds one — and the advice to "attach it from
            # the Hosts panel" sent the operator to a panel that lists hosts, not orphaned
            # targets. The app then had a destination it could never deploy to.
            #
            # The 409 is here to stop a SECOND target shadowing a working one. That is only a
            # real conflict when the existing target is bound somewhere else.
            if not existing["host_id"]:
                attach_target(connection, target_id=existing["id"], host_id=host_id)
                if payload.get("auto_deploy", True):
                    connection.execute(
                        text("UPDATE deployment_targets SET auto_deploy = true, "
                             "updated_at = now() WHERE id = :i"), {"i": existing["id"]})
                early = {"target_id": existing["id"], "host_id": host_id,
                        "adopted_existing_target": True, "revived": revived,
                        "message": f"Bound the existing {environment} target for {app_name!r} "
                                   f"to {host['name']!r}."
                                   + (" It was retired; it is active again." if revived else "")}
            elif existing["host_id"] == host_id:
                early = {"target_id": existing["id"], "host_id": host_id,
                        "already_bound": True, "revived": revived,
                        "message": (f"{app_name!r} is active again on {host['name']!r}."
                                    if revived
                                    else f"{app_name!r} is already deploying to "
                                         f"{host['name']!r}.")}
            else:
                raise HTTPException(
                    status_code=409,
                    detail=f"{app_name!r} already has a {environment} target bound to a "
                           f"different host ({existing['host_id']}). Retarget or retire that "
                           "one first.")

    # An adopted or already-bound target gets its port too, AFTER the transaction above has
    # committed: assign_app_slot locks the same row from its own connection.
    if existing:
        early["bootstrap"] = _app_slot_report(early["target_id"], host, payload.get("app_port"))
        return early

    # DECLARE THE HEALTH CHECK, and its scheme.
    #
    # `_health_url` defaults to https and says, correctly, that the target should state the
    # scheme rather than have the code infer it from the shape of a domain. This endpoint said
    # nothing — so a target reached by bare IP was probed over TLS and the gate failed with
    # `WRONG_VERSION_NUMBER` on an app that was serving perfectly. Deciding it HERE is not
    # inference: at creation we know the destination is a host address with no certificate.
    address = str(host["address"])
    looks_like_ip = all(part.isdigit() for part in address.split(".")) and address.count(".") == 3
    scheme = "http" if (looks_like_ip or ":" in address) else "https"

    created = register_deployment_target({
        "project_id": run["project_id"],
        "app_name": app_name,
        "repo": repo,
        "environment": environment,
        "target_kind": "ssh",
        "health_checks": [{"kind": "http", "scheme": scheme, "path": "/",
                           "expect": 200, "expect_status": 200}],
        # Replaced immediately by `attach_target`, which derives it from the host record so the
        # address has exactly one writable home.
        "target_ref": f"{host.get('ssh_user') or 'root'}@{host['address']}",
        "app_entry": payload.get("app_entry"),
        "app_port": payload.get("app_port"),
        "repo_owner": payload.get("repo_owner") or spec.get("owner"),
        "actor": actor,
    })
    target_id = created.get("id") or (created.get("target") or {}).get("id")

    with begin(engine) as connection:
        attached = attach_target(connection, target_id=target_id, host_id=host_id)
        if payload.get("auto_deploy", True):
            connection.execute(
                text("UPDATE deployment_targets SET auto_deploy = true, updated_at = now() "
                     "WHERE id = :i"), {"i": target_id})

    # PREPARE THE APP'S SLOT ON THE HOST: deploy directory, docker check, and a free port —
    # which also writes the domain the port belongs to.
    #
    # Linking without this produced a target that resolved its key and its host and then
    # blocked at preflight with "target has no domain, so health cannot be observed": a
    # deployment that cannot be health-checked is one the gate cannot pass. The port hunt has
    # to happen against the real machine, and this is the first moment BOSS has one.
    #
    # Best-effort: a target that exists but has not been bootstrapped is recoverable from the
    # CI/CD screen, whereas losing the target because a port scan timed out is not.
    bootstrap_report = _app_slot_report(target_id, host, payload.get("app_port"))

    return {"run_id": run_id, "target_id": target_id, "app_name": app_name,
            "bootstrap": bootstrap_report,
            "host": attached.get("host_name"), "target_ref": attached.get("target_ref"),
            "arch": attached.get("arch"), "auto_deploy": bool(payload.get("auto_deploy", True)),
            "next": "Deploy it once from here; after that a merged change ships by itself."}


_CODE_TASK_DEPLOYMENT_READ_SLOTS = 4
_code_task_deployment_read_slots = threading.BoundedSemaphore(
    _CODE_TASK_DEPLOYMENT_READ_SLOTS
)


def _admit_code_task_deployment_read(endpoint):
    """Bound this read before FastAPI queues its synchronous DB work.

    The Factory can ask for many cards at once. A full per-process queue must
    return a retryable response promptly instead of waiting for a worker thread
    or the pool's default 30-second checkout ceiling.
    """
    @wraps(endpoint)
    async def admitted(*args, **kwargs):
        if not _code_task_deployment_read_slots.acquire(blocking=False):
            raise HTTPException(
                status_code=503,
                detail="Deployment reads are busy; retry shortly.",
                headers={"Retry-After": "1"},
            )
        try:
            try:
                return await run_in_threadpool(endpoint, *args, **kwargs)
            except (InterfaceError, OperationalError, PoolTimeoutError) as error:
                LOGGER.warning("Code task deployment read could not reach Postgres", exc_info=True)
                raise HTTPException(
                    status_code=503, detail="Postgres is not reachable."
                ) from error
        finally:
            _code_task_deployment_read_slots.release()

    return admitted


@app.get("/v1/code-tasks/{run_id}/deployments")
@_admit_code_task_deployment_read
@permit(P.DEPLOYMENT_READ, scope=Scope.of("code_task", path="run_id"))
def deployments_for_code_task_endpoint(run_id: str, limit: int = 5,
                                       app_name: Optional[str] = None):
    """What this code task actually SHIPPED, if anything.

    Joined on `release_packet->>'code_task_run_id'` — the link the delivery seam already
    records — rather than by matching app names. An app's display name, its target's
    `app_name` and its repo folder are three different strings that agree right up until they
    do not, and a status panel that silently shows another app's deployment is worse than one
    that shows nothing.

    Powers the deployment line on the app card, so shipping can be watched from where the
    change was approved instead of on the CI/CD screen.
    """
    with begin(engine) as connection:
        run_project = require_code_task_reader(connection, run_id)
        rows = connection.execute(
            # deployment_target_id is returned so the card can UNBIND, not only retry. The
            # console had no way to undo a binding at all — DELETE /v1/deployment-targets/{id}
            # existed and nothing called it — and a deployment that fails because the TARGET is
            # wrong (no domain, or a port belonging to another app) fails identically on every
            # retry. Without this id the unbind control is permanently disabled, which is how
            # the first version of it shipped before this was checked.
            text("SELECT r.id, r.app_name, r.environment, r.status, r.commit_ref, "
                 "       r.started_at, r.finished_at, r.failure_reason, r.trigger, "
                 "       r.deployment_target_id, r.steps, r.health_check_results, "
                 "       r.decision_id, x.status AS decision_status, "
                 "       t.domains, t.health_checks, h.name AS host_name, "
                 "       r.release_packet->>'code_task_run_id' AS release_packet_run, "
                 "       r.created_at, 'run' AS source "
                 "FROM deployment_runs r "
                 "LEFT JOIN decisions x ON x.id = r.decision_id "
                 "LEFT JOIN deployment_targets t ON t.id = r.deployment_target_id "
                 "LEFT JOIN deployment_hosts h ON h.id = t.host_id "
                 # AN APP'S ATTEMPTS ARE SEVERAL RUNS, AND ONLY ONE OF THEM SHIPPED.
                 #
                 # This matched the release packet's run id alone. The Interview Scorecard App
                 # was deployed and answering 200 on 3015, and its Factory card said NOT
                 # DEPLOYED with a "Deploy now" button — because the deployment is stamped with
                 # crun_7f38987c (the attempt that succeeded) and the card is a different
                 # attempt of the same app. Three attempts, one deployment, and the card asked
                 # about the wrong one.
                 #
                 # So the run id OR the same app, matched on identity below rather than in SQL,
                 # because identity is one rule and it lives in Python. The docstring's warning
                 # still holds — matching on a NAME could show another app's deployment — which
                 # is why this is identity equality within one project and not a LIKE.
                 "WHERE r.project_id = :p "
                 # A DEPLOY FROM THE APP'S OWN boss.deploy.yaml IS A STACK DEPLOYMENT. Read only
                 # from deployment_runs, the step described an older single-container deploy
                 # while the app was live from a newer stack deploy.
                 "UNION ALL "
                 "SELECT s.id, t.app_name, t.environment, s.status, s.commit_sha, "
                 "       s.apply_started_at, s.finished_at, s.failure_reason, 'stack', "
                 "       s.target_id, s.steps, NULL::jsonb, "
                 "       s.decision_id, x.status, "
                 "       t.domains, t.health_checks, h.name, "
                 "       s.code_task_run_id, s.created_at, 'stack' "
                 "FROM stack_deployments s "
                 "LEFT JOIN decisions x ON x.id = s.decision_id "
                 "LEFT JOIN deployment_targets t ON t.id = s.target_id "
                 "LEFT JOIN deployment_hosts h ON h.id = COALESCE(s.host_id, t.host_id) "
                 "WHERE s.project_id = :p "
                 "ORDER BY created_at DESC LIMIT 200"),
            {"p": run_project}).mappings().all()
    from boss_engine.services.naming import identity_key as _identity_key

    _wanted = _identity_key(app_name) if app_name else ""
    rows = [
        r for r in rows
        if r["release_packet_run"] == run_id
        or (_wanted and _identity_key(str(r["app_name"] or "")) == _wanted)
    ][:max(1, min(int(limit), 20))]
    out = []
    seen_targets: set[str] = set()
    for row in rows:
        item = dict(row)
        item.pop("release_packet_run", None)
        source = item.pop("source", "run")
        item.pop("created_at", None)
        # The newest deploy of a target is the one serving it; older ones are history.
        target_key = str(item.get("deployment_target_id") or "")
        newest = target_key not in seen_targets
        seen_targets.add(target_key)
        for key in ("started_at", "finished_at"):
            if item.get(key) is not None:
                item[key] = str(item[key])
        # A FULLY-QUALIFIED url, resolved once, server-side.
        #
        # `domains` holds a bare `host:port`. Every consumer then had to prepend a scheme, and
        # three of them did it differently: delivery-ui hardcoded https (broken link),
        # deploy-ui hardcoded http, and the app card prepended nothing at all — so "Open"
        # resolved as a RELATIVE path and navigated to
        # localhost:3001/192.0.2.202:3010 (address redacted). Handing out an
        # address that is not a URL guarantees each caller invents the missing half.
        # The scheme the health probe uses is the scheme the link uses.
        domains = item.get("domains") or []
        raw = domains[0] if isinstance(domains, list) and domains else None
        if raw and "://" not in str(raw):
            checks = item.get("health_checks") or []
            declared = (checks[0].get("scheme") if isinstance(checks, list) and checks
                        and isinstance(checks[0], dict) else None)
            raw = f"{declared or 'http'}://{raw}"
        item["url"] = raw
        # THE ONE READING (infra_view.deploy_status): the workflow step shows the same word,
        # sentence and app link as Infra, and its drawer is one `ref` away.
        from boss_engine.services.infra_view import deploy_status as _deploy_status

        seen = _deploy_status(item.get("status"), decision_status=item.get("decision_status"),
                              steps=item.get("steps"), health=item.get("health_check_results"),
                              url=raw, failure=item.get("failure_reason"),
                              newest_for_target=newest,
                              success_means_healthy=source == "stack")
        kind = "stack" if source == "stack" else ("delivery" if item.get("trigger") else "registry")
        item.update({"ref": f"{kind}:{item['id']}",
                     "phase": seen["phase"], "word": seen["word"], "tone": seen["tone"],
                     "sentence": seen["sentence"], "now": seen["now"],
                     "open_url": seen["open_url"], "health": seen["health"]})
        for key in ("domains", "health_checks", "steps", "health_check_results",
                    "decision_status"):
            item.pop(key, None)
        out.append(item)

    # Is this app pointed at a host at all? Looked up by `app_name` deliberately: unlike the
    # deployment join above — where matching names would risk showing another app's result —
    # `deployment_targets` is KEYED by (project, app_name, environment). The name IS the
    # identity here, so matching on it is the correct lookup rather than a guess.
    linked_host = None
    linked_target_id = None
    if app_name:
        # IDENTITY, AND SCOPED TO THIS PROJECT.
        #
        # `t.app_name = :a` is exact string equality across every project. Two faults: an app
        # stored as "Lead‐Triage Inbox" carries a U+2010 hyphen and would never equal the ASCII
        # name the console holds, and a name shared by two projects would resolve to whichever
        # row was newest. The name is the identity here — but identity is the collapsed form,
        # which is the whole reason that function exists.
        _wanted_target = _identity_key(app_name)
        with begin(engine) as connection:
            for row in connection.execute(
                text("SELECT t.id AS target_id, t.app_name, h.name FROM deployment_targets t "
                     "JOIN deployment_hosts h ON h.id = t.host_id "
                     "WHERE t.project_id = :p AND t.status = 'active' "
                     "ORDER BY t.created_at DESC"),
                {"p": run_project}).mappings().all():
                if _identity_key(str(row["app_name"] or "")) != _wanted_target:
                    continue
                linked_host = row["name"]
                linked_target_id = row["target_id"]
                break
    return {"run_id": run_id, "deployments": out, "linked_host": linked_host,
            "linked_target_id": linked_target_id}


@app.post("/v1/code-tasks/{run_id}/preview")
@permit(P.PREVIEW_MANAGE, scope=Scope.of("code_task", path="run_id"))
def start_preview_endpoint(run_id: str, payload: Optional[dict] = None):
    """Preview a built app from retained rootfs, Docker, or a managed host process."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    p = payload or {}
    actor = str(p.get("actor") or "").strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    with begin(engine) as connection:
        run_row = connection.execute(
            text("SELECT project_id FROM code_task_runs WHERE id = :run_id"),
            {"run_id": run_id},
        ).mappings().first()
        if not run_row:
            raise HTTPException(status_code=404, detail="Code task run not found.")
        require_project_actor(
            connection, run_row["project_id"], actor, "task_create"
        )
    mode = str(p.get("mode", "auto")).lower()
    ttl = int(p.get("ttl_minutes", 60))
    from .services.preview_service import start_preview_async, stop_preview
    # Replace (don't accumulate): stop any prior running preview for this run so there's one live
    # preview per task — a fresh "Run preview" regenerates it.
    with begin(engine) as _c:
        prior = [r[0] for r in _c.execute(
            text("SELECT id FROM app_previews WHERE run_id=:r AND status IN ('running','starting')"),
            {"r": run_id}).fetchall()]
    for _pid in prior:
        try:
            stop_preview(engine, _pid, settings)
        except Exception:  # noqa: BLE001 — best-effort cleanup
            pass

    # ASYNC, BECAUSE THE WORK OUTLASTS THE REQUEST.
    #
    # Starting a preview clones, installs dependencies, builds and launches. That was done
    # inside this handler, and the console gives up after 120 seconds — so an operator was told
    # "the control plane did not answer within 120s" under a heading reading "Preview / tests
    # failed", while the build was still running and would often go on to succeed. Until the
    # attempt finished there was also no row at all: nothing in the previews list, nothing in
    # the Activity Log, nothing to poll. This returns a `starting` row immediately and lets the
    # console watch it the way it already watches everything else.
    try:
        return start_preview_async(
            engine, settings, run_id, ttl_minutes=ttl, mode=mode, actor=actor)
    except ValueError as exc:
        raise HTTPException(status_code=404, detail=str(exc))


