@app.post("/v1/previews/{preview_id}/smoke")
@permit(P.PREVIEW_MANAGE, scope=Scope.of("app_preview", path="preview_id"))
def smoke_preview_endpoint(preview_id: str, payload: Optional[dict] = None):
    """Tier-3 smoke canary: assert the live preview actually works (key routes), record a receipt."""
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    checks = (payload or {}).get("checks")
    if checks is not None:
        if not isinstance(checks, list) or not checks or len(checks) > 20:
            raise HTTPException(status_code=422, detail="checks must contain 1 to 20 reads")
        for check in checks:
            if not isinstance(check, dict) or str(check.get("method") or "GET").upper() not in {"GET", "HEAD"}:
                raise HTTPException(status_code=422, detail="preview smoke supports GET and HEAD only")
            path = check.get("path") or "/"
            if not isinstance(path, str) or not path.startswith("/") or path.startswith("//"):
                raise HTTPException(status_code=422, detail="smoke path must be relative to preview")
    with begin(engine) as connection:
        require_preview_reader(connection, preview_id)
    from .services.preview_service import smoke_test
    try:
        return smoke_test(engine, preview_id, checks, settings)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))


def _preview_served_elsewhere(request: Request, preview_id: str, path: str,
                              isolation: dict) -> Optional[Response]:
    """A browser that carries the console's session must not be served a preview HERE, on an
    origin with the whole API behind it: it is sent to the preview origin, where the cookie is
    stripped before anything reads it (apps/api/app/preview_origin.py). The preview listener
    itself never arrives with a cookie, so it is served."""
    from boss_engine.identity.authn import SESSION_COOKIE as _session_cookie
    if not request.cookies.get(_session_cookie):
        return None
    from boss_engine.services.preview_service import preview_origin_for
    scheme = "https" if request.url.scheme == "https" else "http"
    origin = preview_origin_for(request.headers.get("host"), scheme)
    if not origin:
        return JSONResponse({"detail": "previews are served from the preview origin "
                             "(BOSS_PREVIEW_ORIGIN / BOSS_PREVIEW_PORT), not from the API"},
                            status_code=403, headers=isolation)
    from urllib.parse import quote
    target = f"{origin}/v1/previews/{quote(preview_id, safe='')}/web/{quote(path, safe='/')}"
    if request.url.query:
        target += "?" + request.url.query
    return Response(status_code=307, headers={**isolation, "Location": target, "Cache-Control": "no-store"})


@app.api_route("/v1/previews/{preview_id}/web", methods=["GET", "POST", "PUT", "PATCH", "DELETE"])
@app.api_route("/v1/previews/{preview_id}/web/{path:path}", methods=["GET", "POST", "PUT", "PATCH", "DELETE"])
@public(reason=PublicReason.PREVIEW_CAPABILITY_URL, verifier=_identity_verifiers.preview_capability)
async def preview_web_proxy(preview_id: str, request: Request, path: str = ""):
    """Browser-facing reverse proxy to a running preview's loopback port — lets a preview be opened
    over the api's tailnet route (the preview's 127.0.0.1 port isn't reachable directly). Auth-exempt
    (gated by the unguessable preview id + TTL) — see require_transport_auth_for_v1."""
    from boss_engine.services.preview_service import preview_isolation_headers
    # ISOLATED, EVERY ANSWER (errors too): a sandbox CSP without allow-same-origin.
    isolation = preview_isolation_headers()
    moved = _preview_served_elsewhere(request, preview_id, path, isolation)
    if moved is not None:
        return moved
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.", headers=isolation)
    from .services.preview_service import proxy_preview
    from boss_engine.services.preview_cookies import inbound_cookie_header
    body = await request.body()
    # The app's OWN cookies only (tagged for this preview); never BOSS's, never another preview's.
    status, ctype, data, headers = proxy_preview(
        engine, preview_id, path, request.method, request.url.query,
        body or None, request.headers.get("content-type"), settings.sandbox_token,
        incoming_headers=dict(request.headers),
        app_cookie_header=inbound_cookie_header(preview_id, request.headers.get("cookie")),
    )
    set_cookies = list((headers or {}).pop("Set-Cookie", None) or [])
    # The previewed app's own CSP / CORS answers never replace the isolation.
    headers = {k: v for k, v in (headers or {}).items()
               if k.lower() not in {"content-security-policy", "access-control-allow-origin",
                                    "access-control-allow-credentials", "set-cookie"}}
    answer = Response(content=data, status_code=status, media_type=ctype, headers={**headers, **isolation})
    for cookie in set_cookies:   # already tagged and scoped by preview_cookies.outbound_set_cookie
        answer.headers.append("set-cookie", cookie)
    return answer


@app.websocket("/v1/previews/{preview_id}/web/")
@app.websocket("/v1/previews/{preview_id}/web/{path:path}")
@public(reason=PublicReason.PREVIEW_CAPABILITY_URL, verifier=_identity_verifiers.preview_running)
async def preview_websocket_proxy(websocket: WebSocket, preview_id: str, path: str = ""):
    """Bidirectional WebSocket proxy for SPA/live-preview development servers."""
    await websocket.accept()
    row = _identity_verifiers.preview_running(engine, preview_id)   # the capability (@public)
    if row is None:
        await websocket.close(code=4404, reason="preview not running")
        return
    base = str(row["url"]).rstrip("/")
    target = ("wss://" + base[8:] if base.startswith("https://") else
              "ws://" + base[7:] if base.startswith("http://") else base)
    target += "/" + path.lstrip("/")
    if websocket.url.query:
        target += "?" + websocket.url.query
    headers = ({"X-Sandbox-Token": settings.sandbox_token}
               if row["mode"] == "rootfs" and settings.sandbox_token else None)
    try:
        import websockets

        from boss_engine.services.env_refs import check_outbound

        check_outbound(target, headers)   # rc6 N-1: websockets writes past the http guard
        async with websockets.connect(target, additional_headers=headers) as upstream:
            async def client_to_upstream():
                while True:
                    message = await websocket.receive()
                    if message.get("text") is not None:
                        await upstream.send(message["text"])
                    elif message.get("bytes") is not None:
                        await upstream.send(message["bytes"])
                    else:
                        return

            async def upstream_to_client():
                async for message in upstream:
                    if isinstance(message, bytes):
                        await websocket.send_bytes(message)
                    else:
                        await websocket.send_text(message)

            await asyncio.gather(client_to_upstream(), upstream_to_client())
    except (WebSocketDisconnect, Exception):  # connection closure is reflected to the browser
        try:
            await websocket.close()
        except Exception:
            pass


@app.get("/v1/previews/{preview_id}/gate")
@permit(P.PREVIEW_READ, scope=Scope.of("app_preview", path="preview_id"))
def preview_gate_endpoint(preview_id: str):
    """What will approving this preview actually do?

    The console must be able to say "approve merges PR #123 and deploys `web` to
    hetzner-ci-01" BEFORE the click. An approval whose consequence is discovered afterwards is
    not an approval.
    """
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    from boss_engine.services.preview_approval import describe_gate

    with begin(engine) as connection:
        require_preview_reader(connection, preview_id)
        found = describe_gate(connection, preview_id=preview_id)
        if not found:
            raise HTTPException(status_code=404, detail="no such preview")
        return found


@app.post("/v1/previews/{preview_id}/approve")
@permit(P.PREVIEW_APPROVE, scope=Scope.of("app_preview", path="preview_id"))
def approve_preview_endpoint(preview_id: str, payload: open_bodies.PreviewApproveBody):
    """Approve what the preview shows — the single human gate on the path to live.

    This does NOT deploy. It approves the run's existing `review_pull_request` decision, which
    merges, which fires the one delivery trigger that already exists. Adding a second path into
    `deployment_runs` is the "two copies of one decision" defect that produced the
    preview-resolver and test-oracle bugs, so the seam is deliberately an approval and not a
    deploy call.
    """
    payload = payload.payload()
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    claimed = str(payload.get("actor") or "").strip()
    if current_mcp_human_attribution.get():
        actor = _decision_action_actor(claimed)
    else:
        actor = str(current_api_principal.get() or claimed).strip()
    if not actor:
        raise HTTPException(status_code=422, detail="actor is required")
    from boss_engine.services.preview_approval import (
        PreviewGateError, record_preview_approval,
    )

    with begin(engine) as connection:
        try:
            gate = record_preview_approval(
                connection, preview_id=preview_id, actor=actor,
                note=str(payload.get("note") or "").strip() or None)
        except PreviewGateError as exc:
            raise HTTPException(status_code=exc.status, detail=str(exc))
        require_project_actor(connection, gate["project_id"], actor, "decision_resolve")

    # Approve the merge decision through the SAME transition a human's approval uses. Calling
    # the existing transition keeps role checks, receipts and the merge itself on one path; a
    # private shortcut here would be a second way to merge.
    decision_id = gate["decision_id"]
    card = approve_decision_card(
        decision_id,
        DecisionActionRequest(actor=actor,
                              note=f"Preview {preview_id} approved by {actor}"
                                   + (f": {gate['note']}" if gate.get("note") else "")),
    )
    with begin(engine) as connection:
        emit_event(
            connection, gate["project_id"], "preview.approved", actor,
            "app_preview", preview_id,
            {"run_id": gate["run_id"], "repo": gate["repo"],
             "branch": gate["branch"], "preview_url": gate["preview_url"],
             "decision_id": decision_id,
             "pull_request_url": gate["pull_request_url"],
             "will_deploy": gate["will_deploy"], "note": (gate.get("note") or "")[:500]},
        )
        _record_governed(
            connection,
            project_id=gate["project_id"],
            actor=actor,
            effect_kind="preview.approve",
            dedupe_parts=[preview_id, decision_id],
            payload={"decision_id": decision_id, "run_id": gate["run_id"]},
        )
    return {"preview_id": preview_id, "decision_id": decision_id,
            "approved_by": actor, "decision": card,
            "app_targets": gate.get("app_targets", []),
            "note": "merge decision approved; delivery follows the merge trigger"}


