@app.post("/v1/sandboxes/{sandbox_id}/preserve")
@permit(P.SANDBOX_MANAGE, scope=Scope.of("sandbox", path="sandbox_id"))
def sandbox_preserve_endpoint(sandbox_id: str, payload: open_bodies.SandboxPreserveBody):
    """Refuse host retention until its cost and external effect are governed."""
    payload = payload.payload()
    actor = current_api_principal.get() or str(payload.get("actor") or "operator").strip()
    with begin(engine) as connection:
        require_sandbox_actor(connection, sandbox_id, actor)
    # The host hold API has no idempotency key. A receipt created only after calling it
    # cannot distinguish a timed-out success from a failed request; retrying can extend
    # retention twice and charge unreserved infrastructure time. Keep this closed until
    # the host accepts a stable request key and the API reserves budget and receipts it.
    raise HTTPException(
        status_code=409,
        detail=(
            "Sandbox preservation is disabled until budget reservation, host "
            "idempotency, and a durable receipt are enforced."
        ),
    )


@app.delete("/v1/sandboxes/{sandbox_id}")
@permit(P.SANDBOX_MANAGE, scope=Scope.of("sandbox", path="sandbox_id"))
def sandbox_destroy_endpoint(sandbox_id: str):
    actor = current_api_principal.get() or "operator"
    with begin(engine) as connection:
        project_id = require_sandbox_actor(connection, sandbox_id, actor)
        stored = connection.execute(
            text(
                """
                SELECT finalize_ctx FROM code_task_runs
                WHERE finalize_ctx->>'sandbox_task_id' = :sandbox_id
                  AND project_id = :project_id
                """
            ),
            {"sandbox_id": sandbox_id, "project_id": project_id},
        ).scalars().all()
        plan = None
        for ctx in stored:
            if isinstance(ctx, str):
                try:
                    ctx = json.loads(ctx)
                except ValueError:
                    ctx = None
            plan = _governed_plan(ctx if isinstance(ctx, dict) else None)
            if plan:
                break
        if plan:
            effect = _record_governed(
                connection,
                project_id=project_id,
                actor=actor,
                effect_kind="sandbox.delete",
                dedupe_parts=[sandbox_id, plan],
                payload={"sandbox_id": sandbox_id, "provider_called": False},
                rollback_plan=plan,
                destructive=True,
                worker=True,
            )
            return {
                "sandbox_id": sandbox_id,
                "status": "released",
                "provider_called": False,
                **effect,
            }
    # Releasing a retained VM discards its rootfs. Without a stored rollback
    # plan there is no host DELETE.
    raise HTTPException(
        status_code=409,
        detail=(
            "Sandbox deletion is disabled until an approved decision, rollback "
            "plan, and durable receipt are enforced."
        ),
    )


