class AgentTurnFailed(Exception):
    """An agent turn that failed, said as one sentence (see agent_turn_failed)."""

    def __init__(self, error: BaseException):
        super().__init__(str(error))
        self.error = error


@app.exception_handler(AgentTurnFailed)
async def agent_turn_failed(_request: Request, exc: AgentTurnFailed):
    """`detail` is the sentence every console error reader shows (lib/api-error.ts);
    `failure` carries kind/action/retry and `technical`, the line for a collapsed Details —
    never the SQL, the parameters or a traceback."""
    from boss_engine.services.model_failures import explain_turn_failure

    said = explain_turn_failure(exc.error)
    return JSONResponse(status_code=500, content={
        "detail": said["sentence"],
        "failure": {"kind": said["kind"], "headline": said["headline"],
                    "action": said["action"], "href": said.get("href"),
                    "retry": bool(said.get("retry")), "technical": said["detail"]},
    })


def _run_agent_chat(payload: AgentChatRequest, request: Request, *, endpoint: str) -> AgentChatResponse:
    """Shared handler for the BOSS chat interface. One brain (AgentService →
    IntentRouter) behind both the canonical endpoint and its deprecated alias, so
    all callers hit identical routing/persistence/confirmation logic and the
    (now tool-grounded) discuss path."""
    _enforce_high_cost_rate_limit(
        request, payload.project_id, payload.actor, endpoint=endpoint
    )
    with begin(engine) as connection:
        require_project_actor(
            connection,
            payload.project_id,
            payload.actor,
            "agent_chat",
        )
        try:
            result = orchestration_agent.chat(
                connection,
                project_id=payload.project_id,
                actor=payload.actor,
                thread_id=payload.thread_id,
                message=payload.message,
                confirm_plan_id=payload.confirm_plan_id,
                surface=payload.surface,
                external_ref=payload.external_ref,
                role=payload.role,
                mode=payload.mode,
                depth=payload.depth,
                context=payload.context,
                attachments=[
                    {"name": a.name, "media_type": a.media_type, "kind": a.kind,
                     "data": a.data}
                    for a in (payload.attachments or [])
                ],
            )
        except AgentThreadNotFoundError as error:
            raise HTTPException(status_code=404, detail=str(error)) from error
        except AgentThreadOwnershipError as error:
            raise HTTPException(status_code=403, detail=str(error)) from error
        except HTTPException:
            raise
        except Exception as error:  # noqa: BLE001
            # "Internal Server Error" IS THE FAILURE THIS WHOLE AREA IS ABOUT — and so is its
            # opposite. Five words that name nothing could not be acted on; the replacement,
            # the exception's class and text, put "IntegrityError: (psycopg.errors.
            # UniqueViolation) duplicate key value … [SQL: INSERT INTO agent_threads …" in the
            # dock on an existing install. One explainer (model_failures.explain_turn_failure) turns any
            # failure into a sentence; the technical line rides along for a collapsed Details,
            # and the whole traceback goes to the log.
            LOGGER.exception("agent chat failed on %s", endpoint)
            raise AgentTurnFailed(error) from error
        return AgentChatResponse(**result)


@app.post("/v1/engine/agent/action", response_model=AgentActionRunResponse)
@permit(P.ASSISTANT_CHAT, scope=Scope.project(body="project_id"),
        confine=(Confine.body("thread_id", "agent_thread"),))
def run_agent_action(payload: AgentActionRunRequest, request: Request) -> AgentActionRunResponse:
    """Execute one action the operator ACCEPTED by clicking its button.

    Deliberately does NOT go through the model. The operator saw a specific tool and specific
    arguments and clicked that; re-asking a model to interpret the click would let it drift into
    doing something adjacent, which is the opposite of what a confirmation button is for.

    The tool must be one BOSS is allowed to run from chat — the same set the agent itself may
    call — so a crafted request cannot reach a capability the conversation never had.
    """
    from boss_engine.context import EngineContext
    from boss_engine.tools import build_discuss_read_registry
    from boss_engine.tools.registry import ToolError

    _enforce_high_cost_rate_limit(
        request, payload.project_id, payload.actor, endpoint="/v1/engine/agent/action"
    )
    registry = build_discuss_read_registry(edition=settings.boss_edition)
    try:
        spec = registry.get(payload.tool)
    except ToolError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    if spec.kind != "write":
        raise HTTPException(
            status_code=400,
            detail=f"{spec.name!r} changes nothing; a button that runs a read is a no-op.",
        )

    with begin(engine) as connection:
        require_project_actor(connection, payload.project_id, payload.actor, "agent_chat")
        # IDENTITY (S2): the thread the press is recorded in must be this project's.
        _identity_verifiers.require_in_project(connection, "agent_threads", payload.thread_id,
                                               payload.project_id)
        if payload.thread_id:
            require_agent_thread_owner(connection, payload.thread_id, payload.actor)

    ctx = EngineContext(settings=settings, engine=engine)
    # THIS IS THE ACK, AND ONLY THIS PATH CAN GIVE IT.
    #
    # Some tools change a machine rather than a row — `run_on_host` opens a shell on a
    # registered host. The confirmation travels as a privileged invoke argument, outside
    # the model-controlled tool args. Reaching this line means an operator pressed the button.
    #
    # The distinction the operator drew after the 2026-09-02 wipe: an agent working WITH a
    # person is fine; an autonomous one performing a destructive act with nobody watching is
    # not. This is where that line is enforced.
    result = registry.invoke(
        spec.name, ctx, project_id=payload.project_id, actor=payload.actor,
        args=dict(payload.args or {}), operator_confirmed=True,
        # IDENTITY (S2): the person who pressed it must hold the TOOL's permission too
        # (`run_on_host` is host:exec), not only assistant:chat.
        auth=_request_identity(request),
    )
    ok = bool(result.get("ok", True))
    with begin(engine) as connection:
        emit_event(connection, payload.project_id, "agent.action_accepted", payload.actor,
                   "agent_action", spec.name,
                   {"tool": spec.name, "args": payload.args,
                    "ok": ok,
                    "thread_id": payload.thread_id})
        # THE PRESS GOES IN THE TRANSCRIPT, OR IT MIGHT AS WELL NOT HAVE HAPPENED.
        #
        # Reported: "I just did all the operations, then nothing happened, no workflow got
        # created, then I refreshed and it displays all 4 operations again."
        #
        # Both halves of that are this line's absence. The offers came back because the stored
        # message still carried them; and the agent re-proposed them because the next turn read
        # a history in which the operator appeared never to have clicked anything. An event row
        # is for audit — the model does not read events, it reads the thread.
        if payload.thread_id:
            from boss_engine.services.agent_service import AgentService

            AgentService(settings).record_action_outcome(
                connection, thread_id=payload.thread_id,
                action_id=str(payload.action_id or ""), tool=spec.name,
                args=dict(payload.args or {}), label=str(payload.label or ""),
                ok=ok, result=result,
                error=("" if ok else str(result.get("error") or "")),
            )
    return AgentActionRunResponse(
        ok=bool(result.get("ok", True)), tool=spec.name, result=result,
        error=(None if result.get("ok", True) else str(result.get("error") or "")),
    )


@app.post("/v1/engine/agent/chat", response_model=AgentChatResponse)
@permit(P.ASSISTANT_CHAT, scope=Scope.project(body="project_id"))
def engine_agent_chat(payload: AgentChatRequest, request: Request) -> AgentChatResponse:
    """The BOSS chat interface — one engine-native agent: routes intents, persists
    threads, gates confirmations, and answers questions grounded in live engine
    data via the read-tool layer. This is the canonical endpoint."""
