@app.post("/v1/console/v2/autonomy")
@permit(P.APPROVAL_RULE_MANAGE, scope=Scope.project(body="project_id"))
def console_v2_autonomy_set(payload: open_bodies.AutonomySetBody = Body(...)) -> dict:
    """Change the mode. Requires an actor, always.

    An autonomy change with no owner is the one kind this system must never accept: it is the
    act that makes every later act unattributable.
    """
    payload = payload.payload()
    from boss_engine.services.autonomy import describe, set_policy

    project_id = str(payload.get("project_id") or "").strip()
    mode = str(payload.get("mode") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")

    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    try:
        with begin(engine) as connection:
            actor = require_autonomy_operator(
                connection, project_id, payload.get("actor")
            )
            policy = set_policy(
                connection, project_id,
                mode=mode, actor=actor,
                threshold_usd=payload.get("threshold_usd"),
                max_risk_tier=payload.get("max_risk_tier"),
            )
            emit_event(
                connection, project_id, "autonomy.policy_set", actor,
                "project", project_id,
                {"mode": policy.mode, "threshold_usd": policy.threshold_usd,
                 "max_risk_tier": policy.max_risk_tier},
            )
            _record_governed(
                connection,
                project_id=project_id,
                actor=actor,
                effect_kind="autonomy.policy_set",
                dedupe_parts=[policy.mode, policy.threshold_usd, policy.max_risk_tier],
                payload={"mode": policy.mode},
            )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return describe(policy)


@app.post("/v1/console/v2/autonomy/apply")
@permit(P.DECISION_APPROVE, scope=Scope.project(body="project_id"))
def console_v2_autonomy_apply(payload: open_bodies.AutonomyApplyBody = Body(...)) -> dict:
    """Run the policy over the pending gates, and report the refusals as well as the approvals.

    A run that reports only what it approved is unreviewable: the operator cannot tell whether
    the policy is working, too tight, or silently doing nothing because every gate is missing a
    cost.
    """
    payload = payload.payload()
    from boss_engine.services.autonomy import apply_policy

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    with begin(engine) as connection:
        actor = require_autonomy_operator(
            connection, project_id, payload.get("actor")
        )
        result = apply_policy(connection, project_id, limit=int(payload.get("limit") or 25))
        emit_event(
            connection, project_id, "autonomy.policy_applied", actor,
            "project", project_id,
            {"mode": result["mode"], "approved_count": len(result["approved"]),
             "declined_count": len(result["declined"])},
        )
        _record_governed(
            connection,
            project_id=project_id,
            actor=actor,
            effect_kind="autonomy.policy_applied",
            dedupe_parts=[result["mode"], len(result["approved"]), len(result["declined"])],
            payload={"mode": result["mode"]},
        )
        return result


