@app.get(
    "/v1/coordination",
    response_model=CoordinationSnapshot,
)
@permit(P.WORK_ITEM_READ, scope=Scope.project(query="project_id"))
def coordination_snapshot_endpoint(project_id: str) -> CoordinationSnapshot:
    """Current role assignments and recent work for one authorized project.

    Source parity: the Command Center combines GET /v1/roles, the first 50
    GET /v1/tasks, and six GET /v1/metrics/in-flight items. The same canonical
    task lifecycle determines labels and activity in every client.
    """
    from boss_engine.services.self_observability import in_flight

    with begin(engine) as connection:
        require_project_reader(connection, project_id)
    roles = role_list(project_id).items
    tasks = task_list(project_id=project_id, limit=50).items
    with begin(engine) as connection:
        recent_work = in_flight(connection, project_id, limit=6)
    return build_coordination_snapshot(roles, tasks, recent_work)


@app.get("/v1/self/diagnostics")
@permit(P.SYSTEM_READ, scope=Scope.org())
def self_diagnostics(preview_root: Optional[str] = None) -> dict:
    """What BOSS can see about the container it is itself running in.

    BOSS can interrogate its own database in detail and can inspect the hosts it DEPLOYS to, and
    had nothing for the machine it runs on. `claude code agent exited -9` therefore cost about an
    hour of hypothesis-testing — OOM killer, deploy restart, or something internal — and was
    settled by reading code rather than data. One number (an OOM count of zero) answers it.

    Needs no docker socket: /proc and the container's own cgroup files are enough, and the
    socket is not something an application container should be given.
    """
    from boss_engine.services.self_observability import self_snapshot

    return self_snapshot(preview_root)


