@app.post("/v1/artifacts/{artifact_id}/rebuild")
@permit(P.ARTIFACT_REBUILD, scope=Scope.project(body="project_id"))
def rebuild_change_record(artifact_id: str, payload: open_bodies.ArtifactRebuildBody = Body(default_factory=open_bodies.ArtifactRebuildBody)) -> dict:
    """Recompose a change record from the run it came from.

    A record renders facts that are still in the database, so a composition fix should reach the
    documents already written rather than only the next one — otherwise "it is fixed now" is
    something the operator has to take on trust while looking at the old dump.
    """
    payload = payload.payload()
    from boss_engine.services.workflow_capability_runner import rebuild_record

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    with begin(engine) as connection:
        result = rebuild_record(connection, project_id, artifact_id)
    if not result.get("ok"):
        raise HTTPException(status_code=409, detail=str(result.get("error") or "rebuild failed"))
    return result


@app.get("/v1/artifacts/{artifact_id}/media")
@permit(P.ARTIFACT_READ, scope=Scope.of("artifact", path="artifact_id"))
def get_artifact_media(artifact_id: str) -> Response:
    """The media file an artifact holds, so a rendered edit can be watched before it is published.

    Only for media BOSS keeps in its own artifact storage (`media_storage.store_local`); a file
    kept in Drive is opened with its Drive link. Read access is the project's, exactly as for
    the artifact itself, and the stored path is re-checked against THIS project's media
    directory before anything is opened — a path in a row is not trusted to choose a file.
    Served as a file response, so a browser's player can seek (Range requests).
    """
    from fastapi.responses import FileResponse

    from boss_engine.services.media_storage import MediaStorageError, local_file_for

    with begin(engine) as connection:
        row = connection.execute(
            text("SELECT project_id, title, content FROM artifacts WHERE id = :a"),
            {"a": artifact_id},
        ).mappings().first()
        if not row:
            raise HTTPException(status_code=404, detail="Artifact not found")
        require_project_reader(connection, row["project_id"])
    content = row["content"] if isinstance(row["content"], dict) else {}
    if not content.get("local_path"):
        where = content.get("view_url")
        raise HTTPException(
            status_code=409,
            detail=("this artifact is not a media file BOSS keeps itself"
                    + (f"; it is in Drive at {where}" if where else "")))
    try:
        path = local_file_for(settings, str(row["project_id"]), content)
    except MediaStorageError as error:
        raise HTTPException(status_code=404, detail=str(error)) from error
    name = str(content.get("name") or row["title"] or path.name)
    return FileResponse(
        path,
        media_type=str(content.get("mime_type") or "") or "application/octet-stream",
        filename=name,
        content_disposition_type="inline",
    )


@app.get("/v1/artifacts/{artifact_id}/pdf")
@permit(P.ARTIFACT_READ, scope=Scope.of("artifact", path="artifact_id"))
def get_artifact_pdf(artifact_id: str) -> Response:
    """A document as a PDF anyone can open, mail, or put in a folder.

    The change record is markdown, which is the right storage format and the wrong DELIVERY
    format: the console rendered it in a <pre> and the operator's verdict was "I dont think
    anyone will be able to read that". Rendered on demand rather than served from the file the
    step wrote, so a record that predates the PDF, or one whose file has been cleaned up,
    still downloads.
    """
    from boss_engine.services import change_record
    from .services.pdf_render import pdf_page_count, render_markdown_pdf

    with begin(engine) as connection:
        row = connection.execute(
            text("SELECT project_id, title, content FROM artifacts WHERE id = :a"),
            {"a": artifact_id},
        ).mappings().first()
        if not row:
            raise HTTPException(status_code=404, detail="Artifact not found")
        require_project_reader(connection, row["project_id"])
    content = row["content"] if isinstance(row["content"], dict) else {}
    markdown = str(content.get("markdown") or "").strip()
    if not markdown:
        raise HTTPException(status_code=409, detail="this artifact has no document body")
    title, subtitle, body = change_record.body_for_pdf(markdown)
    try:
        pdf_bytes = render_markdown_pdf(body, title=title or row["title"],
                                        subtitle=subtitle or None)
    except Exception as error:  # noqa: BLE001
        raise HTTPException(
            status_code=500, detail=f"PDF render failed: {type(error).__name__}: {error}"
        ) from error
    name = re.sub(r"[^A-Za-z0-9]+", "-", str(row["title"] or "document")).strip("-").lower()
    return Response(
        content=pdf_bytes,
        media_type="application/pdf",
        headers={
            "Content-Disposition": f'attachment; filename="{name or "document"}.pdf"',
            "X-PDF-Page-Count": str(pdf_page_count(pdf_bytes)),
        },
    )


