def _set_project_skill_state(
    connection,
    skill_id: str,
    payload: SkillToggleRequest,
    *,
    enabled: bool,
) -> dict:
    require_project_actor(
        connection, payload.project_id, payload.actor, "pack_manage"
    )
    catalog = entitlements.list_skills(
        payload.project_id, connection=connection
    )
    skill = next((item for item in catalog if item["id"] == skill_id), None)
    if skill is None:
        raise HTTPException(status_code=404, detail="Skill not found in project catalog.")
    if skill.get("source") == "authored":
        # An authored skill's switch is its own `enabled` (PATCH /v1/skill-definitions/{key}).
        # A project_skills row here would be a second switch the catalogue does not read.
        raise HTTPException(
            status_code=409,
            detail=(f"{skill_id} is a skill this project authored. Turn it on or off with "
                    "its own switch on the Skills and MCP page."))
    if skill.get("system") is True and not enabled:
        raise HTTPException(status_code=409, detail="System skills cannot be disabled.")
    rows = list_project_skills(connection, payload.project_id)
    row = next((item for item in rows if item["skill_id"] == skill_id), None)
    if row is None:
        row = ensure_skill(
            connection,
            payload.project_id,
            skill_id,
            source="system" if skill.get("system") is True else "tenant",
            enabled=enabled,
            on_demand=(
                bool(payload.on_demand)
                if payload.on_demand is not None
                else skill.get("load") == "on_demand"
            ),
            publisher=skill.get("publisher") or {},
            provenance=skill.get("provenance") or {},
            # THE DECLARED RISK TIER, carried across from the catalogue.
            #
            # Without it `config` is empty, and workflow_custom_steps.resolve_risk reads
            # config.risk_tier — so every skill registered this way bound at UNKNOWN_RISK (2).
            # That is wrong in both directions at once: a tier-0 read like video.plan_edit
            # "always requires a person", which makes a workflow unrunnable unattended, and a
            # tier-3 publish is understated as 2. The tier a skill declares is the only
            # tier anything downstream can act on, so it has to arrive with the row.
            config={"risk_tier": int(skill["risk_tier"])}
            if skill.get("risk_tier") is not None else None,
            actor=payload.actor,
        )
    # REPAIR A ROW THAT PREDATES THE FIX ABOVE.
    #
    # ensure_skill only runs when the row is absent, so every skill registered before the tier
    # was carried across still has an empty config — and goes on binding at UNKNOWN_RISK
    # forever. Enabling is the action an operator already takes when a skill misbehaves, so it
    # is the right place to put the repair: it makes the fix reachable from the console instead
    # of needing a migration nobody knows to run.
    declared = skill.get("risk_tier")
    if declared is not None:
        current = row.get("config") if isinstance(row.get("config"), dict) else {}
        if current.get("risk_tier") is None:
            connection.execute(
                text("UPDATE project_skills SET config = COALESCE(config, '{}'::jsonb) "
                        "|| CAST(:c AS JSONB) "
                        "WHERE project_id = :p AND skill_id = :s"),
                {"c": json.dumps({"risk_tier": int(declared)}),
                 "p": payload.project_id, "s": skill_id},
            )

    updated = (
        enable_skill(
            connection,
            payload.project_id,
            skill_id,
            payload.actor,
            on_demand=payload.on_demand,
        )
        if enabled
        else disable_skill(
            connection, payload.project_id, skill_id, payload.actor
        )
    )
    return updated or row


