# --------------------------------------------------------------------------- #
# SKILLS AS AUTHORABLE OBJECTS. See services/skill_definitions for the reasoning.
# --------------------------------------------------------------------------- #
# NOT "/v1/skills" — THAT PATH WAS ALREADY TAKEN.
#
# A GET on /v1/skills has served the runtime skill catalogue (enablement records, provider
# skills, load order) since long before this. Registering a second GET on the same path does not
# error: FastAPI matches the first route and the new one is simply never reached, which is how
# an endpoint ships, returns 200, and answers a different question than the one asked. Caught by
# calling it against the deployment rather than by reading the code.
#
# These endpoints are about the DEFINITION — the authored object — so they say so.
@app.get("/v1/skill-definitions")
@permit(P.SKILL_READ, scope=Scope.project(query="project_id"))
def list_skill_definitions(project_id: str) -> dict:
    """Every skill this project has authored, with whether it forces an approval, what uses it
    (`references`: the custom steps that run it and the agents that hold it) and what the
    catalogue says about it (`catalogue`: its effective tier, and whether it can run)."""
    from boss_engine.services.skill_catalogue import entries
    from .services.skill_definitions import list_skills

    with begin(engine) as connection:
        skills = list_skills(connection, project_id, with_references=True)
        catalogue = entries(connection, project_id, settings=get_settings())
    for skill in skills:
        item = catalogue.get(skill["skill_key"]) or {}
        skill["catalogue"] = {
            # The tier the floor will USE — never below the wrapped executor's or the MCP
            # tool's, whatever the skill itself declares (skill_catalogue's risk rule).
            "risk_tier": item.get("risk_tier", skill["risk_tier"]),
            "usable": bool(item.get("usable", False)),
            "reason": item.get("reason"),
            "runs_through": item.get("runs_through", ""),
            # Why a person approves every run whatever the tier (its MCP server is not
            # reviewed), or None. The Skills page shows it beside the tier.
            "requires_person": item.get("requires_person"),
        }
        if item.get("requires_person"):
            skill["requires_approval"] = True
    return {"project_id": project_id, "skills": skills}


@app.post("/v1/skill-definitions", status_code=201)
@permit(P.SKILL_MANAGE, scope=Scope.project(body="project_id"))
def save_skill_definition(payload: open_bodies.SkillDefinitionSaveBody) -> dict:
    """Author or replace one skill. Idempotent on (project, skill_key).

    Validation is deliberately here and not in the console: a skill is attachable from the
    canvas, from an agent and from the workflow agent, and three callers checking the same
    rules is three chances for them to disagree.
    """
    payload = payload.payload()
    from .services.skill_definitions import SkillDefinitionError, SkillExistsError, save_skill

    project_id = str(payload.get("project_id") or "").strip()
    actor = str(payload.get("actor") or "").strip() or "executive_console"
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "workflow_manage")
        try:
            return {"skill": save_skill(
                connection, project_id=project_id, actor=actor,
                skill_key=str(payload.get("skill_key") or ""),
                label=str(payload.get("label") or ""),
                behaviour_kind=str(payload.get("behaviour_kind") or ""),
                summary=str(payload.get("summary") or ""),
                knowledge=str(payload.get("knowledge") or ""),
                inputs=payload.get("inputs") or [],
                produces=payload.get("produces") or [],
                config=payload.get("config") or {},
                # `int(x or 1)` saved every tier-0 skill as tier 1: 0 is falsy. Absent means 1;
                # anything else is checked (with a sentence) by save_skill.
                risk_tier=1 if payload.get("risk_tier") in (None, "") else payload["risk_tier"],
                trusted=bool(payload.get("trusted", False)),
                enabled=bool(payload.get("enabled", True)),
                mode=str(payload.get("mode") or "upsert"),
            )}
        except SkillExistsError as error:
            # 409: a create named a key that is taken. Saving used to silently replace it.
            raise HTTPException(status_code=409, detail=str(error)) from error
        except SkillDefinitionError as error:
            # 422, not 500: everything this raises is something the operator can fix, and the
            # message is already written for them.
            raise HTTPException(status_code=422, detail=str(error)) from error


@app.patch("/v1/skill-definitions/{skill_key}")
@permit(P.SKILL_MANAGE, scope=Scope.project(body="project_id"))
def switch_skill_definition(
    skill_key: str, payload: open_bodies.SkillDefinitionSwitchBody,
) -> dict:
    """Turn an authored skill on or off and change nothing else about it.

    The delete refusal has always said "turn the skill off instead", and until this there was
    no way to short of re-saving every field.
    """
    from .services.skill_definitions import SkillDefinitionError, set_skill_enabled

    body = payload.payload()
    project_id = str(body.get("project_id") or "").strip()
    actor = str(body.get("actor") or "").strip() or "executive_console"
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    if not isinstance(body.get("enabled"), bool):
        raise HTTPException(status_code=422, detail="enabled must be true or false.")
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "workflow_manage")
        try:
            return {"skill": set_skill_enabled(
                connection, project_id=project_id, actor=actor, skill_key=skill_key,
                enabled=body["enabled"])}
        except SkillDefinitionError as error:
            raise HTTPException(status_code=404, detail=str(error)) from error


# --------------------------------------------------------------------------- #
# Connecting a channel the operator owns                                        #
# --------------------------------------------------------------------------- #


@app.put("/v1/channels/{provider}/client")
@permit(P.INTEGRATION_MANAGE, scope=Scope.project(body="project_id"))
def save_channel_oauth_client(provider: str, payload: open_bodies.ChannelOAuthClientBody) -> dict:
    """Store THIS PROJECT's own Google OAuth client.

    Per project rather than per installation: a shared client would make the BOSS vendor the
    applicant for every customer's YouTube access — one verification covering everybody, one
    quota pool, and one credential whose compromise reaches every connected channel.

    The secret goes to the secret backend. No table holds it, so no agent can query it: an
    agent that can read a credential can also print it into a message explaining an error.
    """
    payload = payload.payload()
    from .services.channel_oauth import ChannelOAuthError, save_oauth_client

    if provider != "youtube":
        raise HTTPException(status_code=404, detail=f"no channel provider '{provider}'")
    project_id = str(payload.get("project_id") or "").strip()
    actor = str(payload.get("actor") or "").strip() or "executive_console"
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "integration_manage")
        try:
            return save_oauth_client(
                connection, settings, project_id=project_id, actor=actor,
                client_id=str(payload.get("client_id") or ""),
                client_secret=str(payload.get("client_secret") or ""),
                redirect_uri=str(payload.get("redirect_uri") or ""),
            )
        except ChannelOAuthError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error


@app.get("/v1/channels/{provider}/client")
@permit(P.INTEGRATION_READ, scope=Scope.project(query="project_id"))
def channel_oauth_client_status(provider: str, project_id: str) -> dict:
    """Whether a client is configured, and the redirect URI to register with Google.

    Returns NEITHER half of the client. The hint is the last twelve characters of the id —
    enough for a person to tell which one is loaded, useless to anyone else.
    """
    from .services.channel_oauth import oauth_client_status

    if provider != "youtube":
        raise HTTPException(status_code=404, detail=f"no channel provider '{provider}'")
    with begin(engine) as connection:
        status = oauth_client_status(connection, project_id, settings)
    # The path the operator must paste into Google, built from what this API is actually
    # reachable at — so it cannot disagree with the endpoint that receives the redirect.
    base = (settings.google_oauth_redirect_uri or "").strip()
    return {
        **status,
        "callback_path": f"/v1/channels/{provider}/callback",
        "installation_default_redirect_uri": base or None,
    }


