@app.get("/v1/channels/{provider}/callback")
@public(reason=PublicReason.OAUTH_STATE_BOUND_CALLBACK, verifier=_identity_verifiers.channel_oauth_state)
def finish_channel_connection(
    provider: str,
    code: str = "",
    state: str = "",
    error: str = "",
) -> Response:
    """Where Google sends the operator back.

    Deliberately UNAUTHENTICATED, and safe to be: it carries no project id and does nothing
    without a `state` nonce that BOSS itself minted and stored, which is single-use — the
    pending row is activated or gone once spent. Requiring a bearer token here would break the
    flow, because this request is a browser redirect and not an API call.

    Returns HTML rather than JSON: a person is looking at this in a tab.
    """
    from .services.channel_oauth import ChannelOAuthError, complete

    def page(title: str, body: str, ok: bool) -> Response:
        colour = "#34d399" if ok else "#f2647a"
        return Response(
            content=(
                "<!doctype html><meta charset='utf-8'>"
                "<title>BOSS — channel connection</title>"
                "<style>body{background:#090d17;color:#e6edf3;font:16px/1.6 system-ui,sans-serif;"
                "display:grid;place-items:center;height:100vh;margin:0}"
                "div{max-width:32rem;padding:2rem}"
                f"h1{{color:{colour};font-size:1.25rem;margin:0 0 .75rem}}"
                "p{margin:.5rem 0;opacity:.85}</style>"
                f"<div><h1>{title}</h1><p>{body}</p>"
                "<p>You can close this tab and return to the console.</p></div>"
            ),
            media_type="text/html",
            status_code=200 if ok else 400,
        )

    if provider != "youtube":
        return page("Unknown provider", f"BOSS has no channel provider '{provider}'.", False)
    if error:
        # Google's own words. The commonest is access_denied, which simply means the operator
        # pressed Cancel — not a fault, and it should not read like one.
        return page("Not connected", f"Google returned: {error}", False)
    with begin(engine) as connection:
        try:
            result = complete(connection, settings, code=code, state=state)
        except ChannelOAuthError as failure:
            return page("Could not connect", str(failure), False)
    channel = result.get("channel") or {}
    if channel.get("verified"):
        return page("Channel connected",
                    f"BOSS can now publish to <b>{channel.get('title')}</b>.", True)
    return page("Connected, but unverified",
                "The credential is stored, but BOSS could not read the channel back: "
                f"{channel.get('reason')}", True)


@app.get("/v1/channels")
@permit(P.INTEGRATION_READ, scope=Scope.project(query="project_id"))
def list_channel_connections(project_id: str) -> dict:
    """Connected channels. Never returns a credential — only whether one is bound."""
    with begin(engine) as connection:
        rows = connection.execute(
            text(
                "SELECT c.connection_key, c.status, c.health_status, c.granted_capabilities, "
                "       c.max_risk_tier, c.provenance, c.updated_at, d.integration_key "
                "  FROM integration_connections c "
                "  JOIN integration_definitions d ON d.id = c.integration_definition_id "
                " WHERE c.project_id = :p AND d.category = 'media_channel' "
                " ORDER BY c.connection_key"
            ),
            {"p": project_id},
        ).mappings().all()
    # A CONNECTION IS NOT USABLE WITHOUT THE CLIENT THAT MINTED IT.
    #
    # `health_status` records how the last token exchange went and is never revisited. The
    # OAuth CLIENT — the Client ID and secret from the operator's own Google Cloud project — is
    # what refreshes that token, and it lives somewhere else entirely: a secret ref, or the
    # installation's environment. Lose it and every stored token becomes unrefreshable while
    # the row still reads `active / healthy`.
    #
    # That is not a cosmetic discrepancy. It reported "connected, healthy, drive.read,
    # drive.write" for a channel that could not make a single call, a workflow run then failed
    # on its first step with "No Google OAuth client for this project", and the health field had
    # said the opposite one minute earlier. A signal that confidently contradicts the thing it
    # describes is worse than no signal.
    from .services.channel_oauth import oauth_client_status

    with begin(engine) as connection:
        client_ready = bool(
            oauth_client_status(connection, project_id, settings).get("configured"))

    return {"project_id": project_id, "channels": [
        {
            "connection_key": r["connection_key"],
            "provider": r["integration_key"],
            "status": r["status"],
            "health": r["health_status"] if client_ready else "unusable",
            # Said plainly, next to the health it explains, so nobody has to know that a
            # connection and a client are two different things to understand the answer.
            **({} if client_ready else {
                "unusable_reason":
                    "this project has no Google OAuth client, so the stored token cannot be "
                    "refreshed and every call fails. Channels → add the Client ID, secret and "
                    "redirect URI from your own Google Cloud project.",
            }),
            "capabilities": r["granted_capabilities"],
            "max_risk_tier": r["max_risk_tier"],
            # The channel identity, NOT the provenance blob: that carries the state nonce and
            # who started it, neither of which belongs on a list endpoint.
            "channel": (r["provenance"] or {}).get("channel") or {},
            "updated_at": r["updated_at"].isoformat() if r["updated_at"] else None,
        }
        for r in rows
    ]}


@app.delete("/v1/channels/{provider}")
@permit(P.INTEGRATION_MANAGE, scope=Scope.project(query="project_id"))
def disconnect_channel(
    provider: str,
    project_id: str,
    connection_key: str = "youtube_default",
    actor: str = "executive_console",
) -> dict:
    """Revoke the token at Google and locally. Either alone leaves a live credential."""
    from .services.channel_oauth import ChannelOAuthError, disconnect

    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "integration_manage")
        try:
            result = disconnect(connection, settings, project_id=project_id,
                                connection_key=connection_key, actor=actor)
        except ChannelOAuthError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        _record_governed(
            connection,
            project_id=project_id,
            actor=actor,
            effect_kind="channel.disconnect",
            dedupe_parts=[provider, connection_key],
            payload={"provider": provider, "connection_key": connection_key,
                     "status": result.get("status")},
        )
        return result


@app.post("/v1/role-skills/sync")
@permit(P.AGENT_ABILITY_ASSIGN, scope=Scope.project(body="project_id"))
def sync_project_role_skills(payload: ProjectBody) -> dict:
    """Give every installed agent the skills its role spec says it may use.

    Needed because role specs and role_skills were never joined: an agent was TOLD what it
    could use, in its prompt, and HELD nothing. Exposed as an endpoint and not only a bootstrap
    step because every install that already exists is in that state.

    Additive. It never removes an assignment an operator made by hand.
    """
    payload = payload.payload()
    from boss_engine.services.skill_definitions import sync_role_skills

    project_id = str(payload.get("project_id") or "").strip()
    actor = str(payload.get("actor") or "").strip() or "executive_console"
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    with begin(engine) as connection:
        # THE SAME GATE AS ASSIGNING ONE SKILL. This call grants every skill a role
        # spec names. Leaving it open let any caller materialise those grants, including
        # a member without workflow_manage.
        require_project_actor(connection, project_id, actor, "workflow_manage")
        return sync_role_skills(
            connection, project_id=project_id, actor=actor)


