@app.post("/v1/changesets/{changeset_id}/approve", response_model=ChangeSetSummary)
@permit(P.CHANGESET_APPROVE, scope=Scope.of("changeset", path="changeset_id"))
def approve_changeset(
    changeset_id: str,
    payload: ChangeSetApproveRequest,
) -> ChangeSetSummary:
    payload.actor = _mcp_reviewed_actor(payload.actor)
    with begin(engine) as connection:
        project_id = project_id_for_changeset(connection, changeset_id)
        required_roles = resource_plane.required_approvers_for_changeset(
            connection, changeset_id
        )
        approver_roles: Optional[list[str]] = None
        if required_roles and identity_guard.identity_enforced():
            # Dual control under identity: the guard checked changeset:approve; the person must
            # also hold it THROUGH one of the named approver roles (a role binding at the org or
            # this project, direct or by group) — never the legacy members table.
            approver_roles = _roles_granting(project_id, P.CHANGESET_APPROVE, required_roles)
            if not approver_roles:
                reason = ("Dual control: approving needs one of the approver roles "
                          + ", ".join(required_roles) + ".")
                record_policy_denial(project_id, payload.actor, "changeset_approve", reason)
                raise HTTPException(status_code=403, detail={
                    "error": "forbidden", "reason": "approver_role_required",
                    "required_roles": list(required_roles), "message": reason})
        elif required_roles:
            # Dual-control: only an active member holding one of the named approver
            # roles may approve (no generic providerops_manage shortcut).
            try:
                members.require_member(
                    connection,
                    project_id,
                    payload.actor,
                    role_keys_any=required_roles,
                )
            except (
                ProjectMemberNotFoundError,
                ProjectMemberPermissionError,
            ) as error:
                record_policy_denial(
                    project_id, payload.actor, "changeset_approve", str(error)
                )
                raise HTTPException(status_code=403, detail=str(error)) from error
            require_authenticated_actor_binding(
                project_id, payload.actor, "changeset_approve"
            )
        else:
            require_project_actor(
                connection,
                project_id,
                payload.actor,
                "providerops_manage",
            )
        from boss_engine.identity.approvals import ApprovalPending

        try:
            item = resource_plane.approve_changeset(
                connection,
                changeset_id=changeset_id,
                actor=payload.actor,
                approver_roles=approver_roles,
            )
        except ApprovalPending as pending:
            # C-1: the ChangeSet's tier-3 decision went through decisions.transition, which
            # recorded this person as the first of two (this transaction commits it).
            return JSONResponse(status_code=202, content=pending.body())
        except InvalidDecisionTransitionError as error:
            raise HTTPException(status_code=409, detail=str(error)) from error
        except (ProjectMemberNotFoundError, ProjectMemberPermissionError) as error:
            record_policy_denial(project_id, payload.actor, "changeset_approve", str(error))
            raise HTTPException(status_code=403, detail=str(error)) from error
        except (ChangeSetNotFoundError, ValueError) as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        return ChangeSetSummary(**item)


@app.post("/v1/changesets/{changeset_id}/apply", response_model=ChangeSetApplyResponse)
@permit(P.CHANGESET_APPROVE, scope=Scope.of("changeset", path="changeset_id"))
def apply_changeset(
    changeset_id: str,
    payload: ChangeSetApplyRequest,
) -> ChangeSetApplyResponse:
    from boss_engine.services.changeset_apply import (
        ApplyAuthorityRefused, apply_changeset as durable_apply,
    )

    def authorize(connection, project_id):
        try:
            require_project_actor(connection, project_id, payload.actor, "providerops_manage")
        except HTTPException as error:
            raise ApplyAuthorityRefused("Current ChangeSet apply permission is required.") from error
        if identity_guard.identity_enforced():
            from boss_engine.identity import authz, request_memo
            from boss_engine.identity.scope import ResolvedScope
            ctx = identity_guard.REQUEST_IDENTITY.get()
            if ctx is None:
                raise ApplyAuthorityRefused("A canonical principal is required.")
            request_memo.clear()
            decision = authz.check(ctx, P.CHANGESET_APPROVE,
                                  ResolvedScope.in_project(ctx.principal.org_id, project_id),
                                  db=connection)
            if not decision.allowed:
                raise ApplyAuthorityRefused("Current ChangeSet apply permission is required.")
        return payload.actor

    try:
        result = durable_apply(engine, resource_plane, changeset_id=changeset_id,
                               authorize=authorize, created_by_job_id=payload.created_by_job_id,
                               dry_run=payload.dry_run)
    except ApplyAuthorityRefused as error:
        raise HTTPException(status_code=403, detail=str(error)) from error
    except (ChangeSetNotFoundError, ValueError) as error:
        raise HTTPException(status_code=422, detail=str(error)) from error
    return ChangeSetApplyResponse(
        status=result["status"],
        changeset=ChangeSetSummary(**result["changeset"]),
        resource_receipts=[
            ResourceReceiptSummary(**item)
            for item in result.get("resource_receipts", [])
        ],
        expected_receipts=result.get("expected_receipts"),
        decision_id=result.get("decision_id"),
    )


@app.post(
    "/v1/changesets/{changeset_id}/terraform-export",
    response_model=TerraformExportResponse,
)
@permit(P.INFRA_PROVISION, scope=Scope.of("changeset", path="changeset_id"))
def export_changeset_terraform(
    changeset_id: str,
    payload: TerraformExportRequest,
) -> TerraformExportResponse:
    """Track 1 Terraform export (BOSS-66): project a ChangeSet to .tf.json.

    The BOSS DB stays canonical — the export is a deterministic downstream
    projection. Opt-in: rejected unless at least one deployment target enabled
    terraform_export, or the caller forces it (audited escape hatch)."""
    with begin(engine) as connection:
        project_id = project_id_for_changeset(connection, changeset_id)
        require_project_actor(
            connection,
            project_id,
            payload.actor,
            "providerops_manage",
        )
        opt_in_targets = terraform_export_service.count_terraform_export_targets(
            connection, project_id
        )
        forced = False
        if opt_in_targets == 0:
            if not payload.force:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Terraform export is opt-in and disabled for this "
                        "project: no deployment target has terraform_export "
                        "enabled. Enable a target or pass force=true "
                        "(audited)."
                    ),
                )
            forced = True
            emit_event(
                connection,
                project_id,
                "terraform_export.forced",
                payload.actor,
                "changeset",
                changeset_id,
                {
                    "reason": (
                        "No deployment target has terraform_export enabled; "
                        "actor forced the export."
                    ),
                },
            )
        try:
            result = terraform_export_service.export_changeset(
                connection,
                settings,
                changeset_id,
                actor=payload.actor,
            )
        except (
            ValueError,
            terraform_export_service.TerraformExportError,
        ) as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        commit_result = None
        if payload.commit_to_repo:
            try:
                commit_result = terraform_export_service.commit_export_to_repo(
                    settings,
                    changeset_id,
                    result["canonical"],
                    branch=payload.repo_branch or "main",
                )
            except Exception as error:  # noqa: BLE001 — artifact is stored; report
                raise HTTPException(
                    status_code=502,
                    detail=(
                        "Terraform export artifact stored, but the repo "
                        f"commit failed: {error}"
                    ),
                ) from error
        return TerraformExportResponse(
            **result,
            forced=forced,
            opt_in_targets=opt_in_targets,
            commit=commit_result,
        )


