@app.post(
    "/v1/projects/{project_id}/terraform-drift-reconcile",
    response_model=TerraformDriftReconcileResponse,
)
def terraform_drift_reconcile(
    project_id: str,
    payload: TerraformDriftReconcileRequest,
) -> TerraformDriftReconcileResponse:
    """Track 1 inbound drift-sync (BOSS-69): three-way compare BOSS desired
    state vs a customer-supplied .tf/plan JSON vs synced live inventory.

    THE INVARIANT: the supplied .tf NEVER mutates the DB directly. Divergence
    yields a drift report plus a PROPOSED corrective ChangeSet through the
    normal dual-control approval gate; rejecting it changes nothing. Shares
    the terraform_export opt-in gate (force is the audited escape hatch)."""
    with begin(engine) as connection:
        require_project_actor(
            connection,
            project_id,
            payload.actor,
            "providerops_manage",
        )
        if bool(payload.tf_json) == bool(payload.plan_json):
            raise HTTPException(
                status_code=422,
                detail="Provide exactly one of tf_json or plan_json.",
            )
        opt_in_targets = terraform_export_service.count_terraform_export_targets(
            connection, project_id
        )
        forced = False
        if opt_in_targets == 0:
            if not payload.force:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "Terraform drift-sync is opt-in and disabled for this "
                        "project: no deployment target has terraform_export "
                        "enabled. Enable a target or pass force=true "
                        "(audited)."
                    ),
                )
            forced = True
            if not payload.dry_run:
                emit_event(
                    connection,
                    project_id,
                    "terraform_drift.forced",
                    payload.actor,
                    "project",
                    project_id,
                    {
                        "reason": (
                            "No deployment target has terraform_export "
                            "enabled; actor forced the drift reconcile."
                        ),
                    },
                )
        try:
            result = terraform_drift_service.terraform_drift_reconcile(
                connection,
                settings,
                project_id,
                tf_payload=payload.tf_json or payload.plan_json,
                provider_account_id=payload.provider_account_id,
                actor=payload.actor,
                dry_run=payload.dry_run,
                plane=resource_plane,
            )
        except (
            ValueError,
            terraform_drift_service.TerraformDriftError,
        ) as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        return TerraformDriftReconcileResponse(
            **result,
            forced=forced,
            opt_in_targets=opt_in_targets,
        )


@app.post("/v1/iac/detect", response_model=IacDetectResponse)
@permit(P.INFRA_READ, scope=Scope.org(), readonly_post=True)
def detect_iac_change(payload: IacDetectRequest) -> IacDetectResponse:
    """Detect IaC files and/or whether a code task is an IaC-authoring task (no tools run)."""
    file_map = payload.files if isinstance(payload.files, dict) else None
    if file_map:
        iac_files = iac_verify_service.detect_iac_files(file_map)
    elif payload.file_paths:
        iac_files = iac_verify_service.detect_iac_files(payload.file_paths)
    else:
        iac_files = []
    spec = {
        "task_type": payload.task_type,
        "instructions": payload.instructions,
        "acceptance_criteria": payload.acceptance_criteria or [],
    }
    is_task = iac_verify_service.is_iac_task(spec, payload.title)
    return IacDetectResponse(
        is_iac_task=is_task or bool(iac_files),
        iac_files=list(iac_files),
        file_count=len(iac_files),
        task_type=payload.task_type,
    )


@app.post("/v1/iac/verify", response_model=IacVerifyResponse)
@permit(P.INFRA_PROVISION, scope=Scope.org())
def run_iac_verify(payload: IacVerifyRequest) -> IacVerifyResponse:
    """Run the credential-scrubbed IaC verification lane on an operator-supplied file map.

    Executes fmt → init/validate → tflint → checkov/tfsec → plan-dry (plan-live is a
    recorded skip) with no cloud credentials in the subprocess environment. Fail-closed:
    a missing toolchain binary fails the corresponding step rather than silently skipping.
    Input paths are relative-only and confined to a disposable workdir.
    """
    return verify_iac(payload)


def verify_iac(payload: IacVerifyRequest) -> IacVerifyResponse:
    """run_iac_verify, for callers inside the API.

    A route handler is FastAPI's to call (test_no_code_calls_a_route_handler)."""
    import tempfile
    from pathlib import Path

    with tempfile.TemporaryDirectory(prefix="boss-iac-verify-") as scratch:
        workdir = Path(scratch)
        for rel_path, content in payload.files.items():
            target = workdir / rel_path
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content, encoding="utf-8")
        result = iac_verify_service.run_iac_verify_lane(
            workdir,
            settings,
            files=payload.files,
        )
    return IacVerifyResponse(
        ok=result.ok,
        tf_binary=result.tf_binary,
        scanner=result.scanner,
        files=list(result.files),
        steps=[IacVerifyStepSummary(**step.to_dict()) for step in result.steps],
        actor=payload.actor,
        project_id=payload.project_id,
    )


@app.post("/v1/iac/plan", response_model=IacVerifyResponse)
@permit(P.INFRA_PROVISION, scope=Scope.org())
def run_iac_plan(payload: IacVerifyRequest) -> IacVerifyResponse:
    """Plan-oriented IaC lane entrypoint (same credential-free lane as /v1/iac/verify).

    Terraform/OpenTofu ``plan -refresh=false`` is step ``plan_dry``; there is no separate
    plan-only binary path because plan depends on init/validate graph resolution.
    """
    return verify_iac(payload)


