@app.post("/v1/comms/inbox/ingest", response_model=InboxMessageSummary, status_code=201)
@permit(P.COMMS_MANAGE, scope=Scope.project(body="project_id"))
def ingest_inbox_message(payload: InboxMessageIngestRequest) -> InboxMessageSummary:
    with begin(engine) as connection:
        require_project_actor(
            connection,
            payload.project_id,
            payload.actor,
            "comms_manage",
        )
        item = comms.ingest_inbox_message(
            connection,
            payload.project_id,
            payload.channel,
            payload.body,
            payload.actor,
            subject=payload.subject,
            raw_ref=payload.raw_ref,
            data_boundary=payload.data_boundary,
        )
        parsed = item.get("parsed") or {}
        if parsed.get("kind") == "decision_reply":
            comms.advance_inbox(
                connection,
                payload.project_id,
                item["id"],
                status="parsed",
                ack="parsed",
                terminal=False,
                actor=payload.actor,
            )
            parse_error = parsed.get("parse_error")
            decision_id = parsed.get("decision_id")
            action = parsed.get("action")
            # IDENTITY (S2): a reply may only answer a decision of the project it arrived in.
            if isinstance(decision_id, str) and not parse_error and connection.execute(
                    text("SELECT 1 FROM decisions WHERE id = :d AND project_id = :p"),
                    {"d": decision_id, "p": payload.project_id}).first() is None:
                parse_error = "decision_not_in_project"
            if parse_error or not isinstance(decision_id, str) or not isinstance(action, str):
                comms.deadletter_inbox_message(
                    connection,
                    payload.project_id,
                    item["id"],
                    actor=payload.actor,
                    reason=str(parse_error or "decision_reply_missing_id_or_action"),
                    payload={"parsed": parsed},
                    remediation=(
                        parsed.get("remediation")
                        if isinstance(parsed.get("remediation"), str)
                        else None
                    ),
                )
                return inbox_message_summary_from_row(
                    reload_inbox_message(connection, item["id"])
                )
            comms.advance_inbox(
                connection,
                payload.project_id,
                item["id"],
                status="routed",
                ack="routed",
                terminal=False,
                actor=payload.actor,
                route_kind="decision",
                target_ref=decision_id,
            )
            try:
                decision_row = decisions.transition(
                    connection,
                    decision_id,
                    action=action,
                    actor=payload.actor,
                    note=parsed.get("note") if isinstance(parsed.get("note"), str) else None,
                    delegate_to=(
                        parsed.get("delegate_to")
                        if isinstance(parsed.get("delegate_to"), str)
                        else None
                    ),
                    external_ref=payload.raw_ref,
                )
            except (
                DecisionNotFoundError,
                InvalidDecisionTransitionError,
                ProjectMemberNotFoundError,
                ProjectMemberPermissionError,
                ValueError,
            ) as error:
                comms.deadletter_inbox_message(
                    connection,
                    payload.project_id,
                    item["id"],
                    actor=payload.actor,
                    reason=str(error),
                    payload={"parsed": parsed},
                )
                return inbox_message_summary_from_row(
                    reload_inbox_message(connection, item["id"])
                )

            comms.mark_inbox_actioned(
                connection,
                payload.project_id,
                item["id"],
                actor=payload.actor,
                decision_id=decision_id,
                outcome_status=decision_row["status"],
            )
            return inbox_message_summary_from_row(
                reload_inbox_message(connection, item["id"])
            )
        return inbox_message_summary_from_row(item)


