def _job_effect_permission(kind: str) -> Optional[str]:
    if kind.startswith("infra."):
        return "infra_provision"
    if kind.startswith(("github.", "software_factory.", "docs.")):
        return "github_manage"
    if kind.startswith("comms."):
        return "comms_manage"
    if kind.startswith(("webhook.", "a2a.", "work_tracker.")):
        return "integration_manage"
    if kind.startswith("providerops."):
        return "providerops_manage"
    return None


def _require_job_kind_permission(kind: str, project_id: str) -> None:
    """Under identity, a job's EFFECT is authorized by its kind's catalogue permission
    (boss_engine.identity.job_permissions), at the job's project, beyond the route's
    work_item:manage. A kind BOSS does not know is refused: no unmapped effect by default."""
    from boss_engine.identity.job_permissions import permission_for, require_job_kind

    from .routers.identity_access import require_permission

    # C-2: THE check (engine, shared with every dead-letter requeue path); under enforce it
    # raises JobKindRefused (the app's handler answers 422/401/403).
    require_job_kind(kind, project_id)
    permission = permission_for(kind)
    if permission is not None and not identity_guard.identity_enforced():
        require_permission(None, permission, project_id, label="job_kind")   # shadow's ledger


@app.post("/v1/jobs", response_model=JobSummary, status_code=201)
@permit(P.WORK_ITEM_MANAGE, scope=Scope.project(body="project_id"),
        confine=(Confine.body("task_id", "task"), Confine.body("work_item_id", "work_item"),
                 Confine.body("reservation_id", "budget_reservation"),
                 Confine.body("tracker_binding_id", "work_tracker_binding"),
                 Confine.body("allocation_id", "resource_allocation")))
def create_job(payload: JobCreateRequest) -> JobSummary:
    with begin(engine) as connection:
        # Under enforce the actor is the verified principal (the actor rule); a hard-coded "ceo"
        # was refused as actor_mismatch for everyone, so no identity caller could queue a job.
        actor = identity_guard.request_actor() or current_api_principal.get() or "ceo"
        require_project_actor(connection, payload.project_id, actor, "workflow_execute")
        effect_permission = _job_effect_permission(payload.kind)
        if effect_permission:
            require_project_actor(connection, payload.project_id, actor, effect_permission)
        _require_job_kind_permission(payload.kind, payload.project_id)
        job_payload = {
            **payload.payload,
            **(
                {"completion_contract": payload.completion_contract.model_dump()}
                if payload.completion_contract
                else {}
            ),
            **(
                {"requires_reservation": True}
                if payload.requires_reservation
                else {}
            ),
            **(
                {"reservation_id": payload.reservation_id}
                if payload.reservation_id
                else {}
            ),
        }
        try:
            result = jobs.create_job(
                connection,
                project_id=payload.project_id,
                task_id=payload.task_id,
                kind=payload.kind,
                payload=job_payload,
                priority=payload.priority,
                max_attempts=payload.max_attempts,
                run_after_seconds=payload.run_after_seconds,
                data_boundary=payload.data_boundary,
                work_item_id=payload.work_item_id,
                tracker_binding_id=payload.tracker_binding_id,
                allocation_id=payload.allocation_id,
                priority_score=payload.priority_score,
                workload_class=payload.workload_class,
                resource_units=payload.resource_units,
                dedupe_key=payload.dedupe_key,
            )
        except ValueError as error:
            raise HTTPException(status_code=400, detail=str(error)) from error
        if result.get("status") == "skipped":
            raise HTTPException(
                status_code=409,
                detail=result.get("skipped_reason") or "run already stopped",
            )
        if payload.reservation_id:
            budget.attach_job(
                connection,
                payload.project_id,
                payload.reservation_id,
                result["id"],
            )
        return JobSummary(**result)


@app.post("/v1/bootstrap/seed")
@permit(P.OWNER_ASSIGN, scope=Scope.org())
def bootstrap_seed(actor: str = "ceo") -> dict[str, str]:
    if not settings.bootstrap_seed_api_enabled:
        record_policy_denial(
            settings.default_project_id,
            actor,
            "member_manage",
            "BOSS_BOOTSTRAP_SEED_API_ENABLED is false.",
        )
        raise HTTPException(
            status_code=403,
            detail="Bootstrap seed API is disabled. Use the local make seed command or explicitly enable BOSS_BOOTSTRAP_SEED_API_ENABLED.",
        )
    with begin(engine) as connection:
        project_exists = connection.execute(
            text("SELECT 1 FROM projects WHERE id = :project_id"),
            {"project_id": settings.default_project_id},
        ).first()
        if project_exists:
            require_project_actor(
                connection,
                settings.default_project_id,
                actor,
                "member_manage",
            )
    seed()
    with begin(engine) as connection:
        emit_event(
            connection,
            settings.default_project_id,
            "bootstrap.seed_executed",
            actor,
            "project",
            settings.default_project_id,
            {"source": "api"},
        )
    return {"status": "seeded", "actor": actor}


