@app.get("/v1/settings")
@permit(P.SETTINGS_READ, scope=Scope.project(query="project_id"))
def get_project_settings(project_id: str) -> dict:
    """The knobs, what each is worth now, and where that value came from.

    Showing the value without its SOURCE is the difference between "this project runs three
    agents" and "nobody has chosen, so it runs the deployment default" — and only one of those
    tells an operator whether changing it here will do anything.
    """
    from boss_engine.services import project_settings as ps
    from boss_engine.services.setup_service import connected_engines
    with begin(engine) as connection:
        chosen = ps.get_all(connection, project_id)
        connected = connected_engines(connection, settings, project_id)
        from boss_engine.services.setup_service import engine_login_states

        login_states = engine_login_states(connection, project_id)
        # THE PROJECT'S OWN CHOICES DECIDE WHICH MODELS A LANE OFFERS. The lists were drawn from
        # the deployment settings, so choosing codex as the reviewer here still offered Claude's
        # models beside it — the reviewer's model list follows the reviewer's harness, and that
        # harness is this project's setting, not the environment's.
        effective = ps.applied(connection, project_id, settings)
        knobs = []
        for key, spec in ps.KNOBS.items():
            default = getattr(settings, spec["attr"], None)
            value = chosen.get(key, default)
            source = "project" if key in chosen else "deployment default"
            if key in ps.MODEL_FOR_ENGINE.values():
                harness = ps.harness_for_model_knob(spec, effective)
                if not ps.model_is_compatible_with_harness(default, harness):
                    default = ""
                # The run uses the layered value, which may have suppressed a model inherited
                # from the old engine. Show that value rather than the stale deployment alias.
                value = getattr(effective, spec["attr"], default)
                if value != chosen.get(key, getattr(settings, spec["attr"], None)):
                    source = "engine default"
            knobs.append({
                "key": key, "label": spec["label"], "help": spec["help"],
                "kind": spec["kind"], "min": spec.get("min"), "max": spec.get("max"),
                # A picker cannot be drawn without the options, and the options are the ones
                # THIS PROJECT has connected — not every harness BOSS can drive. Offering all
                # eleven on an install with one credential is a dropdown where ten choices
                # fail at build time and nothing says which.
                "choices": (ps.offered_choices(connection, effective, project_id, spec, value)
                            if spec["kind"] == "choice" else None),
                # WHETHER THE LIST IS A LIMIT OR A SUGGESTION. `codex --model` takes any name
                # OpenAI offers, so a closed dropdown would make a model that works
                # unselectable the week after it ships. Claude's four aliases ARE the complete
                # set — BOSS resolves them itself — so that picker stays closed.
                "open_choices": (
                    ps.model_choice_is_open(
                        spec, ps.harness_for_model_knob(spec, effective))
                    if spec["kind"] == "choice" else False),
                "value": value,
                "default": default,
                "source": source,
            })
    return {"project_id": project_id, "knobs": knobs,
            # So the console can say WHY the list is short, and what to do about it, instead
            # of showing a one-item picker with no explanation.
            "connected_engines": sorted(connected),
            "connected_engine_detail": [connected[name] for name in sorted(connected)],
            # A connected engine whose login the provider just rejected: shown as broken.
            "engine_login_states": login_states}


@app.put("/v1/settings/{key}")
@permit(P.SETTINGS_UPDATE, scope=Scope.project(body="project_id"))
def put_project_setting(key: str, payload: ProjectSettingBody, request: Request) -> dict:
    """Set one knob, or hand it back to the deployment default by sending no value.
    An `If-Match` (the knob's version from GET /v1/govern) refuses a stale edit with 412."""
    from .govern_guard import require_fresh
    payload = payload.payload()
    from boss_engine.services import project_settings as ps
    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    from .govern_guard import govern_actor
    actor = govern_actor(payload.get("actor"), current_api_principal.get())
    spec = ps.KNOBS.get(key)
    if spec is None:
        raise HTTPException(status_code=404, detail=f"'{key}' is not a setting BOSS knows about.")
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "providerops_manage")
        require_fresh(request, *ps.version_of(connection, project_id, key))
        if payload.get("value") in (None, ""):
            ps.clear_one(connection, project_id, key, actor=actor)
            paired = ps.MODEL_FOR_ENGINE.get(key)
            if paired:
                ps.clear_one(connection, project_id, paired, actor=actor)
            effective = ps.applied(connection, project_id, settings)
            value = getattr(effective, spec["attr"], None)
            source = ("deployment default" if value == getattr(settings, spec["attr"], None)
                      else "engine default")
            return {"key": key, "value": value, "source": source}
        try:
            before = ps.get_all(connection, project_id).get(key)
            value = ps.set_one(connection, project_id, key, payload.get("value"), actor)
            if key in ps.MODEL_FOR_ENGINE.values():
                effective = ps.applied(connection, project_id, settings)
                harness = ps.harness_for_model_knob(spec, effective)
                if not ps.model_is_compatible_with_harness(value, harness):
                    raise HTTPException(
                        status_code=422,
                        detail=f"{spec['label']}: '{value}' is not a model for {harness}.",
                    )
        except ps.UnknownKnob as error:
            raise HTTPException(status_code=404, detail=str(error)) from error
        except ValueError as error:
            # The bound, in words: "between 1 and 16" is actionable, "invalid" is not.
            raise HTTPException(status_code=422, detail=str(error)) from error
        # A MODEL BELONGS TO THE ENGINE IT WAS CHOSEN FOR. Switching a lane from claude_code to
        # codex left `opus` set beside it — a pairing that fails at the first escalation, with
        # the picker still showing it because a current value is never dropped from the list.
        # So a lane's model is cleared when its engine changes, and the reply says so.
        cleared = None
        paired = ps.MODEL_FOR_ENGINE.get(key)
        if paired and before != value and ps.get_all(connection, project_id).get(paired):
            ps.clear_one(connection, project_id, paired, actor=actor)
            cleared = paired
    return {"key": key, "value": value, "source": "project",
            **({"cleared": cleared} if cleared else {})}


