@writing_get(app, "/v1/decisions/inbox", response_model=DecisionInboxResponse)
@permit(P.DECISION_READ, scope=Scope.project(query="project_id"), writes_on_get=True)
def decision_inbox(
    project_id: str, limit: Optional[int] = None, offset: int = 0
) -> DecisionInboxResponse:
    if limit is not None and (limit < 1 or limit > 200):
        raise HTTPException(status_code=400, detail="limit must be between 1 and 200.")
    if offset < 0:
        raise HTTPException(status_code=400, detail="offset must be >= 0.")
    limit_sql = "LIMIT :limit" if limit is not None else ""
    with begin(engine) as connection:
        require_project_reader(connection, project_id)
        decisions.expire_overdue(connection, project_id)
        params: dict[str, Any] = {"project_id": project_id, "offset": offset}
        if limit is not None:
            params["limit"] = limit
        rows = connection.execute(
            text(
                f"""
                SELECT id, task_id, question, status, risk_tier, default_action,
                       recommendation, options, cost_summary, deadline_at,
                       approved_by, approved_at, delegated_to, delegated_by,
                       delegated_at, revision_requested_by, revision_requested_at,
                       executed_by, executed_at, resolution_note, external_ref,
                       created_at, updated_at
                FROM decisions
                WHERE project_id = :project_id
                ORDER BY
                    CASE status
                        WHEN 'pending' THEN 0
                        WHEN 'delegated' THEN 1
                        WHEN 'approved' THEN 2
                        ELSE 3
                    END,
                    risk_tier DESC,
                    created_at DESC
                {limit_sql}
                OFFSET :offset
                """
            ),
            params,
        ).mappings().all()
        return DecisionInboxResponse(
            project_id=project_id,
            items=[decision_card_from_row(row) for row in rows],
            limit=limit,
            offset=offset,
        )


@app.get("/v1/decisions/{decision_id}", response_model=DecisionCard)
@permit(P.DECISION_READ, scope=Scope.of("decision", path="decision_id"))
def get_decision(decision_id: str, project_id: Optional[str] = None) -> DecisionCard:
    with begin(engine) as connection:
        params: dict[str, Any] = {"decision_id": decision_id}
        project_filter = ""
        if project_id:
            params["project_id"] = project_id
            project_filter = "AND project_id = :project_id"
        row = connection.execute(
            text(
                f"""
                SELECT id, project_id, task_id, question, status, risk_tier, default_action,
                       recommendation, options, cost_summary, deadline_at,
                       approved_by, approved_at, delegated_to, delegated_by,
                       delegated_at, revision_requested_by, revision_requested_at,
                       executed_by, executed_at, resolution_note, external_ref,
                       created_at, updated_at
                FROM decisions
                WHERE id = :decision_id
                {project_filter}
                """
            ),
            params,
        ).mappings().first()
        if not row:
            raise HTTPException(status_code=404, detail="Decision not found")
        require_project_reader(connection, row["project_id"])
        return decision_card_from_row(row)


@app.post("/v1/decisions/digests", response_model=DecisionDigestResponse, status_code=201)
@permit(P.SYSTEM_OPERATE, scope=Scope.project(body="project_id"))
def create_decision_digest(payload: DecisionDigestRequest) -> DecisionDigestResponse:
    with begin(engine) as connection:
        require_project_actor(
            connection,
            payload.project_id,
            payload.actor,
            "decision_resolve",
        )
        result = decisions.create_digest(
            connection,
            project_id=payload.project_id,
            actor=payload.actor,
            max_items=payload.max_items,
            low_risk_max=payload.low_risk_max,
            urgent_risk_min=payload.urgent_risk_min,
        )
        outbox_message_id = None
        if payload.channel:
            require_project_actor(
                connection,
                payload.project_id,
                payload.actor,
                "comms_manage",
            )
            outbox = comms.create_outbox_message(
                connection,
                payload.project_id,
                payload.channel,
                "BOSS decision digest",
                result["body"],
                payload.dedupe_key or f"decision-digest-{result['artifact_id']}",
                payload.actor,
                payload.data_boundary,
            )
            outbox_message_id = outbox["id"]
        return DecisionDigestResponse(
            status=result["status"],
            artifact_id=result["artifact_id"],
            outbox_message_id=outbox_message_id,
            decision_count=result["decision_count"],
            urgent_count=result["urgent_count"],
            batched_count=result["batched_count"],
            body=result["body"],
        )


@app.post("/v1/decisions/{decision_id}/approve", response_model=DecisionCard)
@permit(P.DECISION_APPROVE, scope=Scope.of("decision", path="decision_id"))
def approve_decision(
    decision_id: str, payload: DecisionActionRequest
) -> DecisionCard:
    return approve_decision_card(decision_id, payload)


def approve_decision_card(
    decision_id: str, payload: DecisionActionRequest
) -> DecisionCard:
    """approve_decision, for callers inside the API.

    A route handler is FastAPI's to call (test_no_code_calls_a_route_handler)."""
    from boss_engine.identity.approvals import ApprovalPending

    with begin(engine) as connection:
        try:
            row = approve_decision_in(connection, decision_id, payload)
        except ApprovalPending as pending:
            # §6.13: the first of two approvals of a tier-3 decision is recorded (this transaction
            # commits it); the decision stays pending for a second person.
            return JSONResponse(status_code=202, content=pending.body())
        return decision_card_from_row(row)


def approve_decision_in(connection, decision_id: str, payload: DecisionActionRequest) -> dict:
    """The approval itself, inside the caller's transaction (POST /v1/decisions/{id}/approve, and
    an action that must record something AND approve in one commit, e.g. a security review's
    "Fix selected"). Raises HTTPException for a refusal, ApprovalPending for a first of two
    approvals; the caller's transaction then rolls back or commits as a whole."""
    # Ordinary keys use their bound principal; exact MCP confirmations use
    # the independently authenticated human reviewer.
    payload.actor = _decision_route_actor(connection, decision_id, payload.actor)
    require_decision_actor_binding(connection, decision_id, payload.actor)
    try:
        row = decisions.transition(
            connection,
            decision_id,
            action="approve",
            actor=payload.actor,
            note=payload.note,
            delegate_to=payload.delegate_to,
            external_ref=payload.external_ref,
            content_hash=payload.content_hash,
            # A person overriding the merge gate (CI failed or could not be read), with the
            # note transition() requires. Never a deploy: ci_gate refuses a forced deploy.
            force=payload.force,
        )
    except DecisionNotFoundError as error:
        raise HTTPException(status_code=404, detail=str(error)) from error
    except InvalidDecisionTransitionError as error:
        raise HTTPException(status_code=409, detail=str(error)) from error
    except (ProjectMemberNotFoundError, ProjectMemberPermissionError) as error:
        raise_decision_actor_error(decision_id, payload.actor, error)
    _record_governed(
        connection,
        project_id=row["project_id"],
        actor=payload.actor,
        effect_kind="decision.approve",
        dedupe_parts=[decision_id],
        payload={"decision_id": decision_id, "status": row.get("status")},
    )
    return row


