@app.post("/v1/delivery-workflows/schedules/tick")
@permit(P.SYSTEM_OPERATE, scope=Scope.project(body="project_id"))
def tick_workflow_schedules(payload: open_bodies.WorkflowSchedulesTickBody) -> dict:
    """Start whatever is due. Called by the worker on its ordinary poll.

    Idempotent by construction: the dedupe key is the SCHEDULED moment, so a tick that runs
    twice — two workers, or one retried after a crash — produces one run.
    """
    payload = payload.payload()
    from boss_engine.services import workflow_schedules as schedules

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    # The worker may share a principal-bound API key with an operator in a local install.
    # Use that authenticated identity for authorization rather than trusting a claimed actor.
    actor = current_api_principal.get() or str(payload.get("actor") or "system").strip()
    with begin(engine) as connection:
        require_project_actor(connection, project_id, actor, "workflow_execute")
        started = schedules.run_due(connection, project_id=project_id)
    return {"started": started, "count": len(started)}


@app.get("/v1/delivery-workflows/capabilities")
@permit(P.WORKFLOW_READ, scope=Scope.project_or_org(query="project_id"))
def list_delivery_capabilities(project_id: str | None = None) -> dict:
    """What a step can be. Feeds the builder palette and documents the risk floor."""
    from boss_engine.services.workflow_capabilities import (
        MANUAL_APPROVAL_RISK_FLOOR,
        blocks,
        palette,
    )
    from boss_engine.services import step_agents
    from boss_engine.services import workflow_custom_steps as custom_steps

    # The project's own steps belong in the same palette as the built-in ones — a customer
    # should not have to know which of their steps BOSS wrote. Optional, because the palette is
    # also browsed before a project is chosen.
    custom: list[dict] = []
    # WHO A STEP CAN BE GIVEN TO: this project's roster, the same list the publish check uses
    # (workflows.project_roster). It was a hard-coded set of role keys, so an agent made on the
    # Agents page was never offered. `human` is offered for gates only.
    roster: frozenset[str] = frozenset()
    agents: list[dict] = []
    if project_id and database_is_reachable(engine):
        from boss_engine.services.workflows import project_roster

        with begin(engine) as connection:
            custom = [s for s in custom_steps.list_steps(connection, project_id)
                      if s["enabled"]]
            roster = project_roster(connection, project_id)
            agents = step_agents.project_agents(connection, project_id)

    return {
        "capabilities": palette(),
        "custom_steps": custom,
        # Control blocks the runtime has always supported and the builder never offered, so a
        # customer could only ever author a straight line.
        "blocks": blocks(),
        # THE PROJECT'S AGENTS, not only the bundled ones: an agent made in Agent Studio has
        # to be offered as a captain, or the builder cannot put it on the step it was made for.
        # And not a bundled one the operator deleted: project_roster leaves those out, so the
        # builder never offers a captain publish would then refuse. Before a project is chosen
        # only a person can be named.
        "roles": ([r for r in sorted(roster) if r != step_agents.HUMAN] + [step_agents.HUMAN]
                  if roster else [step_agents.HUMAN]),
        "agents": [{"role_key": a["role_key"], "name": a["name"], "holds": a["holds"],
                    "mcp": a.get("mcp") or []}
                   for a in agents],
        "human_role": step_agents.HUMAN,
        "manual_approval_risk_floor": MANUAL_APPROVAL_RISK_FLOOR,
        "note": (
            "A capability at or above the risk floor always requires a person, whatever a "
            "workflow asks for."
        ),
    }


@app.get("/v1/delivery-workflows/custom-steps")
@permit(P.WORKFLOW_READ, scope=Scope.project(query="project_id"))
def list_delivery_custom_steps(project_id: str) -> dict:
    """A project's own steps, plus everything it could bind a new one to.

    The bindable lists come back with the SAME risk tiers the floor will use, so the builder
    can say "this will need an approval" while the customer is choosing — rather than after
    they try to publish.
    """
    from boss_engine.services.workflow_capabilities import MANUAL_APPROVAL_RISK_FLOOR
    from boss_engine.services import workflow_custom_steps as custom_steps

    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")

    from boss_engine.services.mcp_registry import tool_tier
    from boss_engine.services.skill_catalogue import bindable as catalogue_bindable

    # THE ONE CATALOGUE (skill_catalogue). This read `project_skills`, labelled it "Your
    # skills", and on a real install (boss-1) that was five BOSS system skills and none of the
    # operator's — while every skill agents actually hold had no row there and could not be
    # placed. Every skill the project has is bindable now, with the tier the floor will use.
    with begin(engine) as connection:
        steps = custom_steps.list_steps(connection, project_id)
        bindable_skills = catalogue_bindable(connection, project_id, settings=get_settings())

    # The RECORDED state every MCP screen reads (what the last probe found, with the last-known
    # tools of a server that is down). A GET never probes (R5: every GET is read-only — a probe
    # records its result); the screens ask the servers with POST /v1/mcp/servers/load?check=stale.
    bindable_servers = []
    with begin(engine) as connection:
        recorded_servers = list_mcp_servers(connection, project_id, enabled_only=True)
    for server in recorded_servers:
        entry = {
            "id": server["id"], "name": server["name"],
            "risk_tier": server["risk_tier"], "trusted": server["trusted"],
            "tools": [{"name": tool["name"], "description": tool.get("description", ""),
                       "risk_tier": tool_tier(server, tool["name"])}
                      for tool in server["tools"]],
            # An unreachable server is shown, not hidden. Hiding it would look like the server
            # was never registered, and the customer would add it again. `None` (never
            # checked) is reported as reachable-unknown rather than as down.
            "reachable": server["reachable"] is not False,
            "last_checked_at": server["last_checked_at"],
        }
        if server["reachable"] is False:
            entry["error"] = server["last_error"]
            entry["status_note"] = server["status_note"]
        bindable_servers.append(entry)

    return {
        "steps": steps,
        "bindable": {"skills": bindable_skills, "mcp_servers": bindable_servers},
        "manual_approval_risk_floor": MANUAL_APPROVAL_RISK_FLOOR,
    }


def _delivery_workflow_actor(payload: Optional[dict] = None, actor: Optional[str] = None) -> str:
    """Attribute console workflow writes to the authenticated project member."""
    claimed = actor if actor is not None else (payload or {}).get("actor")
    return str(current_api_principal.get() or claimed or "executive_console").strip()


def _authorize_delivery_target_input(
    connection, project_id: str, actor: str, run_input: dict,
) -> None:
    """Bind any selected host target to this project before saving or starting work."""
    if "target_id" not in run_input and "environment" not in run_input:
        return
    require_project_actor(connection, project_id, actor, "providerops_manage")
    if "target_id" not in run_input:
        # The deploy step picks its target by this environment.
        _require_production(None, project_id, run_input.get("environment"))
        return
    target_id = str(run_input.get("target_id") or "").strip()
    if not target_id:
        raise HTTPException(status_code=422, detail="target_id must be nonempty")
    target = connection.execute(
        text("SELECT environment FROM deployment_targets "
             "WHERE id=:id AND project_id=:project_id"),
        {"id": target_id, "project_id": project_id},
    ).mappings().first()
    if target is None:
        raise HTTPException(status_code=404, detail="deployment target not found")
    environment = str(run_input.get("environment") or "").strip()
    if environment and environment != target["environment"]:
        raise HTTPException(
            status_code=422, detail="environment does not match deployment target",
        )
    # The run's deploy step ships to this target: a production one needs deployment:production.
    _require_production(None, project_id, target["environment"])


@app.post("/v1/delivery-workflows/custom-steps")
@permit(P.WORKFLOW_CREATE, scope=Scope.project(body="project_id"))
def create_delivery_custom_step(payload: WorkflowCustomStepBody) -> dict:
    """Define a step. The risk tier is NOT accepted from the caller — it is resolved from
    whatever the step binds, which is what stops "custom step" being a way around the floor."""
    payload = payload.payload()
    from boss_engine.services import workflow_custom_steps as custom_steps

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    actor = _delivery_workflow_actor(payload)
    try:
        with begin(engine) as connection:
            require_project_actor(connection, project_id, actor, "workflow_manage")
            return custom_steps.create(
                connection,
                project_id=project_id,
                label=str(payload.get("label") or ""),
                summary=str(payload.get("summary") or ""),
                binding_kind=str(payload.get("binding_kind") or ""),
                skill_id=payload.get("skill_id") or None,
                mcp_server_id=payload.get("mcp_server_id") or None,
                mcp_tool_name=payload.get("mcp_tool_name") or None,
                inputs=payload.get("inputs"),
                knowledge=str(payload.get("knowledge") or ""),
                produces=payload.get("produces"),
                step_key=payload.get("step_key") or None,
                actor=actor,
            )
    except custom_steps.CustomStepError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error


@app.patch("/v1/delivery-workflows/custom-steps/{step_key}")
@permit(P.WORKFLOW_CREATE, scope=Scope.project(body="project_id"))
def update_delivery_custom_step(step_key: str, payload: WorkflowCustomStepUpdateBody) -> dict:
    """Change a step that exists, keeping its key.

    PATCH rather than PUT, and the key is not in the body: the key is what workflow specs bind
    to, so a step's name can change without any workflow noticing and the key cannot change at
    all. The risk tier is still resolved from what the step binds, never accepted here — that
    is what stops editing a step being a way around the approval floor.
    """
    payload = payload.payload()
    from boss_engine.services import workflow_custom_steps as custom_steps

    project_id = str(payload.get("project_id") or "").strip()
    if not project_id:
        raise HTTPException(status_code=400, detail="project_id is required")
    actor = _delivery_workflow_actor(payload)
    # Only the fields actually sent are applied; anything absent keeps its current value, which
    # is what makes a rename safe to send on its own.
    optional = {
        name: payload[name]
        for name in ("label", "summary", "binding_kind", "skill_id", "mcp_server_id",
                     "mcp_tool_name", "inputs", "produces", "knowledge")
        if name in payload
    }
    try:
        with begin(engine) as connection:
            require_project_actor(connection, project_id, actor, "workflow_manage")
            return custom_steps.update(
                connection, project_id=project_id, step_key=step_key,
                actor=actor, **optional)
    except custom_steps.CustomStepError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error


@app.delete("/v1/delivery-workflows/custom-steps/{step_key}")
@permit(P.WORKFLOW_CREATE, scope=Scope.project(query="project_id"))
def delete_delivery_custom_step(step_key: str, project_id: str, actor: Optional[str] = None) -> dict:
    from boss_engine.services import workflow_custom_steps as custom_steps

    with begin(engine) as connection:
        resolved_actor = _delivery_workflow_actor(actor=actor)
        require_project_actor(connection, project_id, resolved_actor, "workflow_manage")
        removed = custom_steps.delete(connection, project_id, step_key, resolved_actor)
    if not removed:
        raise HTTPException(status_code=404, detail=f"no custom step '{step_key}'")
    return {"deleted": step_key}


