# Provider SLOs (BOSS-241 depth)


@app.get("/v1/provider-slos", response_model=ProviderSloListResponse)
@permit(P.MODEL_PROVIDER_READ, scope=Scope.project(query="project_id"))
def list_provider_slos(
    project_id: str,
    provider: Optional[str] = None,
    provider_account_id: Optional[str] = None,
    limit: int = 100,
    offset: int = 0,
) -> ProviderSloListResponse:
    """List provider SLO definitions for a project (BOSS-241 depth)."""
    if limit < 1 or limit > 500:
        raise HTTPException(status_code=400, detail="limit must be between 1 and 500.")
    if offset < 0:
        raise HTTPException(status_code=400, detail="offset must be >= 0.")
    with begin(engine) as connection:
        items = provider_slo.list_slos(
            connection,
            project_id,
            provider=provider,
            provider_account_id=provider_account_id,
            limit=limit,
            offset=offset,
        )
        return ProviderSloListResponse(
            project_id=project_id,
            items=[ProviderSloSummary(**item) for item in items],
            limit=limit,
            offset=offset,
        )


@app.post("/v1/provider-slos", response_model=ProviderSloSummary, status_code=201)
@permit(P.MODEL_PROVIDER_MANAGE, scope=Scope.project(body="project_id"))
def upsert_provider_slo(payload: ProviderSloUpsertRequest) -> ProviderSloSummary:
    """Create or update a provider SLO definition (BOSS-241 depth)."""
    with begin(engine) as connection:
        try:
            item = provider_slo.upsert_slo(
                connection,
                project_id=payload.project_id,
                provider=payload.provider,
                metric_key=payload.metric_key,
                target=payload.target,
                window_seconds=payload.window_seconds,
                comparator=payload.comparator,
                provider_account_id=payload.provider_account_id,
                metadata=payload.metadata,
                actor=payload.actor,
                slo_id=payload.slo_id,
            )
        except ValueError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        return ProviderSloSummary(**item)


@app.post("/v1/provider-slos/evaluate", response_model=ProviderSloEvaluateResponse)
@permit(P.SYSTEM_OPERATE, scope=Scope.project(body="project_id"))
def evaluate_provider_slos(payload: ProviderSloEvaluateRequest) -> ProviderSloEvaluateResponse:
    """Evaluate one or all provider SLOs for a project.

    Fail-closed: when no health/cost samples exist in the window, status is
    ``unknown`` (never silent success).
    """
    with begin(engine) as connection:
        try:
            if payload.slo_id:
                evaluation = provider_slo.evaluate_slo(
                    connection,
                    payload.slo_id,
                    project_id=payload.project_id,
                    actor=payload.actor,
                )
                summary = {
                    "ok": 1 if evaluation["status"] == "ok" else 0,
                    "breached": 1 if evaluation["status"] == "breached" else 0,
                    "unknown": 1 if evaluation["status"] == "unknown" else 0,
                }
                result = {
                    "project_id": payload.project_id,
                    "count": 1,
                    "summary": summary,
                    "evaluations": [evaluation],
                }
            else:
                result = provider_slo.evaluate_all_for_project(
                    connection,
                    payload.project_id,
                    actor=payload.actor,
                )
        except ValueError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error
        return ProviderSloEvaluateResponse(
            project_id=result["project_id"],
            count=result["count"],
            summary=result["summary"],
            evaluations=[
                ProviderSloEvaluationSummary(**item) for item in result["evaluations"]
            ],
        )








def _feature_entry_summary(row: dict[str, Any]) -> FeatureCatalogEntrySummary:
    return FeatureCatalogEntrySummary(
        id=row["id"],
        project_id=row["project_id"],
        label=row.get("label"),
        slug=row["slug"],
        title=row["title"],
        doc_path=row["doc_path"],
        status=row["status"],
        source=row.get("source"),
        implementation_files=row.get("implementation_files") or [],
        test_coverage=row.get("test_coverage") or [],
        source_refs=row.get("source_refs") or [],
        needs_label=bool(row.get("needs_label")),
        last_documented_event_id=row.get("last_documented_event_id"),
        last_documented_at=row.get("last_documented_at"),
        created_at=row["created_at"],
        updated_at=row["updated_at"],
        idempotent=bool(row.get("idempotent", False)),
    )


def _find_feature_entry(
    connection, project_id: str, label: str
) -> Optional[dict[str, Any]]:
    """Resolve a feature catalog entry by label, then slug, then id."""
    entries = feature_catalog.list_entries(connection, project_id)
    for entry in entries:
        if entry.get("label") == label:
            return entry
    for entry in entries:
        if entry.get("slug") == label or entry.get("id") == label:
            return entry
    return None


