@app.post("/v1/agents/{role_key}/persona/draft")
@permit(P.AGENT_CREATE, scope=Scope.project(body="project_id"))
def agent_persona_draft_endpoint(role_key: str, body: AgentPersonaDraftBody, request: Request = None):
    """`Draft it`: one model call in the agent's own composed voice. Saves nothing."""
    from boss_engine.services import agent_voice
    from boss_engine.services.agent_persona import lint_persona
    from boss_engine.services.core import emit_event
    from boss_engine.services.model_failures import explain

    who, row, spend = _agent_voice_gate(
        body.project_id, role_key, body.actor, body.persona, "model.agent_persona_draft",
        f"Draft {body.field} for {role_key}", request)
    try:
        raw, usage = spend.ask(system=agent_voice.system_prompt(
                                   row, _instructions_for(body.project_id, role_key, "chat")),
                               prompt=agent_voice.draft_prompt(body.field))
    except Exception as error:  # noqa: BLE001 — explained, never a bare 500
        spend.close(error=str(error))
        explanation = explain(error.__cause__ or error)
        if spend.uncertain:
            explanation = {**explanation, "retry": False,
                           "headline": "The model outcome is unknown. Reconcile its recorded receipt before retrying."}
        raise HTTPException(status_code=502, detail={"code": "model_failed",
                                                     "error": explanation}) from error
    finally:
        spend.close()
    draft = agent_voice.clip_draft(body.field, raw)
    errors, warnings = lint_persona({body.field: draft})
    with begin(engine) as connection:
        emit_event(connection, body.project_id, "agent.persona_drafted", who, "agent",
                   str(row.get("agent_id") or role_key),
                   {"role_key": role_key, "field": body.field, "receipt_id": spend.receipt_id,
                    "usage": usage})
    return {"role_key": role_key, "field": body.field, "draft": draft,
            "problems": errors, "warnings": warnings, "receipt_id": spend.receipt_id}


@app.post("/v1/agents/{role_key}/test")
@permit(P.AGENT_TEST, scope=Scope.project(body="project_id"))
def agent_voice_test_endpoint(role_key: str, body: AgentVoiceTestBody, request: Request = None):
    """`Test`: a probe, answered through the agent's exact composed prompt, streamed as SSE.

    Events: `token` {text}* then `result` {voice 0-5, in_remit, says_ai, fingerprint, …};
    or `error` {error: model_failures.explain()}. Refusals (no model, budget, a persona that
    fails the lint) are answered before the stream opens, as plain HTTP errors.
    """
    from boss_engine.services import agent_voice
    from boss_engine.services.core import emit_event
    from boss_engine.services.model_failures import explain

    who, row, spend = _agent_voice_gate(
        body.project_id, role_key, body.actor, body.persona, "model.agent_voice_test",
        f"Test {body.probe} for {role_key}", request)

    def sse(event: str, data: dict[str, Any]) -> str:
        return f"event: {event}\ndata: {json.dumps(data, default=str)}\n\n"

    def stream():
        completed = False
        # An observed generator interruption still closes the spend bookkeeping.
        # Network disconnect alone does not prove cancellation or provider rejection.
        try:
            # Standard SSE comment: no model result or authority claim. Starlette's
            # compression layer releases headers on the first body chunk even for SSE.
            yield ": voice intent admitted\n\n"
            try:
                reply, usage = spend.ask(system=agent_voice.system_prompt(
                                             row, _instructions_for(body.project_id, role_key,
                                                                    "chat")),
                                         prompt=agent_voice.PROBES[body.probe]["prompt"])
            except Exception as error:  # noqa: BLE001
                spend.close(error=str(error))
                explanation = explain(error.__cause__ or error)
                if spend.uncertain:
                    explanation = {**explanation, "retry": False,
                                   "headline": "The model outcome is unknown. Reconcile its recorded receipt before retrying.",
                                   "action": "Reconcile the recorded invocation receipts before retrying."}
                yield sse("error", {"error": explanation,
                                    "receipt_id": spend.receipt_id,
                                    "receipt_ids": spend.receipt_ids,
                                    "spend_status": "needs_reconciliation" if spend.uncertain else "refused"})
                completed = True
                return
            for piece in agent_voice.chunks(reply):
                yield sse("token", {"text": piece})
            judgement = None
            try:
                raw, _ = spend.ask(system="You grade replies. You output JSON only.",
                                   prompt=agent_voice.judge_prompt(row, body.probe, reply))
                judgement = agent_voice.parse_judgement(raw)
            except Exception:  # noqa: BLE001 — the plain checks still score it
                judgement = None
            spend.close()
            result = {**agent_voice.score(row, body.probe, reply, judgement),
                      "probe": body.probe, "fingerprint": row.get("fingerprint") or "",
                      "version": int(row.get("identity_version") or 1),
                      "draft": body.persona is not None, "receipt_id": spend.receipt_id,
                      "receipt_ids": spend.receipt_ids,
                      "spend_status": "needs_reconciliation" if spend.uncertain else "settled"}
            try:
                with begin(engine) as connection:
                    emit_event(connection, body.project_id, "agent.tested", who, "agent",
                               str(row.get("agent_id") or role_key),
                               {"role_key": role_key, **result, "usage": usage,
                                "model_calls": spend.calls,
                                "cost_usd_micros": spend.actual_usd_micros,
                                "reply": reply[:2000]})
            except Exception:  # noqa: BLE001 — the operator still gets the result
                logging.getLogger(__name__).warning("agent.tested not recorded", exc_info=True)
            yield sse("result", result)
            if spend.uncertain:
                # Preserve the usable reply/score, then expose the unsettled judgement
                # through the existing client's visible error channel as well.
                yield sse("error", {"error": {
                    "kind": "outcome_unknown", "retry": False,
                    "headline": "The judgement outcome is unknown. Reconcile its recorded receipt before retrying."},
                    "receipt_id": spend.receipt_id, "receipt_ids": spend.receipt_ids,
                    "spend_status": "needs_reconciliation"})
            completed = True
        finally:
            spend.close()
            if completed and request is not None:
                # Shared scope state reaches the outer recorder. Set it only after
                # the actual terminal yield was consumed and final close succeeded.
                request.state.voice_stream_completed = True

    # The background close covers a stream that was never started at all (idempotent).
    return StreamingResponse(stream(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
                             background=BackgroundTask(spend.close))
# --- end agent world: identity ---


# --- agent world: acts ---
# Signed work (spec §4.3, §5.4): an agent's acts and lineage, a run's chain, one act, who is live.
# Registered BEFORE the agents router so `/v1/agents/live` is not read as an agent called "live".


class ActsBackfillRequest(BaseModel):
    project_id: str
    actor: str = "executive_console"


def _acts_reader(project_id: str):
    if not database_is_reachable(engine):
        raise HTTPException(status_code=503, detail="Postgres is not reachable.")
    return project_id.strip()


def _acts_viewer(viewer: Optional[str]) -> Optional[str]:
    """Who is reading, so an edge a person made says "you" only to that person.

    The authenticated principal when there is one — a request cannot claim to be someone else.
    With API auth off every caller is the same process, so the console names its operator with
    `?viewer=`; with neither, every person is named, which is never wrong."""
    principal = current_api_principal.get()
    if principal:
        return str(principal)
    if current_transport_authenticated.get():
        return None
    return (viewer or "").strip() or None


@app.get("/v1/agents/live")
@permit(P.PROJECT_READ, scope=Scope.project(query="project_id"))
def agents_live(project_id: str, request: Request, response: Response):
    """Who is working, in a panel, or waiting on you right now. ETag'd for a cheap 4s poll.

    `attention` is what the pill counts: the things that need the operator — the Command
    Center's counts.needs_you, Agents › Live's cards and Approvals' Needs action plus failed
    steps, from the one list (agents_live_board.pill). It used to count AGENTS in a needs-you
    state, so three gates on one agent said 1 while Approvals said 3 (agents-home spec §6.3)."""
    import hashlib as _hashlib

    from boss_engine.services import agent_acts, agents_live_board

    project_id = _acts_reader(project_id)
    with begin(engine) as connection:
        require_project_reader(connection, project_id)
        live = agent_acts.live(connection, project_id)
        attention = agents_live_board.pill(connection, settings, project_id)
    etag = '"' + _hashlib.sha256(json.dumps(
        [live["etag"], attention["count"], [i["id"] for i in attention["items"]]]
    ).encode()).hexdigest()[:20] + '"'
    if request.headers.get("if-none-match") == etag:
        return Response(status_code=304, headers={"ETag": etag})
    response.headers["ETag"] = etag
    response.headers["Cache-Control"] = "no-cache"
    return _withhold_sections(request, project_id,
                              {"project_id": project_id, "items": live["items"], "attention": attention},
                              "/v1/agents/live")


@app.get("/v1/agents/live-board")
@permit(P.PROJECT_READ, scope=Scope.project(query="project_id"))
def agents_live_board_endpoint(project_id: str, request: Request, response: Response,
                               viewer: Optional[str] = None):
    """Agents › Live in one read: what needs you, what is moving, what got done, who is idle
    (agents-home spec §6.2). ETag'd: the tab polls it every 8s while it is visible, and an
    unchanged board is a 304. Composition only — see agents_live_board."""
    from boss_engine.services import agents_live_board

    project_id = _acts_reader(project_id)
    with begin(engine) as connection:
        require_project_reader(connection, project_id)
        board = agents_live_board.build(connection, settings, project_id,
                                        viewer=_acts_viewer(viewer))
    board = _withhold_sections(request, project_id, board, "/v1/agents/live-board")
    if request.headers.get("if-none-match") == board["etag"]:
        return Response(status_code=304, headers={"ETag": board["etag"]})
    response.headers["ETag"] = board["etag"]
    response.headers["Cache-Control"] = "no-cache"
    return board


