from .routers.identity_scim import build_identity_scim_router  # noqa: E402  (identity S1)
from .routers.identity_admin import build_identity_admin_router  # noqa: E402  (identity S5)
from .routers.identity_agents import build_identity_agents_router  # noqa: E402  (identity S3)
from .routers.identity_agents import install_consent_handler  # noqa: E402  (identity S3)
from .routers.identity_github import build_identity_github_router  # noqa: E402  (Setup › Repo: GitHub)
from boss_engine.identity.request_ids import RequestIdMiddleware  # noqa: E402  (identity S5)

app.include_router(build_identity_me_router())
app.include_router(build_identity_auth_router())
app.include_router(build_identity_people_router())
app.include_router(build_identity_sso_router())
app.include_router(build_identity_scim_router())
# S5's audit log, policy, posture, legacy paths and shadow report; building it starts the shadow
# ledger's flusher (not under pytest).
app.include_router(build_identity_admin_router())
app.include_router(build_identity_agents_router())
app.include_router(build_identity_github_router())
# A covering grant is missing: a flat 409 {"error": "consent_required", ...} the console's consent
# sheet reads, wherever a build or run start raises it.
install_consent_handler(app)
from .routers.identity_access import build_identity_access_router  # noqa: E402  (identity S2)

app.include_router(build_identity_access_router(engine))
# One request id per request (outermost, pure ASGI): on every security event and echoed back.
app.add_middleware(RequestIdMiddleware)
# What each request cost (SQL statements, their time, the identity guard's share): outermost, so it
# sees everything; emitted as Server-Timing under BOSS_SERVER_TIMING, read by the budget tests.
from .request_metrics import RequestMetricsMiddleware  # noqa: E402

app.add_middleware(RequestMetricsMiddleware)
# Identity facts read once per request (session, principal status, epoch, project's org), not once
# per check: boss_engine/identity/request_memo.py. Outermost, so the transport step, the guard and
# the handler all share the request's one memo.
from boss_engine.identity.request_memo import RequestMemoMiddleware  # noqa: E402

app.add_middleware(RequestMemoMiddleware)
from .routers.identity_access import declare_framework_routes  # noqa: E402  (identity S2)

declare_framework_routes(app)

# The app platform (docs/product/APP_TEMPLATES_AND_SECURITY_LOOP.md §8.2): one router module per
# feature, each owned by its stream. Day-1 stubs answer 501 not_implemented_yet.
from .routes_templates import build_templates_router  # noqa: E402  (F2, stream S2)
from .routes_security import build_security_router  # noqa: E402  (F4, stream S4)
from .routes_links import build_links_router  # noqa: E402  (F5, stream S5)
from .oidc_routes import build_oidc_router  # noqa: E402  (F6, stream S6)

app.include_router(build_templates_router())
app.include_router(build_security_router())
app.include_router(build_links_router())
app.include_router(build_oidc_router())
from .routes_multirepo import build_multirepo_router  # noqa: E402  (multi-repo apps)

app.include_router(build_multirepo_router())
from .routes_infra_platform import build_infra_platform_router  # noqa: E402  (infra plugins)

app.include_router(build_infra_platform_router())

paid_router = None
mount_edition_routers(app, settings.boss_edition, paid_router=paid_router)

# BOOT-TIME COVERAGE CHECK (IDENTITY.md §6.3, D5): every route must declare @permit, @public or
# @authenticated. Under BOSS_AUTHZ_COVERAGE=fail (the default once BOSS_AUTHZ_MODE=enforce) an
# undeclared route stops the API from starting; in shadow it is listed in the boot log.
identity_guard.check_app_coverage(app)


# FastAPI gives a multi-method route one ID for all of its methods. The public
# OpenAPI contract must give each HTTP operation its own stable name so TUI,
# MCP, generated clients, and humans can address the same capability.
_native_openapi = app.openapi


def _openapi_with_stable_operation_ids() -> dict[str, Any]:
    import warnings

    from boss_engine.services.api_operation_ids import stable_operation_ids

    # The preview proxy intentionally accepts several verbs on one route.
    # FastAPI warns while assigning one temporary ID to all of them; below we
    # replace those IDs with distinct method+path names before publication.
    with warnings.catch_warnings():
        warnings.filterwarnings(
            "ignore",
            message=r"Duplicate Operation ID preview_web_proxy_",
            category=UserWarning,
            module=r"fastapi\.openapi\.utils",
        )
        document = _native_openapi()
    stable_operation_ids(document)
    return document


app.openapi = _openapi_with_stable_operation_ids
